      if (!styled) {
        styled = true;
        try {
          const st = document.createElement('style');
          st.textContent = '.sonic-ri{display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto;vertical-align:middle}.sonic-ri img,.sonic-ri resource-icon{display:block;width:100%;height:100%;object-fit:contain;background-size:contain;background-repeat:no-repeat;background-position:center}.sonic-ri.fallback{border-radius:50%;background:var(--rc);box-shadow:0 0 5px var(--rc);width:10px!important;height:10px!important}.sonic-ri.fallback resource-icon{display:none}';
          (document.head || document.documentElement).appendChild(st);
        } catch (_) {}
      }
