      try { o.chain = JSON.parse(sessionStorage.getItem('SoNiC_LastChainAction_V1') || 'null'); } catch (_) {}
      try { o.autoRun = JSON.parse(sessionStorage.getItem('SoNiC_CollectAutoRun_V1') || 'null'); } catch (_) {}
