    window.SoNiCDebug.lfRaw = () => { try { const j = window.__sonicLfRaw; if (!j) return "(aucune réponse reçue)"; return "clés: " + Object.keys(j).join(",") + " | data: " + (j.data ? Object.keys(j.data).join(",") : "ABSENT") + " | classe603=" + JSON.stringify(j.data?.characterclasses?.["603"]?.totalBonus) + " | expe=" + JSON.stringify(j.data?.expedition?.ResultBooster?.totalBonus); } catch (e) { return String(e); } };
    window.SoNiCDebug.launchProbe = (v) => { try { localStorage.setItem(FLAG, v === false ? '0' : '1'); if (v === false) return 'journal désactivé'; } catch (_) {} return 'journal activé : fais ton enchaînement de pillages puis tape SoNiCDebug.launchLog()'; };
    window.SoNiCDebug.launchLogClear = () => { try { localStorage.removeItem(KEY); } catch (_) {} return 'journal vidé'; };
