function sonicLang(){
  try {
    const saved = localStorage.getItem("SoNiC_Suite_Language");
    if (saved && SONIC_I18N[saved]) return saved;
  } catch (_) {}
  return String(document.documentElement?.lang || document.body?.lang || 'fr').slice(0,2).toLowerCase();
}
window.sonicLocale = () => { try { return sonicLang() === "en" ? "en-GB" : "fr-FR"; } catch (_) { return "fr-FR"; } };
function sonicT(key){ const fr=SONIC_I18N.fr; const lang=SONIC_I18N[sonicLang()]||fr; return lang[key] ?? fr[key] ?? key; }
