      if (!document.getElementById("sonic-confirm-css")) {
        const st = document.createElement("style"); st.id = "sonic-confirm-css";
        st.textContent = "#sonic-confirm{position:fixed!important;top:0!important;left:0!important;right:auto!important;bottom:auto!important;width:100vw!important;height:100vh!important;margin:0!important;padding:0!important;transform:none!important;z-index:2147483600!important;display:flex!important;align-items:center!important;justify-content:center!important;background:rgba(0,4,10,.62);font:12px Arial,sans-serif}#sonic-confirm .sc-box{margin:0!important;flex:0 0 auto;width:min(380px,92vw);background:linear-gradient(180deg,#0c2233,#050c13);border:1px solid #2a789b;border-radius:8px;box-shadow:0 12px 40px rgba(0,0,0,.65),0 0 0 1px rgba(255,210,80,.12);color:#dbeaf2;overflow:hidden}#sonic-confirm .sc-head{padding:9px 14px;border-bottom:1px solid #174e67;background:linear-gradient(180deg,#102c40,#081720);color:#ffd75a;font-weight:700;letter-spacing:.5px}#sonic-confirm .sc-body{padding:14px;line-height:1.5}#sonic-confirm .sc-body b{color:#ffd75a}#sonic-confirm .sc-foot{display:flex;justify-content:flex-end;gap:8px;padding:0 14px 12px}#sonic-confirm button{border:1px solid #235d7a;border-radius:4px;background:#081722;color:#cce7f3;cursor:pointer;font:700 11px Arial,sans-serif;padding:6px 14px}#sonic-confirm button:hover{border-color:#55cfff}#sonic-confirm button.sc-ok{border-color:#a8453f;background:#3a1412;color:#ffd0cc}#sonic-confirm button.sc-ok:hover{border-color:#ff7b72;background:#521a17}";
        (document.head || document.documentElement).appendChild(st);
      }
      const esc = (v) => String(v).replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
      const wrap = document.createElement("div"); wrap.id = "sonic-confirm";
