    const pick = (e) => { const r = sv.getBoundingClientRect(); hsv[1] = Math.max(0, Math.min(1, (e.clientX - r.left) / r.width)); hsv[2] = 1 - Math.max(0, Math.min(1, (e.clientY - r.top) / r.height)); paint(true); };
    sv.addEventListener("pointerdown", (e) => { e.preventDefault(); sv.setPointerCapture(e.pointerId); pick(e); const mv = (ev) => pick(ev); const up = () => { sv.removeEventListener("pointermove", mv); sv.removeEventListener("pointerup", up); }; sv.addEventListener("pointermove", mv); sv.addEventListener("pointerup", up); });
    hue.addEventListener("input", () => { hsv[0] = Number(hue.value); paint(true); });
    hexIn.addEventListener("input", () => { let v = hexIn.value.trim(); if (v[0] !== "#") v = "#" + v; if (/^#[0-9a-f]{6}$/i.test(v)) { cur = v.toLowerCase(); paint(false); } });
    const done = (v) => { try { document.removeEventListener("keydown", onKey, true); wrap.remove(); } catch (_) {} resolve(v); };
    const onKey = (e) => { if (e.key === "Escape") { e.preventDefault(); e.stopPropagation(); done(null); } else if (e.key === "Enter") { e.preventDefault(); e.stopPropagation(); done(cur); } };
