    wrap.addEventListener("mousedown", (e) => { if (e.target === wrap) done(null); });
    wrap.querySelector(".pl-cancel").addEventListener("click", () => done(null));
    wrap.querySelector(".pl-ok").addEventListener("click", () => done(cur));
    document.addEventListener("keydown", onKey, true);
