  const OURS = '[id^="sonic"],[id*="-sonic"],[class*="sonic-"],[class*="sonic_"],[id^="sx-"],[class*=" sx-"],[class^="sx-"],[class^="sa-"],[class*=" sa-"],[id^="sv"],[class^="sv-"],[class*=" sv-"],[class*="sv40"],[id^="sv40"]';
