  const SONIC_SHIP_MSU_RATIO_KEY = "SoNiC_Suite_ShipMSURatio";
  const SONIC_SHIP_MSU_RATIOS = Object.freeze({
    "3:2:1": Object.freeze([3, 2, 1]),
    "1:1:1": Object.freeze([1, 1, 1]),
  });

  function sonicShipMsuGetMode() {
    try {
      const saved = localStorage.getItem(SONIC_SHIP_MSU_RATIO_KEY);
      return SONIC_SHIP_MSU_RATIOS[saved] ? saved : "3:2:1";
    } catch (_) {
      return "3:2:1";
    }
  }

  function sonicShipMsuSetMode(mode) {
    const next = SONIC_SHIP_MSU_RATIOS[mode] ? mode : "3:2:1";
    try { localStorage.setItem(SONIC_SHIP_MSU_RATIO_KEY, next); } catch (_) {}
    try {
      window.dispatchEvent(new CustomEvent("sonic:ship-msu-ratio-changed", {
        detail: { mode: next },
      }));
    } catch (_) {}
    return next;
  }

  function sonicShipMsuValue(composition, mode = sonicShipMsuGetMode()) {
    const ratio = SONIC_SHIP_MSU_RATIOS[mode] || SONIC_SHIP_MSU_RATIOS["3:2:1"];
    return Object.entries(composition || {}).reduce((total, [id, amount]) => {
      const cost = EXPEDITION_SHIP_COSTS[id];
      const count = Math.max(0, Number(amount) || 0);
      if (!cost || !count) return total;
      return total + count * (
        Number(cost[0] || 0) * ratio[0] +
        Number(cost[1] || 0) * ratio[1] +
        Number(cost[2] || 0) * ratio[2]
      );
    }, 0);
  }

