    const en = (() => { try { return sonicLang() === "en"; } catch (_) { return false; } })();
    const fmtT = (sec) => { const d = Math.floor(sec / 86400), h = Math.floor(sec % 86400 / 3600), m = Math.floor(sec % 3600 / 60); return d ? d + (en ? "d " : "j ") + h + "h" : h ? h + "h" + String(m).padStart(2, "0") : Math.max(1, m) + " min"; };
    const names = en ? { metal: "metal", crystal: "crystal", deuterium: "deuterium" } : { metal: "métal", crystal: "cristal", deuterium: "deutérium" };
