      const up = () => { document.removeEventListener("pointermove", mv, true); document.removeEventListener("pointerup", up, true); const b = panel.getBoundingClientRect(); saveUi({ left: b.left, top: b.top }); };
      document.addEventListener("pointermove", mv, true);
