    function getSharedExpeditionPreviewValue() {
      const raw = String(expeditionValueInput.value || "").trim();
      const automatic = calcExpeditionAutomaticMax().max;
      if (!raw) return automatic;
      if (raw.endsWith("%")) {
        const percent = Number(raw.slice(0, -1).replace(",", "."));
        return Number.isFinite(percent) && percent > 0
          ? Math.round(automatic * percent / 100)
          : automatic;
      }
      const value = Number(raw.replace(/[^\d.,-]/g, "").replace(",", "."));
      return Number.isFinite(value) && value > 0 ? Math.round(value) : automatic;
    }

