    addDom("div", { text: "🔗 Lien de transfert des réglages (PC ↔ téléphone)", parent: panel, style: "margin:8px 0 2px; font-weight:bold; color:var(--sonic-gold);" });
    const xferTa = addDom("textarea", { attrs: { rows: "2", placeholder: "Lien ou code SONIC…", spellcheck: "false" }, style: "width:100%; box-sizing:border-box; color:#f2f7fb !important; background:#0b121a !important; border:1px solid rgba(255,215,0,.42); padding:4px 6px; font:11px monospace;", parent: panel });
    addDom("div", { text: "Exporter : crée un lien (copié). Ouvrez-le sur le téléphone, connecté au même univers : un clic applique vos réglages. Importer : colle ici un lien ou un code reçu.", parent: panel, style: "font-size:10px; color:var(--sonic-text-dim); line-height:1.35; margin:0 0 2px;" });
    const XFER_KEY = "SoNiC_Suite_XferText";
