    const xferRow = addDom("div", { style: "display:flex; gap:6px; margin:4px 0 8px;", parent: panel });
    const xferExp = addDom("button", { text: "Exporter", attrs: { type: "button", title: "Crée un lien contenant vos réglages (copié dans le presse-papiers). Ouvrez-le sur l'autre appareil : un clic applique tout." }, style: "flex:1; cursor:pointer;", parent: xferRow });
    const xferImp = addDom("button", { text: "Importer", attrs: { type: "button", title: "Applique les réglages du lien ou du code collé ci-dessus, puis recharge la page." }, style: "flex:1; cursor:pointer;", parent: xferRow });
