  // Vérification de la version disponible (au plus une fois toutes les 12 h, avec les mises à jour de l'API de l'univers).
  const SONIC_UPDATE_RAW = "https://raw.githubusercontent.com/sonicfr-jpg/SoNiC/main/SoNiC_0game.user.js";
  const SONIC_UPDATE_KEY = "SoNiC_Suite_UpdateCheck";
  function sonicVersionNewer(a, b) {
    const pa = String(a).split(/[^0-9]+/).filter(Boolean).map(Number), pb = String(b).split(/[^0-9]+/).filter(Boolean).map(Number);
    for (let i = 0; i < Math.max(pa.length, pb.length); i++) { const d = (pa[i] || 0) - (pb[i] || 0); if (d) return d > 0; }
    return false;
  }
  async function sonicCheckScriptUpdate() {
    try {
      const st = loadJSON(SONIC_UPDATE_KEY, {}) || {};
      if (Date.now() - Number(st.checkedAt || 0) < 12 * 3600 * 1000) return;
      st.checkedAt = Date.now();
      saveJSON(SONIC_UPDATE_KEY, st);
      const res = await fetch(SONIC_UPDATE_RAW, { cache: "no-store" });
      if (!res.ok) return;
      const m = (await res.text()).match(/@version\s+([^\s]+)/);
      if (!m) return;
      st.latest = m[1];
      st.available = sonicVersionNewer(m[1], "1.0.0");
      saveJSON(SONIC_UPDATE_KEY, st);
      if (st.available && st.notified !== m[1]) {
        st.notified = m[1];
        saveJSON(SONIC_UPDATE_KEY, st);
        try { showToast(`SoNiC : version ${m[1]} disponible (bouton ⬆ des options)`); } catch (_) {}
      }
    } catch (_) {}
  }
  setTimeout(sonicCheckScriptUpdate, 4000);
