  function setNativeSpyMessagesHidden(hidden){
    const selectors=["#messagewrapper .msg[data-msg-id]","#messagescomponent .msg[data-msg-id]","#messagecontainercomponent .msg[data-msg-id]",".msg[data-msg-id]"];
    const seen=new Set();
    selectors.forEach(selector=>document.querySelectorAll(selector).forEach(el=>{
      if(seen.has(el))return;
      seen.add(el);
      if(hidden){
        el.classList.add("sonic-native-spy-hidden");
        el.setAttribute("aria-hidden","true");
      }else{
        el.classList.remove("sonic-native-spy-hidden");
        el.removeAttribute("aria-hidden");
      }
    }));
  }
  const SONIC_INACTIVE_RAID_CHAIN_KEY = "SoNiC_Suite_InactiveRaidChain";
  const SONIC_RAID_BURST_COOLDOWN_MS = 2200;
  function sonicLoadInactiveRaidChain() {
    try {
      const raw = sessionStorage.getItem(SONIC_INACTIVE_RAID_CHAIN_KEY);
      const state = raw ? JSON.parse(raw) : null;
      return state && typeof state === "object"
        ? {
            done: Array.isArray(state.done) ? state.done.map(String) : [],
            activeMessageId: state.activeMessageId ? String(state.activeMessageId) : null,
            sendInitiated: !!state.sendInitiated,
            raidBurstUntil: Number(state.raidBurstUntil) || 0,
          }
        : { done: [], activeMessageId: null, sendInitiated: false, raidBurstUntil: 0 };
    } catch (_) {
      return { done: [], activeMessageId: null, sendInitiated: false, raidBurstUntil: 0 };
    }
  }
  function sonicRaidBurstUntil() {
    return Number(sonicLoadInactiveRaidChain().raidBurstUntil) || 0;
  }
  function sonicRaidBurstCoolingDown() {
    return Date.now() < sonicRaidBurstUntil();
  }
  function sonicScheduleRaidBurstStatsFlush() {
    const until = sonicRaidBurstUntil();
    if (until <= Date.now()) return;
    if (window.__sonicRaidBurstStatsTimer) clearTimeout(window.__sonicRaidBurstStatsTimer);
    window.__sonicRaidBurstStatsTimer = window.setTimeout(() => {
      window.__sonicRaidBurstStatsTimer = 0;
      try {
        const rows = sonicEconomyReadCurrentMessageRows([22, 21, 24]);
        sonicEconomySync({ rows, refreshPanel: false });
        try { refreshExpeditionDisplay(); } catch (_) {}
        try { sonicEconomyRefreshPanel(false); } catch (_) {}
      } catch (error) {
        console.warn("[SoNiC Raid] Actualisation différée des statistiques impossible :", error);
      }
    }, Math.max(50, until - Date.now() + 50));
  }
  function sonicSaveInactiveRaidChain(state) {
    try { sessionStorage.setItem(SONIC_INACTIVE_RAID_CHAIN_KEY, JSON.stringify(state)); } catch (_) {}
  }
  function sonicResetInactiveRaidChain() {
    try { sessionStorage.removeItem(SONIC_INACTIVE_RAID_CHAIN_KEY); } catch (_) {}
    document.querySelectorAll("#sonic-spytable .sonic-inactive-armed").forEach((el) => el.classList.remove("sonic-inactive-armed"));
  }
  function sonicInactiveRaidAssistEnabled() {
    return settings.inactiveRaidAssistEnabled !== false;
  }
  function sonicMarkInactiveRaidSendInitiated() {
    if (!sonicInactiveRaidAssistEnabled()) return;
    const state = sonicLoadInactiveRaidChain();
    if (!state.activeMessageId) return;
    const id = String(state.activeMessageId);
    if (!state.done.includes(id)) state.done.push(id);
    state.sendInitiated = true;
    sonicSaveInactiveRaidChain(state);
    try { localStorage.setItem("SoNiC_Suite_RaidLastSend", String(Date.now())); } catch (_) {}
  }
  // Défilement vers la cible suivante : option désactivée par défaut ; limité à N minutes après le dernier envoi (0 = sans limite) pour ne pas gêner hors session de pillage.
  function sonicRaidScrollAllowed() {
    try {
      const st = loadSettings();
      if (st.raidChainScroll !== true) return false;
      const sec = Number.isFinite(Number(st.raidChainScrollSeconds)) && st.raidChainScrollSeconds !== undefined ? Math.max(0, Number(st.raidChainScrollSeconds)) : Math.max(0, (Number(st.raidChainScrollMinutes) || 0) * 60 || 1800);
      if (!sec) return true;
      const last = Number(localStorage.getItem("SoNiC_Suite_RaidLastSend")) || 0;
      return last > 0 && Date.now() - last <= sec * 1000;
    } catch (_) { return false; }
  }
  function sonicMarkInactiveRaidCompletedOnReturn() {
    if (!sonicInactiveRaidAssistEnabled()) return;
    const state = sonicLoadInactiveRaidChain();
    if (!state.activeMessageId || !state.sendInitiated) return;
    const id = String(state.activeMessageId);
    if (!state.done.includes(id)) state.done.push(id);
    state.activeMessageId = null;
    state.sendInitiated = false;
    state.raidBurstUntil = Date.now() + SONIC_RAID_BURST_COOLDOWN_MS;
    sonicSaveInactiveRaidChain(state);
  }
  function sonicArmInactiveRaidByMessageId(messageId, focus = true) {
    if (!isMessagesPage() || !sonicInactiveRaidAssistEnabled()) return false;
    const id = String(messageId || "");
    const table = document.getElementById("sonic-spytable");
    if (!table) return false;

    let row = Array.from(table.querySelectorAll('.sonic-spyRow[data-message-id]'))
      .find((el) => String(el.dataset.messageId || "") === id);

    if (!row) return false;

    const attack = row.querySelector('[data-sonic-inactive-attack="1"]');
    if (!attack) return false;
    table.querySelectorAll(".sonic-inactive-armed").forEach((el) => el.classList.remove("sonic-inactive-armed"));
    row.classList.add("sonic-inactive-armed");
    const state = sonicLoadInactiveRaidChain();
    state.activeMessageId = id;
    state.sendInitiated = false;
    sonicSaveInactiveRaidChain(state);
    if (focus) {
      try {
        // Défilement uniquement si l'option est cochée (et pendant la session de pillage) ; sinon la page reste où elle est.
        if (sonicRaidScrollAllowed()) {
          const r = row.getBoundingClientRect(), vh = window.innerHeight || document.documentElement.clientHeight;
          if (r.top < 60 || r.bottom > vh - 20) row.scrollIntoView({ block: "center", behavior: "auto" });
        }
      } catch (_) {}
      try { attack.focus({ preventScroll: true }); } catch (_) {}
    }
    return true;
  }
  // Lignes affichées dans l'ordre visuel (tri courant), éligibles à l'enchaînement.
  function sonicGetDisplayedRaidRows() {
    const table = document.getElementById("sonic-spytable");
    if (!table) return [];
    return Array.from(table.querySelectorAll(":scope > .sonic-spyLines > .sonic-spyRow[data-message-id]"))
      .filter((row) =>
        row.dataset.messageId &&
        (row.dataset.sonicInactive === "1" || row.dataset.sonicActiveRaid === "1") &&
        row.dataset.sonicRaidRuleAction !== "next" &&
        row.querySelector('[data-sonic-inactive-attack="1"]'));
  }
  function sonicArmNextInactiveRaid(opts) {
    if (!isMessagesPage() || !sonicInactiveRaidAssistEnabled()) return;
    const rows = sonicGetDisplayedRaidRows();
    if (!rows.length) return;
    const state = sonicLoadInactiveRaidChain();
    let done = new Set(state.done.map(String));
    // Aucune cible déjà armée en attente d'envoi : on prend la 1re ligne affichée non traitée.
    const manualId = String(window.__sonicRaidManualPick || "");
    let next = manualId ? rows.find((row) => String(row.dataset.messageId) === manualId && !done.has(manualId)) : null;
    if (!next) { window.__sonicRaidManualPick = ""; next = rows.find((row) => !done.has(String(row.dataset.messageId))); }
    if (!next) {
      state.done = [];
      state.activeMessageId = null;
      state.sendInitiated = false;
      sonicSaveInactiveRaidChain(state);
      next = rows[0];
    }
    if (!next) return;
    const id = String(next.dataset.messageId);
    const alreadyArmed = next.classList.contains("sonic-inactive-armed") && String(state.activeMessageId || "") === id;
    if (alreadyArmed) return;
    const firstShown = rows[0] === next;
    sonicArmInactiveRaidByMessageId(id, !firstShown || !(opts && opts.noScrollTop));
  }
  function sonicMoveInactiveRaidSelection(direction) {
    if (!isMessagesPage() || !sonicInactiveRaidAssistEnabled()) return false;
    const table = document.getElementById("sonic-spytable");
    if (!table) return false;

    const rows = Array.from(
      table.querySelectorAll(':scope > .sonic-spyLines > .sonic-spyRow[data-message-id]')
    );
    const renderedIds = rows.map((row) => String(row.dataset.messageId || "")).filter(Boolean);
    if (!renderedIds.length) return false;

    const state = sonicLoadInactiveRaidChain();
    const currentId = String(state.activeMessageId || "");
    let currentIndex = renderedIds.indexOf(currentId);
    if (currentIndex < 0) currentIndex = direction > 0 ? -1 : 0;

    let nextIndex = currentIndex + (direction > 0 ? 1 : -1);
    if (nextIndex < 0) nextIndex = renderedIds.length - 1;
    if (nextIndex >= renderedIds.length) nextIndex = 0;

    window.__sonicRaidManualPick = renderedIds[nextIndex];
    return sonicArmInactiveRaidByMessageId(renderedIds[nextIndex], true);
  }
  function sonicPrepareInactiveRaid(data) {
    if (!sonicInactiveRaidAssistEnabled() || !data || !/inactif/i.test(data.playerStatus?.label || "") || !data.messageId) return;
    const state = sonicLoadInactiveRaidChain();
    state.activeMessageId = String(data.messageId);
    state.sendInitiated = false;
    sonicSaveInactiveRaidChain(state);
  }

  function syncNativeSpySelectionTools(reports) {
    const root = findNativeMessagesRoot();
    if (!root) return;
    const submenu = root.querySelector(":scope > .tabsWrapperSubMenu");
    if (!submenu) return;

    let tools = submenu.querySelector(":scope > .sonic-spySelectionTools");
    if (!reports?.length) {
      tools?.remove();
      sonicSpySelectedMessageIds.clear();
      return;
    }

    const ids = reports.map((data) => String(data.messageId || "")).filter(Boolean);
    const selected = ids.filter((id) => sonicSpySelectedMessageIds.has(id));

    if (!tools) {
      tools = document.createElement("div");
      tools.className = "sonic-spySelectionTools";
      const nativeDeleteAll = submenu.querySelector(":scope > .deleteAll");
      if (nativeDeleteAll?.nextSibling) submenu.insertBefore(tools, nativeDeleteAll.nextSibling);
      else submenu.appendChild(tools);
    }

    tools.replaceChildren();

    const label = document.createElement("label");
    label.className = "sonic-spySelectionLabel";
    label.title = "Sélectionner tous les rapports de la page OGame";

    const selectAll = document.createElement("input");
    selectAll.type = "checkbox";
    selectAll.className = "sonic-spySelectAll";
    selectAll.checked = ids.length > 0 && selected.length === ids.length;
    selectAll.indeterminate = selected.length > 0 && selected.length < ids.length;

    const text = document.createElement("span");
    text.textContent = "0_Game : sélectionner";

    label.append(selectAll, text);
    tools.appendChild(label);

    const deleteSelected = document.createElement("button");
    deleteSelected.type = "button";
    deleteSelected.className = "custom_btn sonic-spyDeleteSelected";
    deleteSelected.textContent = "Supprimer";
    deleteSelected.title = "Supprimer les messages sélectionnés";
    deleteSelected.disabled = sonicSpySelectedMessageIds.size === 0 || sonicSpyDeleting;
    tools.appendChild(deleteSelected);

    selectAll.addEventListener("change", (event) => {
      event.preventDefault();
      event.stopPropagation();
      if (selectAll.checked) ids.forEach((id) => sonicSpySelectedMessageIds.add(id));
      else ids.forEach((id) => sonicSpySelectedMessageIds.delete(id));
      syncNativeSpySelectionTools(reports);
      document.querySelectorAll("#sonic-spytable .sonic-spySelect[data-message-id]").forEach((box) => {
        box.checked = sonicSpySelectedMessageIds.has(String(box.dataset.messageId || ""));
      });
    });

    deleteSelected.addEventListener("click", (event) => {
      event.preventDefault();
      event.stopPropagation();
      sonicDeleteSelectedMessages(Array.from(sonicSpySelectedMessageIds));
    });
  }

