  function updateSpyActivity(el){if(!el)return;const raw=el.dataset.activityStart;if(!raw){el.textContent="";el.classList.remove("is-red","is-orange");el.classList.add("is-empty");return}const start=Number(raw);if(!Number.isFinite(start)){el.textContent="";el.classList.add("is-empty");return}const minutes=Math.floor(Math.max(0,Date.now()-start)/60000);el.classList.remove("is-red","is-orange","is-empty");if(minutes>=60){el.textContent="";el.classList.add("is-empty");return}el.textContent=`(${minutes})`;el.classList.add(minutes>=15?"is-orange":"is-red")}
  function observeMessages() {
    if (!isMessagesPage()) return;
    const container = findMessagesContainer();
    if (!container) { setTimeout(observeMessages,150); return; }
    try { sonicInstallSpyOverlayWatcher(); } catch (_) {}
    syncSpyNativePresentation(container);
    let pending = null;
    let isRendering = false;
    const scheduleRender = () => {
      if (pending || isRendering) return;
      pending = setTimeout(() => {
        pending = null;
        isRendering = true;
        try {
          renderSpyTable();
          refreshExpeditionDisplay();
          if (document.querySelector(".msg[data-msg-id], #sonic-spytable")) {
            requestAnimationFrame(() => window.__sonicMessagesCurtainReveal?.());
          }
        } catch (error) {
        } finally {
          isRendering = false;
        }
      }, settings.spyTurboMode !== false ? 45 : 400);
    };
    const observer = new MutationObserver((mutations) => {
      const relevant = mutations.some((mutation) => {
        if (
          mutation.target instanceof Element &&
          mutation.target.closest("#sonic-spytable")
        ) {
          return false;
        }
        return mutation.type === "childList" && (
          Array.from(mutation.addedNodes).some(node => node instanceof Element && !node.closest?.("#sonic-spytable") && (node.matches?.(".msg[data-msg-id]") || node.querySelector?.(".msg[data-msg-id]"))) ||
          Array.from(mutation.removedNodes).some(node => node instanceof Element && node.matches?.(".msg[data-msg-id]"))
        );
      });
      if (relevant) scheduleRender();
    });
    observer.observe(container, { childList: true, subtree: true });
  }
  const SONIC_EXP_RESULT_TYPES = {
    ressources: "resource",
    darkmatter: "darkmatter",
    nothing: "nothing",
    shipwrecks: "ship",
    trader: "trader",
    items: "item",
    fleetLost: "blackhole",
    combatPirates: "pirate",
    combatAliens: "alien",
  };
  function sonicExpParseDelay(rawData) {
    try {
      return JSON.parse(
        rawData.dataset.rawNavigation ||
          '{"returnTimeAbsoluteIncreaseHours":0,"returnTimeMultiplier":1}',
      );
    } catch (error) {
      return { returnTimeAbsoluteIncreaseHours: 0, returnTimeMultiplier: 1 };
    }
  }
  function sonicExpResolveResultType(rawExpeditionResult, delay) {
    if (rawExpeditionResult && SONIC_EXP_RESULT_TYPES[rawExpeditionResult]) {
      return SONIC_EXP_RESULT_TYPES[rawExpeditionResult];
    }
    const multiplier = Number(delay.returnTimeMultiplier);
    const absoluteIncrease = Number(delay.returnTimeAbsoluteIncreaseHours);
    if (multiplier < 1) return "early";
    if (multiplier > 1 || absoluteIncrease > 0) return "late";
    return rawExpeditionResult || "unknown";
  }
  function sonicExpParseJson(raw, fallback) {
    if (!raw) return fallback;
    try {
      return JSON.parse(raw);
    } catch (error) {
      return fallback;
    }
  }
  const SONIC_EXP_SHIP_IMAGE_INDEX_V17 = Object.freeze({
    204: 0,
    205: 1,
    206: 2,
    207: 3,
    215: 4,
    211: 5,
    213: 6,
    214: 7,
    202: 8,
    203: 9,
    208: 10,
    209: 11,
    210: 12,
    212: 13,
    218: 14,
    219: 15,
    217: 16,
  });
    // Icônes de vaisseaux : hébergées dans le dépôt (window.SONIC_ASSETS.shipIconsBase + 'ship-<id>.png').

  function sonicExpNormalizeShipSources(rawData) {
    const sources = [
      sonicExpParseJson(rawData.dataset.rawShipsfound, {}),
      sonicExpParseJson(rawData.dataset.rawShipsFound, {}),
      sonicExpParseJson(rawData.dataset.rawShipsgained, {}),
      sonicExpParseJson(rawData.dataset.rawTechnologiesgained, {}),
    ].filter(source => source && typeof source === "object" && !Array.isArray(source));

    const source = sources.find(value => Object.keys(value).length > 0) || {};
    const result = {};
    Object.entries(source).forEach(([shipId, info]) => {
      if (!(String(shipId) in SONIC_EXP_SHIP_IMAGE_INDEX_V17)) return;
      const amount = info && typeof info === "object"
        ? (info.amount ?? info.count ?? info.quantity ?? 0)
        : info;
      const n = Number(amount);
      if (!Number.isFinite(n) || n <= 0) return;
      result[String(shipId)] = (result[String(shipId)] || 0) + n;
    });
    return result;
  }

  function sonicExpNormText(value) {
    return String(value || "")
      .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
      .replace(/[`'\u2019\u00b4]/g, "")
      .toLowerCase();
  }

  function sonicExpFindNativeHeader(row) {
    if (!row) return null;
    for (const el of row.querySelectorAll("*")) {
      if (el.closest(".sonic-exp-result")) continue;
      if (el.children.length > 1) continue;
      if (sonicExpNormText(el.textContent).trim() === "butin") return el;
    }
    return null;
  }

  function sonicExpHideNativeByAmount(row, entries) {
    if (!row || !entries?.length) return;

    const header = sonicExpFindNativeHeader(row);
    const digitsOnly = s => String(s || "").replace(/[^\d]/g, "");
    const candidates = row.querySelectorAll("span,li,div,td,tr,p,b,strong,dd,dt,fieldset");

    candidates.forEach(el => {
      if (el === row || el === header) return;
      if (header && el.contains(header)) return;
      if (el.closest(".sonic-exp-result")) return;
      if (el.querySelector(".sonic-exp-result")) return;
      if (el.querySelector(".rawMessageData") || el.classList.contains("rawMessageData")) return;
      if (el.dataset.sonicNativeHidden === "1") return;

      const rawText = el.textContent || "";
      if (!rawText || rawText.length > 220) return;

      const text = sonicExpNormText(rawText);
      const digits = digitsOnly(rawText);
      const cls = sonicExpNormText(`${el.className || ""}`);

      const match = entries.some(entry => {
        const amount = String(Math.round(Number(entry.value) || 0));
        if (!amount || amount === "0" || !digits.includes(amount)) return false;
        const named = entry.names.some(name => text.includes(name));
        const iconed = entry.names.some(name => cls.includes(name));
        return named || iconed;
      });

      if (!match) return;
      el.dataset.sonicNativeHidden = "1";
      el.style.setProperty("display", "none", "important");
    });
  }

  function sonicExpHideNativeShipResult(row, report) {
    if (!row || !report) return;
    const entries = Object.entries(report.shipsFound || {})
      .map(([id, amount]) => ({
        names: [sonicExpNormText(ALL_UNIT_NAMES[id] || "")].filter(Boolean),
        value: Number(amount) || 0,
      }))
      .filter(e => e.names.length && e.value > 0);
    sonicExpHideNativeByAmount(row, entries);
  }

  function sonicExpHideNativeResourceResult(row, report) {
    if (!row || !report) return;
    const r = report.resources || {};
    const entries = [
      { names: ["metal"], value: r.metal },
      { names: ["cristal", "crystal"], value: r.crystal },
      { names: ["deuterium", "deut"], value: r.deut ?? r.deuterium },
      { names: ["matiere noire", "darkmatter", "dark matter", "antimatiere"], value: r.dm ?? r.darkMatter },
    ].filter(e => Number(e.value) > 0);
    sonicExpHideNativeByAmount(row, entries);
  }

  function sonicExpPlaceInNativeFrame(row, box) {
    const header = sonicExpFindNativeHeader(row);
    if (!header) return false;

    const content = row.querySelector(".msg_content, .msgContent, .msg_body, .message-content");
    let node = header;
    let frame = null;
    let following = [];

    while (node.parentElement && node.parentElement !== row) {
      if (node === content) return false;
      const p = node.parentElement;
      if (p.classList.contains("msg")) return false;
      following = [...p.children].filter(c =>
        c !== node && (node.compareDocumentPosition(c) & Node.DOCUMENT_POSITION_FOLLOWING)
      );
      if (following.length) { frame = p; break; }
      node = p;
    }
    if (!frame) return false;

    following.forEach(c => {
      if (c === box || c.contains(box)) return;
      if (c.classList.contains("rawMessageData") || c.querySelector(".rawMessageData")) return;
      const t = sonicExpNormText(c.textContent);
      if (t.length > 160 || /extrait|journal/.test(t)) return;
      c.dataset.sonicNativeHidden = "1";
      c.style.setProperty("display", "none", "important");
    });

    box.classList.add("sonic-exp-in-frame");
    box.style.setProperty("margin", "0", "important");
    box.style.setProperty("width", "100%", "important");
    box.style.setProperty("border-top", "0", "important");
    const label = box.querySelector(".sonic-exp-result-label");
    if (label) label.style.setProperty("display", "none", "important");

    node.insertAdjacentElement("afterend", box);
    return true;
  }

  function sonicExpParseReport(row) {
    const rawData = getRawMessageData(row);
    if (!rawData) return null;
    const rawExpeditionResult = rawData.dataset.rawExpeditionresult;
    const globalTypeID = parseInt(rawData.dataset.rawMessagetype || "-1", 10);
    if (rawExpeditionResult === undefined && globalTypeID !== 61) return null;
    const rawTimestamp = Number(rawData.dataset.rawTimestamp || 0);
    const timestamp = Number.isFinite(rawTimestamp) && rawTimestamp > 0
      ? (rawTimestamp < 100000000000 ? rawTimestamp * 1000 : rawTimestamp)
      : Date.now() - getReportAgeMilliseconds(rawData);
    const delay = sonicExpParseDelay(rawData);
    let artefact = parseInt(rawData.dataset.rawArtifactsfound || "0", 10);
    if (!Number.isFinite(artefact) || artefact < 0) artefact = 0;
    if (artefact === 0 && globalTypeID === 61) {
      const text = String(rawData.closest?.('[data-msg-id]')?.textContent || rawData.parentElement?.textContent || '');
      const match = text.match(/Art[eé]facts?\s+trouv[eé]s?\s*:\s*(\d+)/i);
      if (match) artefact = Number(match[1]) || 0;
    }
    const lfXP = parseInt(
      rawData.dataset.rawLifeformgainedexperience || "0",
      10,
    );
    const resultType =
      globalTypeID === 61
        ? artefact > 0
          ? "artefact"
          : lfXP > 0
            ? "lifeform"
            : "nothing"
        : sonicExpResolveResultType(rawExpeditionResult, delay);
    const resources = sonicExpParseJson(
      (rawData.dataset.rawResourcesgained || "{}")
        .replace("deuterium", "deut")
        .replace("darkMatter", "dm"),
      {},
    );
    const lifeform = parseInt(rawData.dataset.rawLifeform || "0", 10);
    const item = sonicExpParseJson(rawData.dataset.rawItemsgained, {});
    const depletion = parseInt(rawData.dataset.rawDepletion || "0", 10);
    const sizeRaw = (
      rawData.dataset.rawSize ||
      rawData.dataset.rawArtifactssize ||
      "-1"
    )
      .replace("normal", "2")
      .replace("big", "1")
      .replace("huge", "0");
    const size = parseInt(sizeRaw, 10);
    const shipsFound = sonicExpNormalizeShipSources(rawData);
    const shipsLost = {};
    Object.entries(sonicExpParseJson(rawData.dataset.rawShipslost, {})).forEach(
      ([shipId, amount]) => {
        shipsLost[shipId] = amount;
      },
    );
    return {
      messageId: getMessageId(row),
      globalTypeID,
      timestamp,
      resultType,
      resources,
      shipsFound,
      shipsLost,
      artefact,
      lifeform,
      lfXP,
      item,
      depletion,
      size,
      delay,
    };
  }
  function sonicExpReadAllReports(prebuiltRows = null) {
    const parser = new DOMParser();
    const byId = new Map();
    const entries = Array.isArray(prebuiltRows)
      ? prebuiltRows.filter(entry => Number(entry?.categoryId) === 22)
      : (window.SoNiCMessageReader?.getByCategory?.(22) || []).filter((m) => m?.viewed);

    for (const entry of entries) {
      try {
        const message = entry?.message || entry;
        let row = entry?.row || null;
        if (!row) row = sonicEconomyBuildStoredMessageRow(message);
        if (!row) continue;
        const parsed = sonicExpParseReport(row);
        if (!parsed?.messageId) continue;
        parsed.categoryId = 22;
        byId.set(String(parsed.messageId), parsed);
      } catch (_) {}
    }

    return [...byId.values()].sort(
      (a,b) => Number(b.timestamp || 0) - Number(a.timestamp || 0)
    );
  }

  function sonicExpTranslateShipIds(shipsById) {
    const named = {};
    Object.entries(shipsById || {}).forEach(([id, amount]) => {
      const label = ALL_UNIT_NAMES[id] || `Unité ${id}`;
      named[label] = (named[label] || 0) + Number(amount || 0);
    });
    return named;
  }
  function sonicExpRenderChatGptDashboard() {
    if (
      window.SoNiCExpeditionUI &&
      document.getElementById("sonic-expedition-dashboard")
    ) {
      window.SoNiCExpeditionUI.destroy();
      return;
    }
    if (!window.SoNiCExpeditionUI) return;

    const totals = sonicEconomyAggregateCategoryAllTime("expedition");
    const recyclingTotals = sonicEconomyAggregateCategoryAllTime("recycling");
    const shipsFoundDetail = sonicExpTranslateShipIds(totals.shipsFound);
    const shipsLostDetail = sonicExpTranslateShipIds(totals.shipsLost);
    const sumValues = (obj) =>
      Object.values(obj || {}).reduce((sum, value) => sum + Number(value || 0), 0);

    const lostShipsMSU = (ships) => Object.entries(ships || {}).reduce((sum,[id,amount]) => {
      const cost = EXPEDITION_SHIP_COSTS[id];
      if (!cost) return sum;
      return sum + getMSU(
        cost[0] * (Number(amount)||0),
        cost[1] * (Number(amount)||0),
        cost[2] * (Number(amount)||0),
        settings.msuRatio
      );
    }, 0);

    const dailyData = {};
    Object.keys(sonicDailyEconomyDB.days || {}).forEach((dateKey) => {
      const day = sonicDailyEconomyDB.days[dateKey];
      const e = day?.expedition;
      if (!e || !e.count) return;
      const found = sonicExpTranslateShipIds(e.shipsFound || {});
      const lost = sonicExpTranslateShipIds(e.shipsLost || {});
      const resultTypes = { ...(e.resultTypes || {}) };
      const lostResults =
        Number(resultTypes.pirate || 0) +
        Number(resultTypes.alien || 0) +
        Number(resultTypes.blackhole || 0);
      delete resultTypes.late;
      delete resultTypes.pirate;
      delete resultTypes.alien;
      delete resultTypes.blackhole;
      if (lostResults > 0) resultTypes.lost = lostResults;
      dailyData[dateKey] = {
        count: Number(e.count || 0),
        resources: {
          metal: Number(e.metal || 0),
          crystal: Number(e.crystal || 0),
          deuterium: Number(e.deuterium || 0)
        },
        darkMatter: Number(e.darkMatter || 0),
        artefact: Number(e.artifacts || 0),
        shipsFound: Number(e.shipsFound ? sumValues(e.shipsFound) : 0),
        shipsLost: Number(e.shipsLost ? sumValues(e.shipsLost) : 0),
        shipsFoundDetail: found,
        shipsLostDetail: lost,
        resultTypes,
        msu: getMSU(e.metal || 0, e.crystal || 0, e.deuterium || 0, settings.msuRatio),
        lostMsu: lostShipsMSU(e.shipsLost || {}),
        recycling: {
          count: Number(day?.recycling?.count || 0),
          metal: Number(day?.recycling?.metal || 0),
          crystal: Number(day?.recycling?.crystal || 0),
          deuterium: Number(day?.recycling?.deuterium || 0)
        },
        lastTimestamp: Number(e.lastTimestamp || 0)
      };
    });

    const summary = {
      total: totals.count,
      resources: {
        metal: totals.metal,
        crystal: totals.crystal,
        deuterium: totals.deuterium,
      },
      darkMatter: totals.darkMatter,
      artefact: totals.artifacts,
      shipsFound: sumValues(shipsFoundDetail),
      shipsLost: sumValues(shipsLostDetail),
      shipsFoundDetail,
      shipsLostDetail,
      recycling: {
        count: recyclingTotals.count,
        metal: recyclingTotals.metal,
        crystal: recyclingTotals.crystal,
        deuterium: recyclingTotals.deuterium,
        msu: getMSU(recyclingTotals.metal, recyclingTotals.crystal, recyclingTotals.deuterium, settings.msuRatio),
      },
      resultTypes: Object.fromEntries(
        Object.entries(totals.resultTypes || {}).filter(([type]) => type !== "late")
      ),
      dailyData,
      daily: Object.fromEntries(Object.entries(dailyData).map(([key, value]) => [key, value.count])),
      lastDate: totals.lastTimestamp ? new Date(totals.lastTimestamp) : new Date(),
      msu: getMSU(totals.metal, totals.crystal, totals.deuterium, settings.msuRatio),
      lostMsu: lostShipsMSU(totals.shipsLost || {}),
    };
    window.SoNiCExpeditionUI.setSummary(summary);
  }
  window.SoNiCOpenExpeditionDashboard = function () {
    try {
      sonicExpRenderChatGptDashboard();
      return true;
    } catch (error) {
      console.warn("[SoNiC Expéditions] Ouverture directe du dashboard impossible :", error);
      return false;
    }
  };

  function sonicExpFormatMessageNumber(value) {
    return Number(value || 0).toLocaleString("fr-FR");
  }

  function sonicExpCreateChip(parent, className, label, value) {
    const chip = document.createElement("span");
    chip.className = `sonic-exp-chip ${className}`;
    const strong = document.createElement("b");
    strong.textContent = label;
    chip.appendChild(strong);
    if (value !== undefined && value !== null && value !== "") {
      const text = document.createElement("span");
      text.textContent = sonicExpFormatMessageNumber(value);
      chip.appendChild(text);
    }
    parent.appendChild(chip);
    return chip;
  }

  window.SoNiCShipIcons = {
    src(shipId) {
      const index = SONIC_EXP_SHIP_IMAGE_INDEX_V17[String(shipId)];
      if (!Number.isInteger(index)) return "";
      const hosted = window.SONIC_ASSETS && window.SONIC_ASSETS.shipIconsBase;
      return hosted ? `${hosted}ship-${shipId}.png` : "";
    },
    name(shipId) { return ALL_UNIT_NAMES[shipId] || `Unité ${shipId}`; },
    // Style « Minimal » : vignette découpée dans la planche officielle d'images du jeu (4000 × 6000 px ; vaisseaux : 1re ligne, 17 vignettes de 200 px à partir de y = 3000), sans fichier hébergé par SoNiC.
    sprite(shipId, size) {
      // Planche officielle : défenses (y = 2000), vaisseaux (y = 3000), technologies (y = 4000), vignettes de 200 px.
      const SONIC_DEF_IDX = { 401: 0, 402: 1, 403: 2, 404: 3, 405: 4, 406: 5, 407: 6, 408: 7, 502: 8, 503: 9 };
      const SONIC_TECH_IDX = { 113: 0, 120: 1, 121: 2, 114: 3, 122: 4, 115: 5, 117: 6, 118: 7, 106: 8, 108: 9, 124: 10, 123: 11, 199: 12, 111: 13, 109: 14, 110: 15 };
      let index = SONIC_EXP_SHIP_IMAGE_INDEX_V17[String(shipId)];
      let sheetY = 3000;
      if (!Number.isInteger(index)) {
        if (Number.isInteger(SONIC_DEF_IDX[Number(shipId)])) { index = SONIC_DEF_IDX[Number(shipId)]; sheetY = 2000; }
        else if (Number.isInteger(SONIC_TECH_IDX[Number(shipId)])) { index = SONIC_TECH_IDX[Number(shipId)]; sheetY = 4000; }
      }
      if (!Number.isInteger(index)) return "";
      const px = Math.max(12, Math.min(64, Number(size) || 24));
      const k = px / 200;
      const r = (v) => Math.round(v * 100) / 100;
      return `<span class="sonic-shipspr" style="display:inline-block;flex:0 0 auto;vertical-align:middle;border-radius:3px;width:${px}px;height:${px}px;background:#0b1620 url(https://gf3.geo.gfsrv.net/cdn53/7a9861be0c38bf7de05a57c56d73cf.jpg) no-repeat ${r(-index * 200 * k)}px ${r(-sheetY * k)}px / ${r(4000 * k)}px ${r(6000 * k)}px"></span>`;
    },
  };

  function sonicExpBuildShipCell(shipId, amount) {
    const shipName = ALL_UNIT_NAMES[shipId] || `Unité ${shipId}`;

    const cell = document.createElement("span");
    cell.className = "sonic-exp-shipcell";
    cell.title = `${shipName} ×${sonicExpFormatMessageNumber(amount)}`;
    cell.style.cssText = [
      "display:flex", "align-items:center", "gap:6px",
      "box-sizing:border-box", "width:100%", "height:40px", "overflow:hidden",
      "position:relative", "contain:layout paint", "isolation:isolate",
      "padding:2px 9px 2px 3px",
      "border:1px solid rgba(105,154,179,.45)", "border-radius:4px",
      "background:linear-gradient(180deg,rgba(11,29,41,.92),rgba(4,13,20,.92))",
      "white-space:nowrap",
    ].join(";");

    const icon = document.createElement("img");
    icon.className = "sonic-exp-native-ship-image";
    icon.dataset.shipId = String(shipId);
    icon.style.cssText = [
      "display:block", "position:static", "flex:0 0 38px",
      "width:38px", "height:38px", "min-width:38px", "min-height:38px",
      "max-width:38px", "max-height:38px", "object-fit:fill",
      "overflow:hidden", "border:0", "background:none", "padding:0", "margin:0",
    ].join(";");
    const imageSrc = window.SoNiCShipIcons?.src?.(shipId) || null;
    icon.addEventListener("error", () => {
      icon.style.setProperty("display", "none", "important");
      icon.insertAdjacentHTML(
        "afterend",
        `<span class="sonic-exp-native-ship-fallback" style="display:flex;flex:0 0 38px;align-items:center;justify-content:center;width:38px;height:38px;min-width:38px;border-radius:4px;background:rgba(105,154,179,.18);color:#b8cbd4;font:700 8px Arial,sans-serif">${sonicExpNormText(shipName).slice(0, 2).toUpperCase()}</span>`,
      );
    }, { once: true });
    let spriteNode = null;
    if (imageSrc) {
      icon.src = imageSrc;
    } else {
      // Style Minimal : vignette de la planche officielle du jeu ; texte de repli seulement si l'identifiant n'y figure pas.
      try {
        const html = window.SoNiCShipIcons?.sprite?.(shipId, 38);
        if (html) { const tmp = document.createElement("span"); tmp.innerHTML = html; spriteNode = tmp.firstElementChild; if (spriteNode) spriteNode.style.flex = "0 0 38px"; }
      } catch (_) {}
      if (!spriteNode) icon.dispatchEvent(new Event("error"));
    }
    icon.alt = "";
    icon.draggable = false;
    icon.width = 38;
    icon.height = 38;
    icon.loading = "eager";
    icon.decoding = "sync";

    const text = document.createElement("span");
    text.style.cssText = "display:flex;flex-direction:column;justify-content:center;line-height:1.15;min-width:0;overflow:hidden;flex:1 1 auto";

    const nameEl = document.createElement("span");
    nameEl.textContent = shipName;
    nameEl.style.cssText = "font:700 9px Arial,sans-serif;color:#b8cbd4;overflow:hidden;text-overflow:ellipsis;white-space:nowrap";

    const amountEl = document.createElement("b");
    amountEl.textContent = `×${sonicExpFormatMessageNumber(amount)}`;
    amountEl.style.cssText = "font:700 11px Arial,sans-serif;color:#f1c95b;overflow:hidden;text-overflow:ellipsis;white-space:nowrap";

    text.append(nameEl, amountEl);
    if (spriteNode) cell.append(spriteNode, text); else cell.append(icon, text);
    return cell;
  }

  function sonicExpRenderMessageResult(row) {
    if (!row) return;
    row.querySelectorAll(":scope > .sonic-exp-result, .sonic-exp-result").forEach(el => el.remove());

    const report = sonicExpParseReport(row);
    if (!report) return;

    const box = document.createElement("div");
    box.className = "sonic-exp-result";

    const label = document.createElement("span");
    label.className = "sonic-exp-result-label";
    label.textContent = "Butin";
    box.appendChild(label);

    const resources = report.resources || {};
    if (Number(resources.metal || 0) > 0) sonicExpCreateChip(box, "metal", "M", resources.metal);
    if (Number(resources.crystal || 0) > 0) sonicExpCreateChip(box, "crystal", "C", resources.crystal);
    if (Number(resources.deut || resources.deuterium || 0) > 0) sonicExpCreateChip(box, "deut", "D", resources.deut || resources.deuterium);
    if (Number(resources.dm || resources.darkMatter || 0) > 0) sonicExpCreateChip(box, "dm", "AM", resources.dm || resources.darkMatter);
    if (Number(report.artefact || 0) > 0) sonicExpCreateChip(box, "artifact", "ARTEFACT", report.artefact);
    if (report.item && typeof report.item === "object" && Object.keys(report.item).length) {
      sonicExpCreateChip(box, "item", "OBJET", Object.keys(report.item).length);
    }
    if (Number(report.lfXP || 0) > 0) sonicExpCreateChip(box, "lifeform", "XP", report.lfXP);

    const ships = Object.entries(report.shipsFound || {})
      .filter(([, amount]) => Number(amount || 0) > 0);
    if (ships.length) {
      const shipsWrap = document.createElement("span");
      shipsWrap.className = "sonic-exp-ships";
      shipsWrap.style.cssText = [
        "display:grid",
        "grid-template-columns:repeat(auto-fill,minmax(110px,1fr))",
        "grid-auto-rows:40px",
        "gap:5px",
        "width:100%",
        "min-width:0",
        "contain:layout paint",
      ].join(";");
      ships.forEach(([shipId, amount]) => shipsWrap.appendChild(sonicExpBuildShipCell(shipId, amount)));
      box.appendChild(shipsWrap);
    }

    const hasVisibleLoot = box.querySelector(".sonic-exp-chip, .sonic-exp-ships");
    if (!hasVisibleLoot) {
      const resultLabel =
        report.resultType === "blackhole" ? "Flotte perdue" :
        report.resultType === "pirate" ? "Combat pirates" :
        report.resultType === "alien" ? "Combat aliens" :
        report.resultType === "trader" ? "Marchand" :
        "Rien";
      const empty = document.createElement("span");
      empty.className = "sonic-exp-empty";
      empty.textContent = resultLabel;
      box.appendChild(empty);
    }

    let msu = getMSU(
      Number(resources.metal || 0),
      Number(resources.crystal || 0),
      Number(resources.deut || resources.deuterium || 0),
      settings.msuRatio,
    );
    let shipsMsuNote = "";
    try {
      if (loadSettings().expShipsMsu === true && ships.length) {
        const shipsMsu = Math.round(sonicShipMsuValue(report.shipsFound || {}));
        if (shipsMsu > 0) { msu += shipsMsu; shipsMsuNote = ` dont vaisseaux ${formatNumber(shipsMsu)} (ratio ${sonicShipMsuGetMode()})`; }
      }
    } catch (_) {}
    if (msu > 0) {
      const msuEl = document.createElement("span");
      msuEl.className = "sonic-exp-msu";
      msuEl.title = `${formatNumber(msu)} MSU — ratio ${settings.msuRatio}${shipsMsuNote}`;
      msuEl.textContent = `${formatToUnits(msu)} MSU`;
      box.appendChild(msuEl);
    }

    sonicExpHideNativeResourceResult(row, report);
    sonicExpHideNativeShipResult(row, report);
    if (!sonicExpPlaceInNativeFrame(row, box)) {
      const anchor = row.querySelector(".msg_content, .msgContent, .msg_body, .message-content") || row;
      anchor.appendChild(box);
    }
  }

  function refreshExpeditionDisplay() {
    if (!isMessagesPage()) return;
    const rows = Array.from(document.querySelectorAll(".msg[data-msg-id]"));
    rows.forEach(row => {
      if (row.dataset.sonicExpDone === "1") return;
      if (!row.querySelector(".rawMessageData")) return;
      try { sonicExpRenderMessageResult(row); } catch (_) {}
      row.dataset.sonicExpDone = "1";
    });
  }

  const SONIC_DM_TRACKER_KEY = "SoNiC_Suite_DarkMatterTracker";
  const SONIC_DM_EVENT_URL = "";
  const SONIC_DM_CHECK_INTERVAL = 2000;
  const SONIC_DM_EVENT_CHECK_INTERVAL = 5 * 60000;

  const SONIC_DM_DEFAULT_STATE = {
    totalSpent: 0,
    totalGained: 0,
    lastKnownAM: null,
    lastReset: Date.now(),
    event: { active: false, rate: 0, lastCheck: 0, start: 0, end: 0, spent: 0, src: '', source: '' },
    lastEvent: null,
    lastBannerSrc: '',
    bannerMap: { '6761f19017ced58da2a51e73174b9c': 25 },
    history: [],
  };
  const SONIC_DM_HISTORY_MAX = 200;

  function sonicDmLoadState() {
    const saved = loadJSON(SONIC_DM_TRACKER_KEY, null);
    if (!saved) return { ...SONIC_DM_DEFAULT_STATE, history: [] };
    return {
      ...SONIC_DM_DEFAULT_STATE,
      ...saved,
      event: { ...SONIC_DM_DEFAULT_STATE.event, ...(saved.event || {}) },
      bannerMap: { ...SONIC_DM_DEFAULT_STATE.bannerMap, ...(saved.bannerMap || {}) },
      history: Array.isArray(saved.history) ? saved.history : [],
    };
  }
  let sonicDmState = sonicDmLoadState();
  function sonicDmSaveState() {
    saveJSON(SONIC_DM_TRACKER_KEY, sonicDmState);
  }

  function sonicDmGetCurrentAmount() {
    const primary = document.querySelector("#resources_darkmatter");
    if (primary && primary.dataset.raw !== undefined) {
      const value = Number(primary.dataset.raw);
      if (Number.isFinite(value) && value >= 0) return value;
    }
    const fallbackSelectors = [
      "#darkmatter_box .value",
      "#darkmatter .value",
      "#darkmatter_box",
      ".darkmatter .value",
      ".resource.darkmatter .value",
      '[data-resource="darkmatter"] .value',
      '[id*="darkmatter" i] .value',
    ];
    for (const selector of fallbackSelectors) {
      const element = document.querySelector(selector);
      if (!element) continue;
      const cleaned = (element.textContent || "").replace(/[^\d]/g, "");
      const value = Number(cleaned);
      if (Number.isFinite(value) && value >= 0) return value;
    }
    return null;
  }

  const SONIC_DM_ACTION_WINDOW_MS = 8000;
  let sonicDmLastAction = null;

  function sonicDmWatchActions() {
    document.addEventListener(
      "click",
      (event) => {
        const el = event.target.closest(
          'a.dm, a[class*="dm" i], a.build-it, [class*="item" i][class*="dm" i]',
        );
        if (!el) return;
        const text = (el.textContent || el.title || el.getAttribute("aria-label") || "").trim();
        if (!text) return;
        sonicDmLastAction = { description: text.slice(0, 120), at: Date.now() };
      },
      true,
    );
  }

  function sonicDmConsumeRecentAction() {
    if (
      sonicDmLastAction &&
      Date.now() - sonicDmLastAction.at <= SONIC_DM_ACTION_WINDOW_MS
    ) {
      const description = sonicDmLastAction.description;
      sonicDmLastAction = null;
      return description;
    }
    return null;
  }

  function sonicDmAddHistoryEntry(entry) {
    sonicDmState.history.push(entry);
    if (sonicDmState.history.length > SONIC_DM_HISTORY_MAX) {
      sonicDmState.history = sonicDmState.history.slice(-SONIC_DM_HISTORY_MAX);
    }
  }

  function sonicDmCheckAmount() {
    if (!settings.darkMatterTrackingEnabled) return;
    const currentAM = sonicDmGetCurrentAmount();
    if (currentAM === null) return;

    if (sonicDmState.lastKnownAM === null || sonicDmState.lastKnownAM === undefined) {
      sonicDmState.lastKnownAM = currentAM;
      sonicDmSaveState();
      sonicDmUpdatePanel();
      return;
    }

    const previous = sonicDmState.lastKnownAM;
    const difference = currentAM - previous;
    if (difference < 0) {
      const spent = Math.abs(difference);
      sonicDmState.totalSpent += spent;
      if (sonicDmState.event.active && Date.now() <= (sonicDmState.event.end || Infinity)) sonicDmState.event.spent = (Number(sonicDmState.event.spent) || 0) + spent;
      sonicDmState.lastKnownAM = currentAM;
      sonicDmAddHistoryEntry({
        timestamp: Date.now(),
        previous,
        current: currentAM,
        difference,
        type: "spent",
        amount: spent,
        description: sonicDmConsumeRecentAction() || "Dépense AM détectée",
      });
      sonicDmSaveState();
      sonicDmUpdatePanel();
      sonicDmShowTransaction(`-${formatNumber(spent)} AM`, "spent");
    } else if (difference > 0) {
      sonicDmState.totalGained += difference;
      sonicDmState.lastKnownAM = currentAM;
      sonicDmAddHistoryEntry({
        timestamp: Date.now(),
        previous,
        current: currentAM,
        difference,
        type: "gained",
        amount: difference,
        description: "Gain AM détecté",
      });
      sonicDmMatchRefunds();
      sonicDmSaveState();
      sonicDmUpdatePanel();
      sonicDmShowTransaction(`+${formatNumber(difference)} AM`, "gained");
    }
  }

  // Message « Événement de remboursement » : le gain détecté au même moment est scindé en une ligne « événement » (montant du message) et le reste (expéditions, divers).
  function sonicDmMatchRefunds() {
    try {
      const msgs = sonicDmState.refundMsgs || {};
      let changed = false;
      Object.keys(msgs).forEach((k) => {
        const m = msgs[k];
        if (!m || m.done) return;
        const hist = sonicDmState.history || [];
        let best = -1, bestGap = Infinity;
        hist.forEach((h, i) => {
          if (h.type !== "gained" || h.event) return;
          const gap = h.timestamp - m.ts;
          if (gap < -60000 || gap > 15 * 60000) return;
          if (Number(h.amount) < m.credit) return;
          if (gap < bestGap) { bestGap = gap; best = i; }
        });
        if (best < 0) return;
        const h = hist[best], rest = Number(h.amount) - m.credit;
        const ev = { timestamp: h.timestamp, previous: h.previous, current: h.current, difference: m.credit, type: "gained", amount: m.credit, event: true, rate: m.rate, spent: m.spent, description: "Remboursement événement " + m.rate + " % (dépensé " + formatNumber(m.spent) + ")" };
        if (rest > 0) { h.amount = rest; h.difference = rest; hist.splice(best + 1, 0, ev); } else { hist[best] = ev; }
        m.done = true; changed = true;
      });
      if (changed) { sonicDmSaveState(); sonicDmUpdatePanel(); }
    } catch (_) {}
  }

  function sonicDmGetEstimatedRefund() {
    if (!sonicDmState.event.active || !sonicDmState.event.rate) return 0;
    return Math.floor((Number(sonicDmState.event.spent) || 0) * (sonicDmState.event.rate / 100));
  }

  // ---- Événements de remboursement (15 / 20 / 25 %) : activation manuelle ou lecture de l'image de la vue générale ----
  const SONIC_DM_EVENT_MS = 48 * 3600 * 1000; // durée par défaut (activation manuelle / image sans dates) : 2 jours
  function sonicDmDayStart(t) { const d = new Date(t); d.setHours(0, 0, 0, 0); return d.getTime(); }
  function sonicDmSpentSince(t0, t1) {
    return (sonicDmState.history || []).filter((h) => h.type === "spent" && h.timestamp >= t0 && h.timestamp <= t1).reduce((n, h) => n + (Number(h.amount) || 0), 0);
  }
  function sonicDmStartEvent(rate, opts) {
    const o = opts || {};
    const now = Date.now();
    const start = o.start || (o.source === "image" ? sonicDmDayStart(now) : now);
    const end = o.end || (start + SONIC_DM_EVENT_MS);
    sonicDmState.event = { active: true, rate, lastCheck: now, start, end, spent: sonicDmSpentSince(start, now), src: o.src || "", source: o.source || "manual" };
    sonicDmSaveState(); sonicDmUpdatePanel();
  }
  function sonicDmStopEvent(keepSummary) {
    const e = sonicDmState.event;
    if (e.active && keepSummary) sonicDmState.lastEvent = { src: e.src, rate: e.rate, start: e.start, end: e.end, spent: Number(e.spent) || 0, refund: Math.floor((Number(e.spent) || 0) * e.rate / 100) };
    sonicDmState.event = { ...SONIC_DM_DEFAULT_STATE.event };
    sonicDmSaveState(); sonicDmUpdatePanel();
  }
  // Image de l'événement dans la vue générale : on retient son identifiant ; s'il correspond à un taux connu, l'événement est activé (2 jours à partir de minuit).
  // La bannière du jeu porte la période exacte de l'événement dans son attribut ref (base64 « début|fin » en secondes) : lue sans aucune requête.
  function sonicDmBannerWindow() {
    try {
      const a = document.querySelector('#banner_skyscraper a.close_details[ref], #bannerskyscrapercomponent a.close_details[ref], .bannerPosition a.close_details[ref]');
      const ref = String(a?.getAttribute("ref") || "");
      for (let len = Math.min(ref.length, 44); len >= 12; len--) {
        let dec = "";
        try { dec = atob(ref.slice(0, len)); } catch (_) { continue; }
        const m = dec.match(/^(\d{9,11})\|(\d{9,11})$/);
        if (m) {
          const start = Number(m[1]) * 1000, end = Number(m[2]) * 1000;
          if (end > start && end - start < 40 * 86400000) return { start, end };
        }
      }
    } catch (_) {}
    return null;
  }
  function sonicDmScanBanner() {
    try {
      const e = sonicDmState.event;
      if (e.active && Date.now() > (e.end || 0)) sonicDmStopEvent(true);
      if (!/component=overview|page=overview/i.test(location.search)) return;
      const img = document.querySelector('#overviewcomponent a[href*="component=shop"] img[src*="gfsrv"], #overview a.tooltipLeft[href*="component=shop"] img[src*="gfsrv"], a.tooltipLeft[href*="component=shop"] img[src$=".jpg"]');
      const id = String(img?.getAttribute("src") || "").split("/").pop().replace(/\.\w+$/, "").split("?")[0];
      if (!id) return;
      if (sonicDmState.lastBannerSrc !== id) { sonicDmState.lastBannerSrc = id; sonicDmSaveState(); }
      const rate = Number(sonicDmState.bannerMap[id]);
      const win = sonicDmBannerWindow();
      const now = Date.now();
      if ([15, 20, 25].includes(rate) && win && now < win.end) {
        const ev = sonicDmState.event;
        if (ev.active && ev.src === id) {
          // Événement déjà suivi : on aligne début/fin sur les dates exactes de la bannière.
          if (ev.start !== win.start || ev.end !== win.end) {
            sonicDmState.event = { ...ev, start: win.start, end: win.end, spent: sonicDmSpentSince(win.start, now) };
            sonicDmSaveState(); sonicDmUpdatePanel();
          }
          return;
        }
        const done = sonicDmState.lastEvent;
        // Même période déjà terminée ou arrêtée à la main : pas de relance.
        if (done && done.src === id && done.end === win.end && !ev.active) return;
        sonicDmStartEvent(rate, { source: "image", src: id, start: win.start, end: win.end });
        return;
      }
      if ([15, 20, 25].includes(rate) && !(sonicDmState.event.active && sonicDmState.event.src === id)) {
        const done = sonicDmState.lastEvent;
        // Un événement déjà terminé avec la même image n'est pas relancé.
        if (done && done.src === id && Date.now() > done.end) return;
        sonicDmStartEvent(rate, { source: "image", src: id });
      }
    } catch (_) {}
  }
  // Message « Événement de remboursement » (onglet Univers de jeu) : taux et période (du jj.mm. au jj.mm.) lus directement dans le texte.
  let sonicDmMsgSig = "";
  function sonicDmScanMessages() {
    try {
      if (!/component=messages|page=messages/i.test(location.search + location.hash) && !document.querySelector("#messagescomponent")) return;
      const nodes = Array.from(document.querySelectorAll(".msg, [data-msg-id]"));
      if (!nodes.length) return;
      const sig = nodes.length + ":" + (nodes[0]?.textContent || "").length;
      if (sig === sonicDmMsgSig) return;
      sonicDmMsgSig = sig;
      const seen = sonicDmState.seenEventMsgs || (sonicDmState.seenEventMsgs = {});
      nodes.forEach((n) => {
        const t = (n.textContent || "").replace(/\s+/g, " ");
        if (!/antimati[eè]re/i.test(t) || !/[ée]v[eèé]nement/i.test(t) || !/%/.test(t)) return;
        // Message de fin d'événement : « utilisé au total X unités … recréditer … de N % … (Y unités d'antimatière) ».
        const tot = t.match(/utilis[ée]\s+au\s+total\s+([\d.\s\u00a0]+?)\s+unit[ée]s/i);
        const cr = t.match(/(\d{1,2})\s*%[^()]*\(\s*([\d.\s\u00a0]+?)\s+unit[ée]s/i);
        if (tot && cr) {
          const dt = t.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})\s+(\d{1,2}):(\d{2})(?::(\d{2}))?/);
          const ts = dt ? new Date(Number(dt[3]), Number(dt[2]) - 1, Number(dt[1]), Number(dt[4]), Number(dt[5]), Number(dt[6] || 0)).getTime() : 0;
          const num = (x) => Number(String(x).replace(/[^\d]/g, "")) || 0;
          const credit = num(cr[2]), spent = num(tot[1]), rate = Number(cr[1]);
          if (ts && credit > 0) {
            const store = sonicDmState.refundMsgs || (sonicDmState.refundMsgs = {});
            const key = ts + ":" + credit;
            if (!store[key]) {
              store[key] = { ts, credit, spent, rate, done: false };
              sonicDmState.lastEvent = { src: "", rate, start: 0, end: ts, spent, refund: credit };
              sonicDmSaveState();
            }
            sonicDmMatchRefunds();
          }
          return;
        }
        const per = t.match(/du\s+(\d{1,2})\.(\d{1,2})\.?\s*au\s+(\d{1,2})\.(\d{1,2})\./i);
        const rt = t.match(/(\d{2})\s*%\s+de\s+vos\s+d[ée]penses|(\d{2})\s*%\s+(?:de\s+)?(?:vos\s+)?d[ée]penses/i) || t.match(/(\d{2})\s*%/);
        const rate = Number(rt && (rt[1] || rt[2]));
        if (!per || ![15, 20, 25].includes(rate)) return;
        const md = t.match(/(\d{1,2})\.(\d{1,2})\.(\d{4})\s+\d{1,2}:\d{2}/);
        const year = md ? Number(md[3]) : new Date().getFullYear();
        const start = new Date(year, Number(per[2]) - 1, Number(per[1]), 0, 0, 0).getTime();
        // « du 23.10. au 24.10. » : le dernier jour est inclus (jusqu'à 23:59:59).
        let end = new Date(year, Number(per[4]) - 1, Number(per[3]), 23, 59, 59).getTime();
        if (end <= start) end = start + 24 * 3600 * 1000 - 1000;
        const key = per[1] + "." + per[2] + "-" + per[3] + "." + per[4] + "@" + year + ":" + rate;
        if (seen[key]) return;
        seen[key] = 1;
        const now = Date.now();
        if (now >= end) {
          const spent = sonicDmSpentSince(start, end);
          sonicDmState.lastEvent = { src: "", rate, start, end, spent, refund: Math.floor(spent * rate / 100) };
          sonicDmSaveState(); sonicDmUpdatePanel();
        } else if (!(sonicDmState.event.active && sonicDmState.event.start === start && sonicDmState.event.rate === rate)) {
          sonicDmStartEvent(rate, { source: "message", start, end, src: sonicDmState.lastBannerSrc || "" });
          const id = sonicDmState.lastBannerSrc;
          if (id && !sonicDmState.bannerMap[id]) { sonicDmState.bannerMap[id] = rate; sonicDmSaveState(); }
        }
      });
    } catch (_) {}
  }
  function sonicDmSetEventRate(rate) {
    const e = sonicDmState.event;
    if (e.active && e.rate === rate) { sonicDmStopEvent(true); return; }
    // L'image affichée en ce moment est associée à ce taux (reconnue automatiquement aux prochains événements).
    const id = sonicDmState.lastBannerSrc;
    if (id && !sonicDmState.bannerMap[id]) sonicDmState.bannerMap[id] = rate;
    sonicDmStartEvent(rate, { source: "manual", src: id || "" });
  }

  async function sonicDmCheckEventStatus() {
    if (!settings.darkMatterEventSyncEnabled) return;
    if (!SONIC_DM_EVENT_URL) return;
    try {
      const response = await fetch(SONIC_DM_EVENT_URL + "?t=" + Date.now(), {
        cache: "no-store",
      });
      if (!response.ok) throw new Error("HTTP " + response.status);
      const data = await response.json();
      const validRates = [15, 20, 25];
      const active = data.active === true;
      const rate = validRates.includes(Number(data.rate)) ? Number(data.rate) : 0;
      sonicDmState.event.active = active && rate > 0;
      sonicDmState.event.rate = sonicDmState.event.active ? rate : 0;
      sonicDmState.event.lastCheck = Date.now();
      sonicDmSaveState();
      sonicDmUpdatePanel();
    } catch (error) {
    }
  }

  function sonicDmShowTransaction(text, type) {
    const popup = addDom("div", {
      class: `sonic-dm-transaction sonic-dm-${type}`,
      text,
      parent: document.body,
    });
    requestAnimationFrame(() => popup.classList.add("show"));
    setTimeout(() => {
      popup.classList.remove("show");
      setTimeout(() => popup.remove(), 500);
    }, 2500);
  }

  function sonicDmInjectStyles() {
    if (document.getElementById("sonic-dm-tracker-style")) return;
    const style = document.createElement("style");
    style.id = "sonic-dm-tracker-style";
    style.textContent = `
#sonic-dm-tracker {
position: fixed;
top: 8px;
right: 550px;
min-width: 100px;
padding: 6px 9px;
background: var(--sonic-bg);
border: 1px solid rgba(145, 80, 255, .65);
border-radius: 6px;
box-shadow: 0 0 10px rgba(125, 70, 255, .2), inset 0 1px rgba(255,255,255,.06);
color: var(--sonic-text);
font-family: Arial, sans-serif;
cursor: pointer;
z-index: 999999;
user-select: none;
transition: transform .15s ease, box-shadow .15s ease;
}
#sonic-dm-tracker:hover {
transform: translateY(-1px);
box-shadow: 0 0 14px rgba(145, 80, 255, .45), inset 0 1px rgba(255,255,255,.08);
}
.sonic-dm-header { display: flex; align-items: center; justify-content: space-between; font-size: 10px; opacity: .9; }
.sonic-dm-title { font-weight: bold; letter-spacing: .5px; color: #c9a6ff; }
.sonic-dm-status { font-size: 8px; font-weight: bold; color: var(--sonic-gold); }
.sonic-dm-main { margin-top: 2px; }
.sonic-dm-value { font-size: 15px; font-weight: bold; color: #e2c9ff; text-shadow: 0 0 6px rgba(190,100,255,.5); }
.sonic-dm-refund { display: flex; align-items: center; gap: 4px; margin-top: 3px; padding-top: 3px; border-top: 1px solid var(--sonic-border); color: var(--sonic-gold); font-size: 10px; font-weight: bold; }
#sonic-dm-rate { margin-left: auto; font-size: 9px; opacity: .8; }
.sonic-dm-transaction {
position: fixed;
top: 45px;
right: 550px;
padding: 6px 11px;
border-radius: 5px;
background: rgba(10,15,25,.95);
border: 1px solid rgba(255,255,255,.2);
color: var(--sonic-text);
font-weight: bold;
font-size: 11px;
z-index: 1000000;
opacity: 0;
transform: translateY(-8px);
transition: opacity .3s ease, transform .3s ease;
}
.sonic-dm-transaction.show { opacity: 1; transform: translateY(0); }
.sonic-dm-transaction.sonic-dm-spent { color: #ff8f9f; }
.sonic-dm-transaction.sonic-dm-gained { color: #7cff92; }
`;
    document.head.appendChild(style);
  }

  function sonicDmCreatePanel() {
    if (document.getElementById("sonic-dm-tracker")) return;
    sonicDmInjectStyles();
    const panel = addDom("div", { id: "sonic-dm-tracker", parent: document.body });
    panel.innerHTML = `
<div class="sonic-dm-header">
  <span class="sonic-dm-title">💜 AM</span>
  <span class="sonic-dm-status" id="sonic-dm-status"></span>
</div>
<div class="sonic-dm-main">
  <span class="sonic-dm-value" id="sonic-dm-spent">0</span>
</div>
<div class="sonic-dm-refund" id="sonic-dm-refund" style="display:none">
  <span>🎁</span>
  <span id="sonic-dm-refund-value">+0</span>
  <span id="sonic-dm-rate">0%</span>
</div>
`;
    panel.addEventListener("click", () => sonicDmOpenDialog());
    sonicDmUpdatePanel();
    sonicPositionHud();
  }


  // Fenêtre du suivi de matière noire (aux couleurs de SoNiC, titre = pseudo du joueur).
  function sonicDmOpenDialog() {
    document.getElementById("sonic-dm-dialog")?.remove();
    const esc = (v) => String(v ?? "").replace(/[&<>"]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" }[c]));
    const name = String(document.querySelector('meta[name="ogame-player-name"]')?.getAttribute("content") || window.ogame?.playerName || "Joueur").trim();
    if (!document.getElementById("sonic-dm-dialog-css")) {
      const st = document.createElement("style"); st.id = "sonic-dm-dialog-css";
      st.textContent = "#sonic-dm-dialog{position:fixed!important;top:80px;left:80px;width:440px;height:auto;max-width:96vw;z-index:2147483600!important;font:12px Arial,sans-serif;resize:both;overflow:hidden;min-width:300px;min-height:160px}#sonic-dm-dialog .dm-head{cursor:move}#sonic-dm-dialog .dm-box{width:100%;height:100%;max-height:none;box-sizing:border-box;display:flex;flex-direction:column;background:linear-gradient(180deg,#0c2233,#050c13);border:1px solid #2a789b;border-radius:8px;box-shadow:0 12px 40px rgba(0,0,0,.65),0 0 0 1px rgba(255,210,80,.12);color:#dbeaf2;overflow:hidden}#sonic-dm-dialog .dm-head{display:grid;grid-template-columns:26px 1fr 26px;align-items:center;text-align:center;padding:10px 14px;border-bottom:1px solid #174e67;background:linear-gradient(180deg,#102c40,#081720)}#sonic-dm-dialog .dm-title{color:#ffd75a;font-weight:700;font-size:14px;letter-spacing:.5px}#sonic-dm-dialog .dm-sub{color:#9bb7c7;font-size:10px;margin-top:2px}#sonic-dm-dialog .dm-x{border:1px solid #235d7a;border-radius:4px;background:#081722;color:#cce7f3;cursor:pointer;width:26px;height:26px;font-size:15px}#sonic-dm-dialog .dm-x:hover{border-color:#ffd75a;color:#ffd75a}#sonic-dm-dialog .dm-body{padding:12px 14px;overflow:auto}#sonic-dm-dialog .dm-cards{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}#sonic-dm-dialog .dm-card{padding:8px;border:1px solid rgba(255,255,255,.09);border-radius:6px;background:rgba(255,255,255,.03);text-align:center}#sonic-dm-dialog .dm-card small{display:block;color:#8fa6b6;font-size:9px;letter-spacing:.6px;text-transform:uppercase}#sonic-dm-dialog .dm-card b{display:block;margin-top:3px;font-size:15px}#sonic-dm-dialog .sp{color:#ff8f9f}#sonic-dm-dialog .ga{color:#7cff92}#sonic-dm-dialog .ne{color:#e2c9ff}#sonic-dm-dialog .dm-evbtns{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}#sonic-dm-dialog .dm-ev{padding:8px;border:1px solid #235d7a;border-radius:6px;background:#081722;color:#cce7f3;cursor:pointer;font:700 13px Arial,sans-serif}#sonic-dm-dialog .dm-ev:hover{border-color:#ffd75a}#sonic-dm-dialog .dm-ev.on{border-color:#ffd75a;background:#2b2108;color:#ffd75a;box-shadow:0 0 10px rgba(255,215,90,.25)}#sonic-dm-dialog .dm-evnote{margin-top:8px;color:#8fa6b6;font-size:10.5px;line-height:1.45}#sonic-dm-dialog .dm-ref{line-height:1.6;margin-top:10px;padding:7px 10px;border:1px solid rgba(255,215,90,.4);border-radius:6px;background:rgba(255,215,90,.07);color:#ffd75a}#sonic-dm-dialog h4{margin:14px 0 6px;color:#ffd75a;font-size:11px;letter-spacing:.5px}#sonic-dm-dialog .dm-row{display:grid;grid-template-columns:78px 1fr auto;gap:8px;padding:4px 0;border-top:1px solid rgba(255,255,255,.06);font-size:11px;align-items:center}#sonic-dm-dialog .dm-row span:first-child{color:#8fa6b6;font-size:10px}#sonic-dm-dialog .dm-row span:nth-child(2){overflow:hidden;text-overflow:ellipsis;white-space:nowrap}#sonic-dm-dialog .dm-empty{color:#8fa6b6;padding:8px 0}#sonic-dm-dialog .dm-foot{display:flex;justify-content:space-between;align-items:center;gap:8px;padding:10px 14px;border-top:1px solid #174e67}#sonic-dm-dialog .dm-since{color:#8fa6b6;font-size:10px}#sonic-dm-dialog .dm-btn{border:1px solid #a8453f;border-radius:4px;background:#3a1412;color:#ffd0cc;cursor:pointer;font:700 11px Arial,sans-serif;padding:6px 12px}#sonic-dm-dialog .dm-btn:hover{border-color:#ff7b72;background:#521a17}";
      (document.head || document.documentElement).appendChild(st);
    }
    const st8 = sonicDmState;
    const net = (Number(st8.totalGained) || 0) - (Number(st8.totalSpent) || 0);
    const refund = sonicDmGetEstimatedRefund();
    const fmtD = (t) => { try { return new Date(t).toLocaleString((window.sonicLocale?window.sonicLocale():"fr-FR"), { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }); } catch (_) { return ""; } };
    // Une ligne par jour pour les gains (expéditions et divers) ; les dépenses et le remboursement d'événement gardent leur ligne.
    const rowsAll = [], gmap = {};
    (st8.history || []).slice(-120).reverse().forEach((h) => {
      if (h.type === "gained" && !h.event && (!h.description || h.description === "Gain AM détecté")) {
        const d = new Date(h.timestamp), k = d.getFullYear() + "-" + d.getMonth() + "-" + d.getDate();
        if (gmap[k]) { gmap[k].amount += Number(h.amount) || 0; gmap[k].n++; return; }
        const r = { timestamp: h.timestamp, type: "gained", amount: Number(h.amount) || 0, n: 1, description: "Gains AM (expéditions et divers)" };
        gmap[k] = r; rowsAll.push(r); return;
      }
      rowsAll.push(h);
    });
    const hist = rowsAll.slice(0, 12);
    const ev = st8.event, le = st8.lastEvent;
    const fmtP = (t) => { try { return new Date(t).toLocaleString((window.sonicLocale?window.sonicLocale():"fr-FR"), { weekday: "short", day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" }); } catch (_) { return ""; } };
    const left = ev.active ? Math.max(0, ev.end - Date.now()) : 0;
    const leftTxt = left ? (Math.floor(left / 3600000) + " h " + String(Math.floor(left % 3600000 / 60000)).padStart(2, "0") + " min") : "";
    const evHtml = '<h4>Événement de remboursement</h4><div class="dm-evbtns">' + [15, 20, 25].map((r) => '<button type="button" class="dm-ev' + (ev.active && ev.rate === r ? " on" : "") + '" data-rate="' + r + '">' + r + ' %</button>').join("") + '</div>' +
      (ev.active ? '<div class="dm-ref"><b>' + ev.rate + ' % actif</b>' + (ev.source === "image" ? ' · détecté par l\'image de la vue générale' : ev.source === "message" ? ' · lu dans le message de l\'événement' : ' · activé manuellement') + '<br>Période : ' + fmtP(ev.start) + ' → ' + fmtP(ev.end) + ' · reste ' + leftTxt + '<br>Dépensé pendant l\'événement : <b>' + formatNumber(ev.spent || 0) + ' AM</b><br>Remboursement attendu : <b>+' + formatNumber(refund) + ' AM</b></div>'
        : '<div class="dm-evnote">Aucun événement actif. Choisissez le taux de l\'événement en cours (détecté aussi par le message de l\'événement ou par l\'image de la vue générale).' + (le ? '<br>Dernier : ' + le.rate + ' % · dépensé ' + formatNumber(le.spent) + ' AM · remboursement +' + formatNumber(le.refund) + ' AM' : '') + '</div>');
    const wrap = document.createElement("div"); wrap.id = "sonic-dm-dialog";
    wrap.innerHTML = '<div class="dm-box" role="dialog"><div class="dm-head"><span></span><div><div class="dm-title">💜 ' + esc(name) + '</div><div class="dm-sub">Suivi de la matière noire</div></div><button type="button" class="dm-x" title="Fermer">×</button></div><div class="dm-body"><div class="dm-cards"><div class="dm-card"><small>Dépensé</small><b class="sp">−' + formatNumber(st8.totalSpent) + '</b></div><div class="dm-card"><small>Gagné</small><b class="ga">+' + formatNumber(st8.totalGained) + '</b></div><div class="dm-card"><small>Bilan net</small><b class="ne">' + (net >= 0 ? "+" : "−") + formatNumber(Math.abs(net)) + '</b></div></div>' +
      evHtml +
      '<h4>Derniers mouvements</h4>' + (hist.length ? hist.map((h) => '<div class="dm-row"' + (h.event ? ' style="background:rgba(255,215,0,.12);border-left:3px solid #ffd700"' : '') + '><span>' + fmtD(h.timestamp) + '</span><span title="' + esc(h.description) + '">' + (h.event ? "🎁 " : "") + esc(h.description || "") + (h.n > 1 ? " ×" + h.n : "") + '</span><b class="' + (h.type === "spent" ? "sp" : "ga") + '">' + (h.type === "spent" ? "−" : "+") + formatNumber(h.amount) + '</b></div>').join("") : '<div class="dm-empty">Aucun mouvement enregistré pour l\'instant.</div>') +
      '</div><div class="dm-foot"><span class="dm-since">Depuis le ' + esc(new Date(st8.lastReset).toLocaleString((window.sonicLocale?window.sonicLocale():"fr-FR"))) + '</span><button type="button" class="dm-btn">Réinitialiser</button></div></div>';
    const done = () => { try { document.removeEventListener("keydown", onKey, true); wrap.remove(); } catch (_) {} };
    const onKey = (e) => { if (e.key === "Escape") { e.preventDefault(); e.stopPropagation(); done(); } };
    // Tableau flottant : déplaçable par l'en-tête, redimensionnable (coin bas-droit), position et taille mémorisées.
    const DMUI = "SoNiC_Suite_DmDialogUi_V1";
    const ui = (() => { try { return JSON.parse(localStorage.getItem(DMUI) || "{}") || {}; } catch (_) { return {}; } })();
    const save = (patch) => { Object.assign(ui, patch); try { localStorage.setItem(DMUI, JSON.stringify(ui)); } catch (_) {} };
    if (Number.isFinite(ui.left) && Number.isFinite(ui.top)) { wrap.style.left = Math.max(0, Math.min(window.innerWidth - 80, ui.left)) + "px"; wrap.style.top = Math.max(0, Math.min(window.innerHeight - 40, ui.top)) + "px"; }
    if (ui.w >= 300) wrap.style.width = Math.min(ui.w, window.innerWidth - 10) + "px";
    if (ui.h >= 160) wrap.style.height = Math.min(ui.h, window.innerHeight - 10) + "px";
    wrap.querySelector(".dm-head").addEventListener("pointerdown", (e) => {
      if (e.target.closest("button")) return;
      e.preventDefault();
      const r = wrap.getBoundingClientRect(), dx = e.clientX - r.left, dy = e.clientY - r.top;
      const mv = (ev) => { wrap.style.left = Math.max(0, Math.min(window.innerWidth - 80, ev.clientX - dx)) + "px"; wrap.style.top = Math.max(0, Math.min(window.innerHeight - 30, ev.clientY - dy)) + "px"; };
      const up = () => { document.removeEventListener("pointermove", mv, true); document.removeEventListener("pointerup", up, true); const b = wrap.getBoundingClientRect(); save({ left: b.left, top: b.top }); };
      document.addEventListener("pointermove", mv, true); document.addEventListener("pointerup", up, true);
    });
    try { let t = 0; new ResizeObserver(() => { clearTimeout(t); t = setTimeout(() => { if (wrap.isConnected && wrap.style.height) save({ w: wrap.offsetWidth, h: wrap.offsetHeight }); }, 300); }).observe(wrap); } catch (_) {}
    wrap.querySelector(".dm-x").addEventListener("click", done);
    wrap.querySelectorAll(".dm-ev").forEach((b) => b.addEventListener("click", () => { sonicDmSetEventRate(Number(b.dataset.rate)); done(); sonicDmOpenDialog(); }));
    wrap.querySelector(".dm-btn").addEventListener("click", async () => {
      const ok = await window.sonicConfirmUI({ title: "Réinitialiser le suivi", text: "Remettre à zéro les dépenses et gains de matière noire enregistrés ?" });
      if (ok) { sonicDmResetTracker(true); done(); }
    });
    document.addEventListener("keydown", onKey, true);
    document.documentElement.appendChild(wrap);
  }

  function sonicDmResetTracker(skipConfirm) {
    if (
      skipConfirm !== true && !sonicConfirm(
        "Réinitialiser toutes les statistiques de Matière Noire ?\n\nLes dépenses et gains enregistrés seront remis à zéro.",
      )
    )
      return;
    const currentAM = sonicDmGetCurrentAmount();
    sonicDmState.totalSpent = 0;
    sonicDmState.totalGained = 0;
    sonicDmState.lastKnownAM = currentAM;
    sonicDmState.lastReset = Date.now();
    sonicDmState.history = [];
    sonicDmState.event.spent = 0;
    sonicDmSaveState();
    sonicDmUpdatePanel();
  }
  window.sonicResetDarkMatterTracker = sonicDmResetTracker;
  window.SoNiCDarkMatter = {
    getState: () => sonicDmState,
    getHistory: () => sonicDmState.history,
    reset: sonicDmResetTracker,
  };

  function sonicDmTick() {
    if (!document.getElementById("sonic-dm-tracker") && settings.darkMatterTrackingEnabled) {
      sonicDmCreatePanel();
    }
    sonicDmCheckAmount();
    sonicDmScanBanner();
    sonicDmScanMessages();
  }

  function sonicDmInit() {
    if (sonicIsEmpireStandalonePage()) return;
    if (!settings.darkMatterTrackingEnabled) return;
    sonicDmCreatePanel();
    sonicDmWatchActions();
    sonicDmCheckAmount();
    sonicDmScanBanner();
    sonicDmCheckEventStatus();
    window.sonicEvery('dm-tick', sonicDmTick, SONIC_DM_CHECK_INTERVAL);
  }
  const SONIC_TEMP_ITEMS_KEY = "SoNiC_Suite_TemporaryItems";
  let sonicTemporaryItemsWatcherActive = false;

  function sonicLoadTemporaryItems() {
    return loadJSON(SONIC_TEMP_ITEMS_KEY, []);
  }
  function sonicSaveTemporaryItems(items) {
    saveJSON(SONIC_TEMP_ITEMS_KEY, items);
  }

  // Images des objets : le jeu les héberge lui-même (/cdn/img/item-images/<hash>.png). On retient le chemin lu dans l'inventaire affiché,
  // sans aucune requête supplémentaire ; l'image est ensuite affichée depuis le serveur du jeu.
  const SONIC_ITEM_IMAGES_KEY = "SoNiC_Suite_ItemImages";
  function sonicItemImagesLoad() { const v = loadJSON(SONIC_ITEM_IMAGES_KEY, {}); return v && typeof v === "object" ? v : {}; }
  function sonicItemNameKey(name) { return "name:" + String(name || "").replace(/^\s*\[[^\]]*\]\s*/, "").toLowerCase().replace(/\s+/g, " ").trim(); }
  function sonicItemImagePath(text) {
    const m = String(text || "").match(/(?:https?:)?(?:\/\/[^\/"')\s]+)?(\/cdn\/img\/item-images\/[0-9a-f]{20,64}\.(?:png|jpg|jpeg|gif|webp))/i);
    return m ? m[1] : "";
  }
  function sonicCaptureItemImages() {
    try {
      const els = document.querySelectorAll(".item_img");
      if (!els.length) return;
      const map = sonicItemImagesLoad();
      let changed = false;
      els.forEach((el) => {
        const path = sonicItemImagePath(el.getAttribute("style") || "");
        if (!path) return;
        const a = el.querySelector("a.detail_button, a[ref]");
        const ref = a?.getAttribute("ref") || "";
        const title = (a?.getAttribute("data-tooltip-title") || a?.getAttribute("title") || "").split("|")[0];
        const put = (k) => { if (k && map[k] !== path) { map[k] = path; changed = true; } };
        put(ref);
        if (title) put(sonicItemNameKey(title));
      });
      if (changed) saveJSON(SONIC_ITEM_IMAGES_KEY, map);
    } catch (_) {}
  }
  function sonicItemImageFor(item) {
    if (item?.image) return String(item.image);
    const map = sonicItemImagesLoad();
    return map[String(item?.id || "")] || map[sonicItemNameKey(item?.name)] || "";
  }
  const SONIC_TEMP_INVENTORY_STATE_KEY = "SoNiC_Suite_TemporaryInventoryState";






  function sonicParseRemainingTime(text) {
    if (!text) return null;
    const normalized = String(text)
      .replace(/\u00a0/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    const match = normalized.match(
      /Temps restant\s*:\s*(.*?)(?:Phase actuelle|Durée|$)/i,
    );
    if (!match) return null;
    const timeText = match[1].trim();

    let weeks = 0, days = 0, hours = 0, minutes = 0, seconds = 0;
    const weekMatch = timeText.match(/(\d+)\s*s(?=\s*\d+\s*j)/i);
    if (weekMatch) weeks = Number(weekMatch[1]);
    const dayMatch = timeText.match(/(\d+)\s*j/i);
    const hourMatch = timeText.match(/(\d+)\s*h/i);
    const minuteMatch = timeText.match(/(\d+)\s*m/i);
    const secondMatches = [...timeText.matchAll(/(\d+)\s*s/gi)];
    if (secondMatches.length > 0) {
      const lastSecondMatch = secondMatches[secondMatches.length - 1];
      if (secondMatches.length > 1 || !weekMatch) {
        seconds = Number(lastSecondMatch[1]);
      }
    }
    if (dayMatch) days = Number(dayMatch[1]);
    if (hourMatch) hours = Number(hourMatch[1]);
    if (minuteMatch) minutes = Number(minuteMatch[1]);

    const totalSeconds =
      weeks * 7 * 24 * 3600 + days * 24 * 3600 + hours * 3600 + minutes * 60 + seconds;
    if (!Number.isFinite(totalSeconds) || totalSeconds <= 0) return null;
    return totalSeconds;
  }


  function sonicCleanTemporaryItemName(value) {
    if (!value) return "";
    let text = String(value)
      .replace(/\u00a0/g, " ")
      .replace(/<[^>]*>/g, " ")
      .replace(/&nbsp;|&amp;/g, " ")
      .replace(/\s+/g, " ")
      .trim();
    text = text.split(/\s*\|\s*/)[0].trim();
    text = text
      .replace(/\s*[·|]\s*Expire(?:\s+le)?\s+.*$/i, "")
      .replace(/\s+Expire\s+\d{1,2}\/\d{1,2}.*$/i, "")
      .replace(/\b[a-f0-9]{40}\b/gi, "")
      .replace(/\s*[,;·]\s*(?=[,;·]|$)/g, "")
      .replace(/\s{2,}/g, " ")
      .trim();
    text = text.replace(/^Temps restant\s*:\s*/i, "").trim();
    return text;
  }


  function sonicExtractInventoryExpirationObjects(root, depth = 0, path = "inventoryObj") {
    if (!root || depth > 5) return [];
    const found = [];
    if (Array.isArray(root)) {
      root.forEach((value, index) => {
        found.push(...sonicExtractInventoryExpirationObjects(value, depth + 1, `${path}[${index}]`));
      });
      return found;
    }
    if (typeof root !== "object") return found;

    const obj = root;
    const name =
      sonicCleanTemporaryItemName(obj.name) ||
      sonicCleanTemporaryItemName(obj.itemName) ||
      sonicCleanTemporaryItemName(obj.title) ||
      sonicCleanTemporaryItemName(obj.label);

    const id = obj.id ?? obj.itemId ?? obj.itemID ?? obj.inventoryId ?? obj.inventoryItemId;
    const quantity = Number(obj.quantity ?? obj.amount ?? obj.count ?? 1) || 1;

    const absoluteCandidates = [
      obj.expiresAt, obj.expirationAt, obj.expirationTimestamp, obj.expiryTimestamp,
      obj.endTimestamp, obj.endTime, obj.validUntil, obj.validUntilTimestamp,
    ];
    let expiresAt = absoluteCandidates
      .map(Number)
      .find((value) => Number.isFinite(value) && value > 100000000000);

    let remainingSeconds = null;
    const remainingCandidates = [
      obj.remainingSeconds, obj.secondsRemaining, obj.remainingTime,
      obj.durationRemaining, obj.timeRemaining, obj.remaining,
    ];
    for (const value of remainingCandidates) {
      if (typeof value === "number" && Number.isFinite(value) && value > 0) {
        remainingSeconds = value > 100000 ? value / 1000 : value;
        break;
      }
      if (typeof value === "string") {
        const parsed = sonicParseRemainingTime(value) || sonicParseRemainingTime(`Temps restant : ${value}`);
        if (parsed) {
          remainingSeconds = parsed;
          break;
        }
      }
    }
    if (!expiresAt && remainingSeconds) expiresAt = Date.now() + remainingSeconds * 1000;

    const hasExpiration = Number.isFinite(expiresAt) && expiresAt > Date.now();
    if (hasExpiration && (name || id)) {
      found.push({
        id: String(id || `inventory-${sonicCleanTemporaryItemName(name)}`),
        name: name || "Objet à durée limitée",
        quantity,
        scannedAt: Date.now(),
        expiresAt,
        source: "inventoryObj",
        sourcePath: path,
      });
    }

    Object.keys(obj).forEach((key) => {
      if (["parent", "prototype", "constructor"].includes(key)) return;
      const value = obj[key];
      if (value && typeof value === "object") {
        found.push(...sonicExtractInventoryExpirationObjects(value, depth + 1, `${path}.${key}`));
      }
    });
    return found;
  }

  function sonicGetActiveTemporaryItems() {
    const now = Date.now();
    const items = sonicLoadTemporaryItems()
      .filter((item) => item.expiresAt > now)
      .sort((a, b) => a.expiresAt - b.expiresAt);
    sonicSaveTemporaryItems(items);
    return items;
  }

  function sonicOpenNativeInventory() {
    try {
      const native = document.querySelector(
        'a[data-tooltip-title="Inventaire"], a[href*="component=shop"][href*="page=inventory"]'
      );
      if (native?.href) {
        window.location.href = native.href;
        return;
      }
    } catch (_) {}

    window.location.href = `${location.origin}/game/index.php?page=ingame&component=shop#page=inventory`;
  }

  function sonicEscapeInventoryText(value) {
    return String(value ?? "")
      .replace(/&/g, "&amp;")
      .replace(/</g, "&lt;")
      .replace(/>/g, "&gt;")
      .replace(/"/g, "&quot;")
      .replace(/'/g, "&#39;");
  }

  function sonicRefreshInventoryExpirationIndicator() {
    const indicator = document.getElementById("sonic-inventory-expiration-indicator");
    if (!indicator) return;

    const items = sonicGetActiveTemporaryItems();
    indicator.classList.remove("is-red", "is-yellow", "is-green", "is-none");
    const timerEl = document.getElementById("sonic-inventory-timer");
    if (timerEl) {
      timerEl.textContent = "";
      timerEl.classList.remove("is-red");
      if (settings.inventoryTimer === true && items.length) {
        const left = Number(items[0].expiresAt) - Date.now();
        if (left > 0 && left <= 24 * 3600 * 1000) {
          const t = Math.floor(left / 1000);
          const h = Math.floor(t / 3600), m = Math.floor((t % 3600) / 60), sec = t % 60;
          timerEl.textContent = h > 0 ? `${h}h${String(m).padStart(2, "0")}` : `${m}:${String(sec).padStart(2, "0")}`;
          timerEl.classList.toggle("is-red", left <= 12 * 3600 * 1000);
        }
      }
    }
    if (!window.__sonicInvTimerTick) window.__sonicInvTimerTick = setInterval(() => { try { sonicRefreshInventoryExpirationIndicator(); } catch (_) {} }, 1000);

    if (!items.length) {
      indicator.classList.add("is-none");
      indicator.title = "Aucun objet à durée limitée";
      return;
    }

    const remaining = Math.max(0, Number(items[0].expiresAt) - Date.now());
    let state = "is-green";
    let label = "Plus de 24 h";
    if (remaining <= 12 * 60 * 60 * 1000) {
      state = "is-red";
      label = "Expiration dans moins de 12 h";
    } else if (remaining <= 24 * 60 * 60 * 1000) {
      state = "is-yellow";
      label = "Expiration dans moins de 24 h";
    }

    indicator.classList.add(state);
    indicator.title = `${label} : ${items[0].name || "Objet à durée limitée"}`;
  }

  function sonicToggleFullInventoryList() {
    if (sonicIsEmpireStandalonePage()) return;

    const existing = document.getElementById("sonic-full-inventory-list");
    if (existing) {
      existing.remove();
      return;
    }

    const now = Date.now();
    let items = sonicGetActiveTemporaryItems().map(item => ({
        id: String(item.id || ""),
        name: String(item.name || "Objet temporaire"),
        quantity: Math.max(1, Number(item.quantity) || 1),
        category: item.category ? String(item.category) : "",
        rarity: item.rarity ? String(item.rarity) : "",
        image: sonicItemImageFor(item),
        expiresAt: Number(item.expiresAt) || 0
      })).filter(item => item.expiresAt > now);

    items.sort((a, b) => a.expiresAt - b.expiresAt);

    const dropdown = addDom("div", {
      id: "sonic-full-inventory-list",
      parent: document.body,
    });

    const formatDate = value => new Date(value).toLocaleString((window.sonicLocale?window.sonicLocale():"fr-FR"), {
      day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit"
    });

    dropdown.innerHTML = `
      <div class="sonic-full-inventory-head">
        <div>
          <b>⌛ OBJETS À DURÉE LIMITÉE</b>
          <span>${items.length} objet${items.length > 1 ? "s" : ""} · expiration la plus proche en premier</span>
        </div>
        <div class="sonic-full-inventory-actions">
          <button type="button" data-sonic-open-native>Inventaire</button>
          <button type="button" data-sonic-inventory-close>×</button>
        </div>
      </div>
      <div class="sonic-full-inventory-body">
        ${items.length ? items.map(item => {
          const meta = `Expire ${formatDate(item.expiresAt)}`;
          const shown = String(item.name).replace(/^\s*\[[^\]]*\]\s*/, "") || item.name;
          const icon = item.image
            ? `<img class="sonic-full-inventory-ico" src="${sonicEscapeInventoryText(location.origin + item.image)}" alt="" loading="lazy">`
            : `<span class="sonic-full-inventory-ico is-empty">⌛</span>`;
          return `<div class="sonic-full-inventory-row is-temporary">
            ${icon}
            <div class="sonic-full-inventory-main">
              <b>${sonicEscapeInventoryText(shown)}</b>
              <small>${sonicEscapeInventoryText(meta)}</small>
            </div>
          </div>`;
        }).join("") : '<div class="sonic-full-inventory-empty">Aucun objet à durée limitée actif.</div>'}
      </div>`;

    const button = document.getElementById("sonic-inventory-info-button");
    if (button) {
      const br = button.getBoundingClientRect();
      const panelWidth = 360;
      const left = Math.max(
        8,
        Math.min(
          Math.round(br.left - panelWidth + br.width),
          Math.max(8, window.innerWidth - panelWidth - 8)
        )
      );
      dropdown.style.top = `${Math.round(br.bottom + 6)}px`;
      dropdown.style.left = `${left}px`;
    }

    // Position / taille mémorisées ; déplaçable par l'en-tête, redimensionnable par le coin bas-droit.
    const INV_UI_KEY = "SoNiC_Suite_InventoryPanelUi_V1";
    const invUi = (() => { try { return JSON.parse(localStorage.getItem(INV_UI_KEY) || "{}") || {}; } catch (_) { return {}; } })();
    const invSave = (patch) => { try { localStorage.setItem(INV_UI_KEY, JSON.stringify({ ...invUi, ...patch })); Object.assign(invUi, patch); } catch (_) {} };
    if (Number.isFinite(invUi.left) && Number.isFinite(invUi.top)) {
      dropdown.style.left = Math.max(0, Math.min(window.innerWidth - 80, invUi.left)) + "px";
      dropdown.style.top = Math.max(0, Math.min(window.innerHeight - 40, invUi.top)) + "px";
    }
    if (invUi.w >= 240) dropdown.style.width = Math.min(invUi.w, window.innerWidth - 10) + "px";
    if (invUi.h >= 120) { dropdown.style.height = Math.min(invUi.h, window.innerHeight - 10) + "px"; dropdown.style.maxHeight = "none"; }
    const invHead = dropdown.querySelector(".sonic-full-inventory-head");
    if (invHead) {
      invHead.style.cursor = "move";
      invHead.title = "Glisser pour déplacer · tirer le coin bas-droit pour redimensionner";
      invHead.addEventListener("pointerdown", (e) => {
        if (e.target.closest("button")) return;
        e.preventDefault();
        const r = dropdown.getBoundingClientRect(), dx = e.clientX - r.left, dy = e.clientY - r.top;
        const mv = (ev) => { dropdown.style.left = Math.max(0, Math.min(window.innerWidth - 80, ev.clientX - dx)) + "px"; dropdown.style.top = Math.max(0, Math.min(window.innerHeight - 30, ev.clientY - dy)) + "px"; };
        const up = () => { document.removeEventListener("pointermove", mv, true); document.removeEventListener("pointerup", up, true); const b = dropdown.getBoundingClientRect(); invSave({ left: b.left, top: b.top }); };
        document.addEventListener("pointermove", mv, true); document.addEventListener("pointerup", up, true);
      });
    }
    try { let t = 0; new ResizeObserver(() => { clearTimeout(t); t = setTimeout(() => { if (dropdown.isConnected && dropdown.style.height) invSave({ w: dropdown.offsetWidth, h: dropdown.offsetHeight }); }, 300); }).observe(dropdown); } catch (_) {}

    dropdown.querySelector("[data-sonic-inventory-close]")?.addEventListener("click", () => dropdown.remove());
    dropdown.querySelector("[data-sonic-open-native]")?.addEventListener("click", () => {
      dropdown.remove();
      sonicOpenNativeInventory();
    });

    setTimeout(() => {
      document.addEventListener("mousedown", function closeTemporaryDropdown(event) {
        if (dropdown.contains(event.target) || button?.contains(event.target)) return;
        dropdown.remove();
        document.removeEventListener("mousedown", closeTemporaryDropdown, true);
      }, true);
    }, 0);
  }


