    let sonicTargetType = 1;
    function sonicSyncTargetTypeButtons() {
      targetDebrisBtn.classList.toggle("sonic-target-type-selected", sonicTargetType === 2);
      targetPlanetBtn.classList.toggle("sonic-target-type-selected", sonicTargetType === 1);
      targetMoonBtn.classList.toggle("sonic-target-type-selected", sonicTargetType === 3);
    }
    // Application automatique de la cible (plus de bouton « Appliquer »).
    function sonicApplyTargetFromFields() {
      const fleet = window.fleetDispatcher;
      if (!fleet) return;
      const galaxy = Number(targetGalaxyInput.value) || 0;
      const system = Number(targetSystemInput.value) || 0;
      const position = Number(targetPositionInput.value) || 0;
      if (!galaxy || !system || !position) return;
      setFleetTarget(fleet, { galaxy, system, position, type: sonicTargetType });
      if (typeof fleet.refresh === "function") fleet.refresh();
      setTimeout(() => { try { sonicRefreshTripInfo(); } catch (_) {} }, 120);
    }
    let sonicTargetApplyTimer = 0;
    function sonicScheduleTargetApply(delay = 350) {
      clearTimeout(sonicTargetApplyTimer);
      sonicTargetApplyTimer = setTimeout(sonicApplyTargetFromFields, delay);
    }
    [targetGalaxyInput, targetSystemInput, targetPositionInput].forEach((input) => {
      input.addEventListener("input", () => sonicScheduleTargetApply(350));
      input.addEventListener("change", () => sonicScheduleTargetApply(0));
      input.addEventListener("keydown", (event) => {
        if (event.key === "Enter") { event.preventDefault(); sonicScheduleTargetApply(0); }
      });
    });
    targetPlanetBtn.addEventListener("click", () => { sonicTargetType = 1; sonicSyncTargetTypeButtons(); try { sonicApplyPanelSprites(); } catch (_) {} sonicScheduleTargetApply(0); });
    targetDebrisBtn.addEventListener("click", () => { sonicTargetType = 2; sonicSyncTargetTypeButtons(); try { sonicApplyPanelSprites(); } catch (_) {} sonicScheduleTargetApply(0); });
    targetMoonBtn.addEventListener("click", () => { sonicTargetType = 3; sonicSyncTargetTypeButtons(); try { sonicApplyPanelSprites(); } catch (_) {} sonicScheduleTargetApply(0); });
    function sonicRefreshTargetFields() {
      const fleet = window.fleetDispatcher;
      const target = fleet?.realTarget;
      if (!target) return;
      if (document.activeElement !== targetGalaxyInput) targetGalaxyInput.value = target.galaxy || "";
      if (document.activeElement !== targetSystemInput) targetSystemInput.value = target.system || "";
      if (document.activeElement !== targetPositionInput) targetPositionInput.value = target.position || "";
      sonicTargetType = Number(target.type) === 3 ? 3 : (Number(target.type) === 2 ? 2 : 1);
      sonicSyncTargetTypeButtons();
      try { sonicApplyPanelSprites(); } catch (_) {}
    }
