  const SONIC_CONSTRUCTION_FLEET_HOST='sonic-construction-fleet-load';
  function sonicConstructionRenderFleetPanel(fleet, payload) {
    if (!fleet || !payload) return;
    const panel = document.getElementById("sonic-transport-panel");
    if (!panel) return;
    panel.dataset.sonicConstructionMode = "1";
    panel.dataset.sonicConstructionMission = String(Number(payload.mission) === 4 ? 4 : 3);
    panel.dataset.sonicConstructionTarget = [payload.target?.galaxy, payload.target?.system, payload.target?.position].filter(Boolean).join(":");
    const inputs = sonicGetTransportResourceInputs();
    const vals = {
      metal: Math.max(0, Math.floor(Number(payload.metal) || 0)),
      crystal: Math.max(0, Math.floor(Number(payload.crystal) || 0)),
      deuterium: Math.max(0, Math.floor(Number(payload.deuterium) || 0)),
    };
    Object.entries(inputs).forEach(([key, input]) => {
      if (input) input.value = String(vals[key]);
    });
    const title = panel.querySelector(".sonic-transport-title");
    const subtitle = panel.querySelector(".sonic-transport-subtitle");
    if (title) title.textContent = "CHARGEMENT SoNiC";
    if (subtitle) subtitle.textContent = `${Number(payload.mission) === 4 ? "Stationner" : "Transport"} · cible ${panel.dataset.sonicConstructionTarget || "—"}`;
    sonicRefreshTransportShipSelector();
    sonicRefreshTransportPreview();
    panel.scrollIntoView({block:"nearest"});
  }
  function sonicConstructionHideFleetPanel(){ const p=document.getElementById("sonic-transport-panel"); if(p){ delete p.dataset.sonicConstructionMode; delete p.dataset.sonicConstructionMission; delete p.dataset.sonicConstructionTarget; }}
  function applyFleetSelection() {
    if (!isFleetDispatchPage()) return;

    let constructionPending = null;
    const constructionMode = new URLSearchParams(window.location.search).get('sonicConstruction') === '1';
    if(constructionMode){
      try {
        const raw = sessionStorage.getItem('SoNiC_ConstructionSend');
        if(raw) constructionPending = JSON.parse(raw);
      } catch (_) {}
    }

    const context = loadRaidContext();
    if (!context && !constructionPending) return;
    const fleet = window.fleetDispatcher;
    if (!fleet || !Array.isArray(fleet.shipsOnPlanet)) {
      setTimeout(applyFleetSelection, 40);
      return;
    }
    if (fleet.currentPage && fleet.currentPage !== "fleet1") {
      setTimeout(applyFleetSelection, 40);
      return;
    }

    if (context && !constructionPending) {
      window.__sonicUserMissionChosen = true;
      selectMissionRobust(fleet, 1);
      sonicSelectedMissionId = 1;
      sonicUpdateMissionButtonsState();
      sonicUpdateTransportShipButtonsState();
    }

    if (constructionPending) {
      refreshShipCapacityCache();
      try {
        const target = constructionPending.target || {};
        if (typeof setFleetTarget === "function" && target.galaxy && target.system && target.position) {
          setFleetTarget(fleet, {
            galaxy: Number(target.galaxy), system: Number(target.system),
            position: Number(target.position), type: Number(target.type) || 1
          });
        }

        const constructionMission = Number(constructionPending.mission) === 4 ? 4 : 3;
        if (typeof selectMissionRobust === "function") selectMissionRobust(fleet, constructionMission);

        const grossResources = {
          metal: Math.max(0, Math.floor(Number(constructionPending.grossResources?.metal ?? constructionPending.metal) || 0)),
          crystal: Math.max(0, Math.floor(Number(constructionPending.grossResources?.crystal ?? constructionPending.crystal) || 0)),
          deuterium: Math.max(0, Math.floor(Number(constructionPending.grossResources?.deuterium ?? constructionPending.deuterium) || 0))
        };
        const resources = {
          metal: Math.max(0, Math.floor(Number(constructionPending.resources?.metal) || 0)),
          crystal: Math.max(0, Math.floor(Number(constructionPending.resources?.crystal) || 0)),
          deuterium: Math.max(0, Math.floor(Number(constructionPending.resources?.deuterium) || 0))
        };

        sonicPendingResourceLoad = {...resources, setAt: Date.now()};
        sonicConstructionRenderFleetPanel(fleet, {...constructionPending, ...resources});

        const inputs = sonicGetTransportResourceInputs();
        if (inputs.metal) inputs.metal.value = String(resources.metal);
        if (inputs.crystal) inputs.crystal.value = String(resources.crystal);
        if (inputs.deuterium) inputs.deuterium.value = String(resources.deuterium);

        sonicSelectedMissionId = constructionMission;
        sonicUpdateMissionButtonsState();
        sonicUpdateTransportShipButtonsState();

        const clearIds = [202, 203, 209, 210, 219];
        clearIds.forEach(id => {
          if (typeof fleet.selectShip === "function") fleet.selectShip(id, 0);
        });

        const total = Math.max(0,
          Math.floor(Number(resources.metal) || 0) +
          Math.floor(Number(resources.crystal) || 0) +
          Math.floor(Number(resources.deuterium) || 0)
        );

        const preferredKey = settings.transportPreferredShip || sonicSelectedTransportShip || "pt";
        const preferredId = Number(SONIC_TRANSPORT_SHIPS[preferredKey]?.id || 202);
        const capacity = getShipCapacity(preferredId);
        const available = sonicGetAvailableShipCount(fleet, preferredId);
        const needed = capacity > 0 ? Math.ceil(total / capacity) : 0;
        const selected = Math.max(0, Math.min(available, needed));

        if (selected > 0 && typeof fleet.selectShip === "function") {
          fleet.selectShip(preferredId, selected);
        }

        let remaining = Math.max(0, total - selected * capacity);
        if (remaining > 0 && typeof fleet.selectShip === "function") {
          [202, 203, 219].filter(id => Number(id) !== preferredId).forEach(id => {
            if (remaining <= 0) return;
            const cap = getShipCapacity(id);
            const avail = sonicGetAvailableShipCount(fleet, id);
            if (!cap || !avail) return;
            const n = Math.min(avail, Math.ceil(remaining / cap));
            if (n > 0) {
              fleet.selectShip(id, n);
              remaining -= n * cap;
            }
          });
        }

        fleet.cargoMetal = Math.min(resources.metal, Number(fleet.metalOnPlanet) || 0);
        fleet.cargoCrystal = Math.min(resources.crystal, Number(fleet.crystalOnPlanet) || 0);
        fleet.cargoDeuterium = Math.min(resources.deuterium, Number(fleet.deuteriumOnPlanet) || 0);
        if (typeof fleet.refresh === "function") fleet.refresh();

        const selectedSummary = {};
        [202, 203, 219].forEach(id => {
          const ship = typeof fleet.findShip === "function" ? fleet.findShip(id) : null;
          const n = Number(ship?.number || 0);
          if (n > 0) selectedSummary[id] = n;
        });
        window.sonicLog('[SoNiC Construction] préselection', {
          mode: 'construction', mission: constructionMission,
          resources, ships: selectedSummary
        });
        return;
      } catch(e) {
        console.warn('[SoNiC Construction] préparation flotte échouée', e);
      }
    }

    sonicConstructionHideFleetPanel();
    refreshShipCapacityCache();
    const params = new URLSearchParams(window.location.search);
    const hasTarget =
      params.has("galaxy") || params.has("system") || params.has("position");
    if (!hasTarget) {
      clearRaidContext();
      if (isMessagesPage() === false) openMessages();
      return;
    }
    const amount = calculateRequiredShips(
      Number(context.wave1),
      Number(context.ageMilliseconds),
      Number(context.shipId),
      Number(context.targetType) || 1,
    );
    setShipAmount(fleet, Number(context.shipId), amount);
    fleet.shipsOnPlanet.forEach((ship) => {
      if (Number(ship.id) !== Number(context.shipId)) {
        setShipAmount(fleet, Number(ship.id), 0);
      }
    });
    selectMissionRobust(fleet, 1);
    if (typeof fleet.refresh === "function") fleet.refresh();
    if (typeof fleet.focusSubmitFleet1 === "function")
      fleet.focusSubmitFleet1();
  }
  function sonicLastSendWasAttack() {
    try {
      const info = JSON.parse(sessionStorage.getItem("SoNiC_LastSendInfo") || "null");
      if (!info || Date.now() - Number(info.at || 0) > 120000) return null; // pas d'envoi récent
      return !info.mission || info.mission === 1 || info.mission === 2;
    } catch (_) { return null; }
  }
  function handleFleetReturn(force = false) {
    // Un envoi récent qui n'est pas une attaque (expédition, recycler…) ne doit jamais ramener aux messages.
    if (sonicLastSendWasAttack() === false) return;
    // Sans envoi d'attaque récent, un contexte de raid ancien ne déclenche pas de retour automatique.
    if (!force && sonicLastSendWasAttack() === null) return;
    const context = loadRaidContext();
    if (!context) {
      if (force && sonicRaidReturnPending()) {
        sonicMarkInactiveRaidCompletedOnReturn();
        openMessages();
      }
      return;
    }
    if (!force && isFleetDispatchPage()) {
      const params = new URLSearchParams(window.location.search);
      const hasTarget =
        params.has("galaxy") || params.has("system") || params.has("position");
      if (hasTarget) return;
    }

    if (context.autoNextWave === true && settings.raidWaveAutoEnabled !== false) {
      const nextContext = advanceRaidWaveContext(context);
      if (nextContext) {
        const amount = calculateRequiredShips(
          Number(nextContext.wave1),
          Number(nextContext.ageMilliseconds),
          Number(nextContext.shipId),
          Number(nextContext.targetType) || 1,
        );
        if (amount > 0) {
          const [galaxy, system, position] = String(nextContext.coords || "").split(":");
          const url = new URL(window.location.href);
          url.search = "";
          url.searchParams.set("page", "ingame");
          url.searchParams.set("component", "fleetdispatch");
          url.searchParams.set("galaxy", galaxy);
          url.searchParams.set("system", system);
          url.searchParams.set("position", position);
          url.searchParams.set("type", String(nextContext.targetType || 1));
          url.searchParams.set("mission", "1");
          url.searchParams.set(`am${nextContext.shipId}`, String(amount));
          url.searchParams.set("sonicmode", SONIC_MODE_QUICK_RAID);
          if (nextContext.messageId) url.searchParams.set("sonicmsg", nextContext.messageId);
          window.location.href = url.toString();
          return;
        }
      }
    }

    sonicMarkInactiveRaidCompletedOnReturn();
    clearRaidContext();
    openMessages();
  }
  function openMessages() {
    if (isMessagesPage()) return;
    const current = new URL(window.location.href);
    const url = new URL(current.origin + current.pathname);
    url.searchParams.set("page", "ingame");
    url.searchParams.set("component", "messages");
    const cp = current.searchParams.get("cp");
    if (cp) url.searchParams.set("cp", cp);
    window.location.href = url.toString();
  }

  // Erreur serveur sur la page flotte pendant une chaîne de pillage : retour automatique aux messages.
  (function sonicInstallRaidErrorReturn() {
    let fired = false;
    const check = (node) => {
      if (fired || settings.raidErrorReturnToMessages === false) return;
      if (!(node instanceof Element) || !isFleetDispatchPage()) return;
      const text = String(node.textContent || "");
      if (!/LOCA_ERROR_|INQUIRY_NOT_WO/i.test(text)) return;
      if (/INQUIRY_NOT_WO/i.test(text) && (window.__sonicInquiryRetry || 0) < 2) return;
      let inChain = false;
      try { inChain = !!loadRaidContext() || !!sonicLoadInactiveRaidChain().activeMessageId; } catch (_) {}
      if (!inChain) return;
      // Spécifique aux pillages lancés depuis les messages : jamais pour expédition, recyclage, transport…
      const qp = new URLSearchParams(window.location.search);
      const urlMission = Number(qp.get("mission")) || 0;
      const liveMission = Number(window.fleetDispatcher?.mission) || 0;
      const fromMessagesRaid = qp.has("sonicmsg") || qp.has("sonicmode");
      const mission = liveMission || urlMission;
      if (mission ? ![1, 2].includes(mission) : !fromMessagesRaid) return;
      if (sonicLastSendWasAttack() === false) return;
      fired = true;
      try { window.sonicLog && window.sonicLog("[SoNiC Raid] erreur serveur → retour messages", text.slice(0, 80)); } catch (_) {}
      setTimeout(() => { try { clearRaidContext(); } catch (_) {} openMessages(); }, 1400);
    };
    const start = () => {
      new MutationObserver((records) => {
        for (const r of records) r.addedNodes.forEach(check);
      }).observe(document.documentElement, { childList: true, subtree: true });
    };
    if (document.documentElement) start(); else document.addEventListener("DOMContentLoaded", start, { once: true });
  })();

  function sonicRaidReturnPending() {
    if (loadRaidContext()) return true;
    try {
      const chain = sonicLoadInactiveRaidChain();
      return !!(chain.activeMessageId && chain.sendInitiated);
    } catch (_) { return false; }
  }
  function sonicOnSendFleetResponse(url, response) {
    try {
      if (!/sendFleet/i.test(String(url || ""))) return;
      if (!response || typeof response !== "object") return;
      if (response.success === false || (Array.isArray(response.errors) && response.errors.length)) return;
      if (response.success !== true && !response.redirectUrl && !response.newToken) return;
      const sentMission = Number(window.fleetDispatcher?.mission || 0);
      if (sentMission && sentMission !== 1 && sentMission !== 2) return;
      if (!sonicRaidReturnPending()) return;
      if (window.__sonicReturnFiredAt && Date.now() - window.__sonicReturnFiredAt < 3000) return;
      window.__sonicReturnFiredAt = Date.now();
      sonicMarkInactiveRaidSendInitiated();
      handleFleetReturn(true);
    } catch (_) {}
  }
  function sonicInstallFastReturnAfterSend() {
    if (window.__sonicFastReturnInstalled) return;
    window.__sonicFastReturnInstalled = true;
    // 1) jQuery (OGame envoie la flotte via $.ajax)
    const installJq = () => {
      const jq = window.jQuery || window.$;
      if (!jq || !jq.fn) return false;
      jq(document).off("ajaxSuccess.sonicFastReturn").on("ajaxSuccess.sonicFastReturn", (_event, xhr, ajaxSettings) => {
        let response = xhr?.responseJSON;
        if (!response && xhr?.responseText) {
          try { response = JSON.parse(xhr.responseText); } catch (_) {}
        }
        sonicOnSendFleetResponse(ajaxSettings?.url, response);
      });
      return true;
    };
    if (!installJq()) {
      let tries = 0;
      const timer = setInterval(() => {
        if (installJq() || ++tries > 200) clearInterval(timer);
      }, 50);
    }
    // 2) Filet de sécurité : XHR natif et fetch
    try {
      const proto = window.XMLHttpRequest && window.XMLHttpRequest.prototype;
      if (proto && !proto.__sonicSendHook) {
        proto.__sonicSendHook = true;
        const origOpen = proto.open;
        proto.open = function (method, url) {
          try { this.__sonicUrl = String(url || ""); } catch (_) {}
          return origOpen.apply(this, arguments);
        };
        const origSend = proto.send;
        proto.send = function () {
          try {
            if (/sendFleet/i.test(this.__sonicUrl || "")) {
              this.addEventListener("load", () => {
                let response = null;
                try { response = JSON.parse(this.responseText); } catch (_) {}
                sonicOnSendFleetResponse(this.__sonicUrl, response);
              });
            }
          } catch (_) {}
          return origSend.apply(this, arguments);
        };
      }
      if (typeof window.fetch === "function" && !window.fetch.__sonicSendHook) {
        const origFetch = window.fetch;
        const wrapped = function (input) {
          const result = origFetch.apply(this, arguments);
          try {
            const url = typeof input === "string" ? input : input?.url;
            if (/sendFleet/i.test(String(url || ""))) {
              result.then((res) => res.clone().json().then((json) => sonicOnSendFleetResponse(url, json)).catch(() => {})).catch(() => {});
            }
          } catch (_) {}
          return result;
        };
        wrapped.__sonicSendHook = true;
        window.fetch = wrapped;
      }
    } catch (_) {}
  }
  sonicInstallFastReturnAfterSend();
  function openFleetDispatch() {
    if (isFleetDispatchPage()) return;
    const url = new URL(window.location.href);
    url.searchParams.set("component", "fleetdispatch");
    window.location.href = url.toString();
  }
  function openGalaxy() {
    if (isGalaxyPage()) return;
    const url = new URL(window.location.href);
    url.searchParams.set("component", "galaxy");
    window.location.href = url.toString();
  }
  function openTrader() {
    const url = new URL(window.location.href);
    url.searchParams.set("component", "trader");
    window.location.href = url.toString();
  }
  function sonicArmCollectBodyNavigation(target, action) {
    if (!target) return;
    try {
      const cp = target.cp ? String(target.cp) : '';
      if (!cp) return;
      sessionStorage.setItem('SoNiC_CollectNextBodyPending', JSON.stringify({
        cp,
        action: action || '',
        setAt: Date.now(),
        armed: true,
        sentAt: 0
      }));
    } catch (_) {}
  }

  const sonicCLog = (...a) => { try { console.info('[SoNiC Collecter]', ...a); } catch (_) {} };
  window.sonicCLog = sonicCLog;
  const SONIC_COLLECT_AUTORUN_KEY = 'SoNiC_CollectAutoRun_V1';

  // Navigue vers le corps suivant ; pour Collecter, on reste sur Flotte et on relance la présélection à l'arrivée.
  function sonicNavigateToNextBody(link, pending) {
    const url = new URL(link.href, window.location.href);
    sonicCLog('navigation vers le corps suivant', pending, 'href du lien =', link.href);
    if (pending?.cp) url.searchParams.set('cp', String(pending.cp));
    window.__sonicNavigatingNextBody = true;
    if (['collect', 'expedition', 'recycle', 'hide', 'recall'].includes(pending?.action)) {
      url.searchParams.set('page', 'ingame');
      url.searchParams.set('component', 'fleetdispatch');
      try {
        sessionStorage.setItem(SONIC_COLLECT_AUTORUN_KEY, JSON.stringify({
          cp: String(pending.cp || ''),
          action: pending.action,
          setAt: Date.now()
        }));
      } catch (_) {}
    }
    sonicCLog('adresse cible', url.toString());
    window.location.href = url.toString();
  }

  // À l'arrivée sur le corps suivant : présélectionne Collecter (Entrée = continuer, Entrée = envoyer).
  function sonicAutoRunCollectAfterRedirect() {
    if (!isFleetDispatchPage()) return;
    let flag = null;
    try {
      const raw = sessionStorage.getItem(SONIC_COLLECT_AUTORUN_KEY);
      flag = raw ? JSON.parse(raw) : null;
    } catch (_) {}
    if (!flag) { sonicCLog('arrivée Flotte : aucun relancement programmé'); return; }
    try { sessionStorage.removeItem(SONIC_COLLECT_AUTORUN_KEY); } catch (_) {}
    sonicCLog('relancement programmé', flag, 'cp actuel =', new URLSearchParams(window.location.search).get('cp'));

    const currentCp = new URLSearchParams(window.location.search).get('cp');
    if (Date.now() - Number(flag.setAt || 0) > Number(flag.ttl || 60000)) { sonicCLog('relancement expiré'); return; }
    // Adresse sans cp mais corps déjà affiché = corps visé : aucun rechargement supplémentaire.
    let shownBodyId = '';
    try { shownBodyId = String(document.querySelector('meta[name="ogame-planet-id"]')?.getAttribute('content') || ''); } catch (_) {}
    if (flag.cp && !currentCp && !flag.__redirected && shownBodyId && shownBodyId !== String(flag.cp)) {
      // Arrivée sans cp dans l'adresse : on force le bon corps puis on relance à l'arrivée.
      try {
        sessionStorage.setItem(SONIC_COLLECT_AUTORUN_KEY, JSON.stringify({ ...flag, __redirected: true, setAt: Date.now() }));
        const u = new URL(window.location.href);
        u.searchParams.set('cp', String(flag.cp));
        sonicCLog('cp absent, redirection vers', u.toString());
        window.location.href = u.toString();
        return;
      } catch (_) {}
    }
    if (flag.cp && currentCp && String(currentCp) !== String(flag.cp)) {
      // Un relancement frais de Collecter s'applique au corps affiché même si le cp diffère (changement de corps entre-temps).
      if (flag.action !== 'collect') { sonicCLog('relancement ignoré : autre corps', flag.cp, currentCp); return; }
      sonicCLog('cp différent, Collecter relancé sur le corps affiché', flag.cp, currentCp);
    }
    if (!['collect', 'expedition', 'recycle', 'hide', 'recall'].includes(flag.action)) return;

    if (flag.action === 'collect') {
      // Purge toute cargaison résiduelle de la planète précédente : Collecter recalcule avec la réserve configurée.
      sonicSavePendingResourceLoad({ metal: 0, crystal: 0, deuterium: 0 });
      sonicSetCollectFleetState(null);
    } else {
      sonicSavePendingResourceLoad({ metal: 0, crystal: 0, deuterium: 0 });
    }

    // Empêche la sélection Transport par défaut d'écraser la préselection.
    window.__sonicUserMissionChosen = true;
    window.__sonicDefaultTransportApplied = true;

    const chainMission = { expedition: 15, recycle: 8, recall: 4 }[flag.action] || 0;
    const chainEntry = { action: flag.action, at: Date.now(), run: null, mission: chainMission };
    window.__sonicChainPending = chainEntry;
    // Présélection visuelle (cadre doré) maintenue tant que Entrée n'a pas été pressée : le jeu ou la page peuvent la réinitialiser pendant le chargement.
    const showChainVisual = () => {
      try {
        if (window.__sonicChainPending !== chainEntry) return false;
        if (chainMission) { sonicSelectedMissionId = chainMission; sonicUpdateMissionButtonsState(); sonicSelectActionVisual(null); }
        else sonicSelectActionVisual(flag.action === 'recall' ? 'ships' : flag.action);
        return true;
      } catch (_) { return true; }
    };
    showChainVisual();
    let visualTries = 0;
    const visualTimer = setInterval(() => { if (++visualTries > 120 || !showChainVisual()) clearInterval(visualTimer); }, 250);
    let attempts = 0;
    const tick = () => {
      if (!isFleetDispatchPage()) return;
      const fleet = window.fleetDispatcher;
      const baseReady = fleet && Array.isArray(fleet.shipsOnPlanet) && fleet.shipsOnPlanet.length &&
        fleet.currentPage === 'fleet1' && fleet.currentPlanet;
      const hasRes = baseReady && ((Number(fleet.metalOnPlanet) || 0) + (Number(fleet.crystalOnPlanet) || 0) + (Number(fleet.deuteriumOnPlanet) || 0)) > 0;
      const ready = baseReady && (flag.action !== 'collect' || ((document.getElementById('sonic-transport-metal') && hasRes) || attempts > 100));
      if (ready) {
        sonicCLog('page prête, action en attente d\'Entrée', flag.action, 'tentatives =', attempts);
        // Rien n'est sélectionné automatiquement : le bouton est seulement présélectionné (invisible côté vaisseaux).
        // La sélection des vaisseaux/ressources et le passage à Flotte 2 se font à l'appui sur Entrée.
        chainEntry.run = () => {
        if (flag.action === 'collect') {
          let tries = 0;
          const run = () => {
            collectResources().catch(error => console.warn('[SoNiC Collecter] Relance automatique impossible :', error));
            // Contrôle : si la mission ou les vaisseaux ne sont pas posés (page pas encore stabilisée), on rejoue.
            setTimeout(() => {
              const f = window.fleetDispatcher;
              if (!f || f.currentPage !== 'fleet1' || ++tries > 4) return;
              const selected = [202, 203, 219].some(id => Number((typeof f.findShip === 'function' ? f.findShip(id) : null)?.number || 0) > 0);
              const cargo = (Number(f.cargoMetal) || 0) + (Number(f.cargoCrystal) || 0) + (Number(f.cargoDeuterium) || 0);
              const avail = (Number(f.metalOnPlanet) || 0) + (Number(f.crystalOnPlanet) || 0) + (Number(f.deuteriumOnPlanet) || 0);
              if (Number(f.mission) !== 3 || (avail > 0 && cargo <= 0 && !selected)) run();
            }, 900);
          };
          run();
          // Garde : pendant 7 s, si OGame écrase mission / vaisseaux / cargaison, on les remet (et on le note dans la console).
          const guardStart = Date.now();
          const guard = setInterval(() => {
            if (Date.now() - guardStart > 7000) { clearInterval(guard); return; }
            const f = window.fleetDispatcher, d = window.__sonicCollectDesired;
            if (!f || !d || f.currentPage !== 'fleet1' || Date.now() - d.at < 400) return;
            const shipsOk = d.allocation.every(({ shipId, amount }) => Number((typeof f.findShip === 'function' ? f.findShip(shipId) : null)?.number || 0) === Number(amount));
            const cargoOk = Number(f.cargoMetal) === Math.min(d.values.metal, Number(f.metalOnPlanet) || 0) &&
              Number(f.cargoCrystal) === Math.min(d.values.crystal, Number(f.crystalOnPlanet) || 0) &&
              Number(f.cargoDeuterium) === Math.min(d.values.deuterium, Number(f.deuteriumOnPlanet) || 0);
            const missionOk = Number(f.mission) === 3;
            if (shipsOk && cargoOk && missionOk) return;
            sonicCLog('sélection écrasée, correction', { shipsOk, cargoOk, missionOk, mission: f.mission });
            window.__sonicCollectLock = true;
            try {
              sonicReapplyCollectShips(f, d.allocation);
              f.cargoMetal = Math.min(d.values.metal, Number(f.metalOnPlanet) || 0);
              f.cargoCrystal = Math.min(d.values.crystal, Number(f.crystalOnPlanet) || 0);
              f.cargoDeuterium = Math.min(d.values.deuterium, Number(f.deuteriumOnPlanet) || 0);
              sonicPendingResourceLoad = { ...d.values, setAt: Date.now() };
              if (!missionOk) { selectMissionRobust(f, 3); sonicSelectedMissionId = 3; }
              if (typeof f.refresh === 'function') f.refresh();
            } finally { setTimeout(() => { window.__sonicCollectLock = false; }, 600); }
          }, 250);
        } else if (flag.action === 'expedition') {
          selectExpeditionFleet();
          // Garde : si OGame écrase la mission pendant son initialisation, on rejoue la préselection (3 fois max).
          let guardTries = 0;
          const expGuard = setInterval(() => {
            const f = window.fleetDispatcher;
            if (++guardTries > 8 || !f || f.currentPage !== 'fleet1') { clearInterval(expGuard); return; }
            if (Number(f.mission) !== 15 && !(new URLSearchParams(window.location.search).has('position'))) {
              sonicCLog('mission Expédition écrasée, correction');
              try { selectExpeditionFleet(); } catch (_) {}
            }
          }, 500);
        } else if (flag.action === 'recall') {
          selectRecallFleet(true);
          try { sonicSelectActionVisual('ships'); } catch (_) {}
          let recallTries = 0;
          const recallGuard = setInterval(() => {
            const f = window.fleetDispatcher;
            if (++recallTries > 8 || !f || f.currentPage !== 'fleet1') { clearInterval(recallGuard); return; }
            if (Number(f.mission) !== 4) { sonicCLog('mission Stationner écrasée, correction'); try { selectRecallFleet(true); } catch (_) {} }
          }, 500);
        } else if (flag.action === 'hide') {
          hideFleet(true);
          try { sonicSelectActionVisual('hide'); } catch (_) {}
          let hideTries = 0;
          const hideGuard = setInterval(() => {
            const f = window.fleetDispatcher;
            if (++hideTries > 8 || !f || f.currentPage !== 'fleet1') { clearInterval(hideGuard); return; }
            if (Number(f.mission) !== Number(window.__sonicHideMission || 4)) { sonicCLog('mission Cacher écrasée, correction'); try { hideFleet(true); } catch (_) {} }
          }, 500);
        } else {
          recycleDebris();
        }
        };
        return;
      }
      if (++attempts < 200) setTimeout(tick, 40);
      else sonicCLog('abandon : page non prête', { baseReady: !!baseReady, page: fleet?.currentPage });
    };
    tick();
  }

  function sonicMarkCollectBodySent() {
    try {
      const raw = sessionStorage.getItem('SoNiC_CollectNextBodyPending');
      if (!raw) return;
      const pending = JSON.parse(raw);
      if (!pending?.cp || Date.now() - Number(pending.setAt || 0) > 120000) {
        sessionStorage.removeItem('SoNiC_CollectNextBodyPending');
        return;
      }
      pending.sentAt = Date.now();
      pending.armed = false;
      sessionStorage.setItem('SoNiC_CollectNextBodyPending', JSON.stringify(pending));
    } catch (_) {}
  }

  function sonicInstallCollectBodySendHook() {
    if (window.__sonicCollectBodySendHookBound) return;
    window.__sonicCollectBodySendHookBound = true;
    // Navigation vers le corps suivant après un envoi RÉUSSI : déclenchée dès la réponse du serveur (un seul chargement de page).
    const goNext = () => {
      try {
        const raw = sessionStorage.getItem('SoNiC_CollectNextBodyPending');
        if (!raw || !isFleetDispatchPage()) return;
        const pending = JSON.parse(raw);
        if (!pending?.sentAt || Date.now() - Number(pending.sentAt) > 8000) return;
        const cp = String(pending.cp || '');
        const link = Array.from(document.querySelectorAll('#planetList .planetlink,#planetList .moonlink')).find(a => {
          try { return new URL(a.href, window.location.href).searchParams.get('cp') === cp; } catch (_) { return false; }
        });
        if (!link) return;
        sessionStorage.removeItem('SoNiC_CollectNextBodyPending');
        sonicNavigateToNextBody(link, pending);
      } catch (_) {}
    };
    window.addEventListener('sonic-fleet-sent', () => goNext()); // immédiat : remplace la navigation native avant qu'elle n'aboutisse (un seul chargement)
    document.addEventListener('click', event => {
      const send = event.target instanceof Element ? event.target.closest('#sendFleet') : null;
      if (!send || !isFleetDispatchPage()) return;
      sonicMarkCollectBodySent();
      // Filet de sécurité si le signal de réussite n'a pas pu être lu ; un envoi refusé reste sur la page pour réessayer.
      setTimeout(() => {
        try {
          const stillFleet2 = window.fleetDispatcher && window.fleetDispatcher.currentPage === 'fleet2';
          if (stillFleet2) {
            sonicCLog('envoi non abouti : on reste sur la page pour réessayer');
            try { sessionStorage.removeItem('SoNiC_CollectAutoRun_V1'); } catch (_) {}
            try {
              const rawP = sessionStorage.getItem('SoNiC_CollectNextBodyPending');
              if (rawP) { const pp = JSON.parse(rawP); pp.sentAt = 0; pp.armed = true; pp.setAt = Date.now(); sessionStorage.setItem('SoNiC_CollectNextBodyPending', JSON.stringify(pp)); }
            } catch (_) {}
            window.__sonicNavigatingNextBody = false;
            return;
          }
          goNext();
        } catch (_) {}
      }, 2500);
    }, true);
  }


  function sonicApplyPendingCollectBodyNavigation() {
    try {
      const raw = sessionStorage.getItem('SoNiC_CollectNextBodyPending');
      if (!raw) return;
      const pending = JSON.parse(raw);
      const age = Date.now() - Number(pending.setAt || 0);
      if (!pending?.cp || age > 120000) {
        sessionStorage.removeItem('SoNiC_CollectNextBodyPending');
        return;
      }
      if (!pending.sentAt) return;

      const currentCp = new URLSearchParams(window.location.search).get('cp');
      if (String(currentCp || '') === String(pending.cp)) {
        sessionStorage.removeItem('SoNiC_CollectNextBodyPending');
        return;
      }
      if (!document.querySelector('#planetList')) return;

      const link = Array.from(document.querySelectorAll('#planetList .planetlink,#planetList .moonlink')).find(a => {
        try {
          return new URL(a.href, window.location.href).searchParams.get('cp') === String(pending.cp);
        } catch (_) { return false; }
      });
      if (!link) return;

      sessionStorage.removeItem('SoNiC_CollectNextBodyPending');
      sonicNavigateToNextBody(link, pending);
    } catch (_) {}
  }

  function getBodyLinks() {
    return Array.from(
      document.querySelectorAll(
        "#planetList .planetlink, #planetList .moonlink",
      ),
    );
  }
  function sonicRefreshCurrentBodyHalo() {
    const list = document.querySelector('#planetList');
    if (!list) return;
    list.querySelectorAll('.smallplanet.sonic-current-body-halo').forEach(el => {
      el.classList.remove('sonic-current-body-halo', 'sonic-current-moon', 'sonic-current-planet');
    });
    if (window.__sonicHaloOn === undefined) { try { window.__sonicHaloOn = loadSettings().currentBodyHalo !== false; } catch (_) { window.__sonicHaloOn = true; } }
    if (window.__sonicHaloOn === false) return;

    const urlCp = new URLSearchParams(window.location.search).get('cp');
    const fleet = window.fleetDispatcher;
    const current = fleet?.currentPlanet || null;
    const bodyInfo = typeof window.sonicFutureGetCurrentBodyInfo === 'function'
      ? window.sonicFutureGetCurrentBodyInfo()
      : null;
    const currentIds = new Set([
      urlCp,
      bodyInfo?.planetId,
      current?.id,
      current?.planetId,
      current?.moonId,
      current?.cp,
    ].filter(v => v != null && String(v) !== '').map(String));
    const cg = Number(bodyInfo?.coords?.galaxy ?? current?.galaxy);
    const cs = Number(bodyInfo?.coords?.system ?? current?.system);
    const cp = Number(bodyInfo?.coords?.position ?? current?.position);
    const currentType = bodyInfo?.type === 'moon' ? 3 : (Number(current?.type) || 1);

    if (!currentIds.size && ![cg, cs, cp].every(Number.isFinite)) return;

    list.querySelectorAll('.smallplanet').forEach(container => {
      const links = Array.from(container.querySelectorAll(':scope > a.planetlink, :scope > a.moonlink'));
      const hit = links.some(link => {
        try {
          const linkCp = new URL(link.href, window.location.href).searchParams.get('cp');
          if (linkCp && currentIds.has(String(linkCp))) return true;
        } catch (_) {}
        const text = [
          link.getAttribute('data-coordinates'), link.getAttribute('data-coords'),
          link.getAttribute('title'), link.getAttribute('aria-label'), link.textContent
        ].filter(Boolean).join(' ');
        const m = text.match(/(\d+)\s*:\s*(\d+)\s*:\s*(\d+)/);
        if (!m || ![cg, cs, cp].every(Number.isFinite)) return false;
        if (Number(m[1]) !== cg || Number(m[2]) !== cs || Number(m[3]) !== cp) return false;
        return !currentType || (isMoonLink(link) ? 3 : 1) === currentType;
      });
      if (hit) {
        container.classList.add('sonic-current-body-halo');
        const matchedLink = links.find(link => {
          try {
            const linkCp = new URL(link.href, window.location.href).searchParams.get('cp');
            if (linkCp && currentIds.has(String(linkCp))) return true;
          } catch (_) {}
          const text = [
            link.getAttribute('data-coordinates'), link.getAttribute('data-coords'),
            link.getAttribute('title'), link.getAttribute('aria-label'), link.textContent
          ].filter(Boolean).join(' ');
          const m = text.match(/(\d+)\s*:\s*(\d+)\s*:\s*(\d+)/);
          return !!(m && [cg, cs, cp].every(Number.isFinite) &&
            Number(m[1]) === cg && Number(m[2]) === cs && Number(m[3]) === cp &&
            (!currentType || (isMoonLink(link) ? 3 : 1) === currentType));
        });
        container.classList.toggle('sonic-current-moon', !!matchedLink && isMoonLink(matchedLink));
        container.classList.toggle('sonic-current-planet', !!matchedLink && !isMoonLink(matchedLink));
      }
    });
  }
  function sonicInstallCurrentBodyHalo() {
    sonicRefreshCurrentBodyHalo();
    if (window.__sonicCurrentBodyHaloObserver) return;
    const list = document.querySelector('#planetList');
    if (list) {
      const observer = new MutationObserver(() => sonicRefreshCurrentBodyHalo());
      observer.observe(list, { childList:true, subtree:true });
      window.__sonicCurrentBodyHaloObserver = observer;
      return;
    }
    if (window.__sonicCurrentBodyHaloRootObserver || !document.body) return;
    const rootObserver = new MutationObserver(() => {
      if (!document.querySelector('#planetList')) return;
      rootObserver.disconnect();
      window.__sonicCurrentBodyHaloRootObserver = null;
      sonicInstallCurrentBodyHalo();
    });
    rootObserver.observe(document.body, { childList:true, subtree:true });
    window.__sonicCurrentBodyHaloRootObserver = rootObserver;
  }
  sonicInstallCurrentBodyHalo();
  if (!window.__sonicCurrentBodyHaloRefreshTimer) {
    window.__sonicCurrentBodyHaloRefreshTimer = window.sonicEvery('body-halo', () => {
      try { sonicRefreshCurrentBodyHalo(); } catch (_) {}
      try { sonicRefreshFullDotsSidebar(); } catch (_) {}
    }, 1500);
  }
  sonicInstallCollectBodySendHook();

  // Indicateur d'envoi : petite roue discrète entre le clic sur « Envoyer la flotte » et le rechargement de la page.
  // (Le jeu masque sa propre roue dès la réponse du serveur, alors que le rechargement dure encore ~1 s.)
  function sonicInstallSendSpinner() {
    if (window.__sonicSendSpinnerBound) return;
    window.__sonicSendSpinnerBound = true;
    // Petite roue native : sur Flotte, le jeu affiche de grandes roues (128 px) sur chaque bloc pendant l'envoi.
    // On les réduit et on allège le voile sombre ; l'option « petite roue » les rétablit en grand si elle est décochée.
    try {
      if (!document.getElementById('sonic-small-wheel-css')) {
        const st = document.createElement('style');
        st.id = 'sonic-small-wheel-css';
        st.textContent = 'html.sonic-small-wheel.sonic-on-fleet .ajax_loading_indicator{transform:scale(.2) !important;transform-origin:center center !important}'
          + 'html.sonic-small-wheel.sonic-on-fleet .ajax_loading_overlay{opacity:.45 !important}'
          + 'html.sonic-small-wheel.sonic-on-fleet #pageReloader{transform:scale(.6);transform-origin:top left}'
          // Messages : la roue de chargement disparaît (le contenu se remplace sans voile ni roue).
          + 'html.sonic-small-wheel.sonic-on-messages .ajax_loading_indicator,html.sonic-small-wheel.sonic-on-messages #loadingCircle{display:none !important}'
          + 'html.sonic-small-wheel.sonic-on-messages .ajax_loading_overlay{background:transparent !important;opacity:0 !important}';
        (document.head || document.documentElement).appendChild(st);
      }
      const applyWheel = () => {
        const opt = loadSettings().sendSpinner !== false;
        document.documentElement.classList.toggle('sonic-small-wheel', opt && (isFleetDispatchPage() || isMessagesPage()));
        document.documentElement.classList.toggle('sonic-on-fleet', isFleetDispatchPage());
        document.documentElement.classList.toggle('sonic-on-messages', isMessagesPage());
      };
      window.sonicApplySmallWheel = applyWheel;
      applyWheel();
    } catch (_) {}
    const hide = () => {
      document.getElementById('sonic-send-spinner')?.remove();
      try { document.documentElement.style.removeProperty('cursor'); } catch (_) {}
    };
    document.addEventListener('click', (event) => {
      const send = event.target instanceof Element ? event.target.closest('#sendFleet') : null;
      if (!send || !isFleetDispatchPage() || loadSettings().sendSpinner === false) return;
      if (send.classList.contains('off') || send.classList.contains('disabled')) return;
      if (!document.getElementById('sonic-send-spinner-css')) {
        const st = document.createElement('style');
        st.id = 'sonic-send-spinner-css';
        st.textContent = '#sonic-send-spinner{position:fixed;top:96px;right:56px;width:14px;height:14px;border-radius:50%;border:2px solid rgba(255,215,0,.25);border-top-color:#ffd700;animation:sonic-send-spin .7s linear infinite;z-index:2147483000;pointer-events:none}@keyframes sonic-send-spin{to{transform:rotate(360deg)}}';
        document.head.appendChild(st);
      }
      if (!document.getElementById('sonic-send-spinner')) {
        const el = document.createElement('div');
        el.id = 'sonic-send-spinner';
        document.body.appendChild(el);
      }
      try { document.documentElement.style.setProperty('cursor', 'progress', 'important'); } catch (_) {}
      // Envoi refusé (la page reste sur Flotte 2) : on retire l'indicateur.
      setTimeout(hide, 8000);
    }, true);
    window.addEventListener('pagehide', hide);
  }
  sonicInstallSendSpinner();
  setTimeout(sonicApplyPendingCollectBodyNavigation, 250);
  setTimeout(sonicApplyPendingCollectBodyNavigation, 900);
  setTimeout(sonicApplyPendingCollectBodyNavigation, 1800);
  setTimeout(sonicApplyPendingCollectBodyNavigation, 3500);

  function isMoonLink(link) {
    return link.classList.contains("moonlink");
  }
  function getCurrentBodyIndex(links) {
    let index = links.findIndex((link) => link.classList.contains("active"));
    if (index >= 0) return index;
    const currentCp = new URLSearchParams(window.location.search).get("cp");
    if (currentCp) {
      index = links.findIndex((link) => {
        try {
          return (
            new URL(link.href, window.location.href).searchParams.get("cp") ===
            currentCp
          );
        } catch (error) {
          return false;
        }
      });
    }
    return index >= 0 ? index : 0;
  }
  function switchPlanet(direction) {
    const links = getBodyLinks();
    if (links.length === 0) return;
    const currentIndex = getCurrentBodyIndex(links);
    const currentIsMoon = isMoonLink(links[currentIndex]);
    let index = currentIndex;
    if (settings.mixBodyTypesOnSwitch) {
      index = (index + direction + links.length) % links.length;
    } else {
      for (let step = 0; step < links.length; step++) {
        index = (index + direction + links.length) % links.length;
        if (isMoonLink(links[index]) === currentIsMoon) break;
      }
    }
    const targetHref = links[index].getAttribute("href");
    if (!targetHref) return;
    let targetCp;
    try {
      targetCp = new URL(targetHref, window.location.href).searchParams.get(
        "cp",
      );
    } catch (error) {
      return;
    }
    if (!targetCp) return;
    const url = new URL(window.location.href);
    url.searchParams.set("cp", targetCp);
    // Changement de corps = rechargement complet : on rejoue l'action en cours (expédition / recycler) à l'arrivée.
    try {
      const rep = window.__sonicRepeat;
      const f = window.fleetDispatcher;
      if (isFleetDispatchPage() && rep && f && Number(f.mission) === Number(rep.mission) && Date.now() - rep.at < 180000) {
        sonicSetAutoRun(rep.action, targetCp, 20000);
      } else if (isFleetDispatchPage()) {
        // Après un envoi, la page s'est rechargée : on reprend la dernière action enchaînée (Expédition, Recycler…) pour le corps suivant.
        const last = JSON.parse(sessionStorage.getItem("SoNiC_LastChainAction_V1") || "null");
        const pendingHere = !!window.__sonicChainPending;
        const manual = !!(last && Date.now() - Number(last.at || 0) < 10 * 60 * 1000);
        if (manual && (pendingHere || !f || f.currentPage === "fleet1")) {
          sessionStorage.setItem("SoNiC_LastChainAction_V1", JSON.stringify({ ...last, at: Date.now() }));
          sonicSetAutoRun(last.action, targetCp, 20000);
        }
      }
    } catch (_) {}
    window.location.href = url.toString();
  }
  function isEditable(element) {
    if (!element || !(element instanceof Element)) return false;
    if (element.isContentEditable) return true;
    if (element.tagName === "TEXTAREA" || element.tagName === "SELECT")
      return true;
    if (element.tagName !== "INPUT") return false;
    const type = (element.type || "").toLowerCase();
    return [
      "text",
      "search",
      "email",
      "password",
      "number",
      "tel",
      "url",
    ].includes(type);
  }
  // ===== Raccourcis clavier configurables =====
  const SONIC_SHORTCUTS_KEY = "SoNiC_Suite_Shortcuts_v1";
  function sonicNavTo(component) {
    const url = new URL(window.location.href);
    url.search = "";
    url.searchParams.set("page", "ingame");
    url.searchParams.set("component", component);
    const cp = new URLSearchParams(window.location.search).get("cp");
    if (cp) url.searchParams.set("cp", cp);
    window.location.href = url.toString();
  }
  function sonicGalaxyStep(dGalaxy, dSystem) {
    if (!isGalaxyPage()) return;
    const gi = document.querySelector("#galaxy_input"), si = document.querySelector("#system_input");
    if (!gi || !si) return;
    const maxG = Number(window.universeData?.galaxies) || Number(window.serverData?.galaxies) || 9;
    const maxS = Number(window.universeData?.systems) || Number(window.serverData?.systems) || 499;
    let g = Number(gi.value) || 1, s = Number(si.value) || 1;
    if (dSystem) { s += dSystem; if (s > maxS) s = 1; if (s < 1) s = maxS; }
    if (dGalaxy) { g += dGalaxy; if (g > maxG) g = 1; if (g < 1) g = maxG; }
    gi.value = String(g); si.value = String(s);
    try {
      if (typeof window.loadContentNew === "function") { window.loadContentNew(g, s); return; }
    } catch (_) {}
    openGalaxyAt(g, s, 0);
  }
  function sonicGateOpen() { return !!document.getElementById("jumpgateForm"); }
  // scope : global | fleet | galaxy | gate (sert à détecter les conflits). run absent = géré ailleurs (porte de saut).
