    const DB_KEY = 'SoNiC_GalaxyDatabase_v3';
    const LEGACY_DB_KEYS = ['SoNiC_GalaxyDatabase_v2','SoNiC_GalaxyDatabase_v1'];
    const UI_KEY = 'SoNiC_GalaxyPlayerPanel_v39';
    const OWN_POSITIONS_KEY = 'SoNiC_GalaxyOwnPositions_v1';
    function statsUniverse() {
        const m = String(location.hostname).match(/^s(\d+)-/i);
        return m ? '_' + m[1] : '_270';
    }

    const MARKERS = {
        own:      { label:'Nos positions', color:'#18cfff', icon:'◎' },
        friend:   { label:'Ami',            color:'#35cf95', icon:'●' },
        enemy:    { label:'Ennemi',         color:'#ff4b4b', icon:'⚔' },
        target:   { label:'Cible',          color:'#ffd21a', icon:'◎' },
        watch:    { label:'Surveillance',   color:'#a86cff', icon:'◉' },
        inactive: { label:'Inactif',        color:'#bfcbd5', icon:'◷' },
        avoid:    { label:'À éviter',       color:'#ff6b35', icon:'!' },
        none:     { label:'Aucun',          color:'#748696', icon:'×' }
    };

    // Préférences : marqueurs affichés au survol + catégories personnalisées (nom + couleur).
    const MARKER_PREFS_KEY = 'SoNiC_GalaxyMarkerPrefs_V1';
    function sanitizeMarkerPrefs(v){
        const hidden = Array.isArray(v?.hidden) ? v.hidden.map(String) : [];
        const custom = Array.isArray(v?.custom) ? v.custom.filter(c => c && /^c_[a-z0-9]{3,12}$/.test(String(c.key)) && String(c.label || '').trim()).slice(0, 12)
            .map(c => ({ key: String(c.key), label: String(c.label).trim().slice(0, 24), color: /^#[0-9a-f]{6}$/i.test(String(c.color)) ? String(c.color) : '#ffffff' })) : [];
        return { hidden, custom };
    }
    let markerPrefs = (() => { try { return sanitizeMarkerPrefs(JSON.parse(localStorage.getItem(MARKER_PREFS_KEY) || 'null')); } catch (_) { return sanitizeMarkerPrefs(null); } })();
    function isMarkerHidden(k){ return markerPrefs.hidden.includes(k); }
    function applyMarkerPrefs(){
        try{ const oc=JSON.parse(localStorage.getItem('SoNiC_GalaxyMarkerColors')||'{}')||{}; if(MARKERS.own){ MARKERS.own.color=/^#[0-9a-f]{6}$/i.test(oc.own||'')?oc.own:'#18cfff'; } }catch(_){}
        Object.keys(MARKERS).forEach(k => { if (MARKERS[k].custom) delete MARKERS[k]; });
        markerPrefs.custom.forEach(c => { MARKERS[c.key] = { label: c.label, color: c.color, icon: '●', custom: true }; });
        try {
            let st = document.getElementById('sonic-custom-marker-css');
            if (!st) { st = document.createElement('style'); st.id = 'sonic-custom-marker-css'; (document.head || document.documentElement).appendChild(st); }
            st.textContent = markerPrefs.custom.map(c => `.sv40-sprite.sv40-sprite-${c.key}{background:${c.color} !important;border-radius:50% !important;box-shadow:0 0 5px ${c.color};transform:scale(.55)}.sv40-sprite.sv40-sprite-${c.key}::before{content:'' !important}`).join('');
        } catch (_) {}
    }
    applyMarkerPrefs();

    const MARKER_SPRITE_URL = window.SONIC_ASSETS.markersSprite;

    function markerLabel(key, count) {
        if (key === 'all') return 'Tous';
        if (key === 'own') return 'Nos positions';
        const singular = MARKERS[key]?.label || 'Aucun';
        if (count > 1) {
            if (key === 'friend') return 'Amis';
            if (key === 'enemy') return 'Ennemis';
            if (key === 'inactive') return 'Inactifs';
        }
        return singular;
    }

    let db = loadDB();

    (function purgeAutoCapturedCoords(){
        let selectedId='';
        try {
            const ui=JSON.parse(localStorage.getItem(UI_KEY)||'null');
            if(ui?.playerId) selectedId=String(ui.playerId);
        } catch (_) {}

        const keepIds=new Set(
            Object.values(db.players||{})
                .filter(p=>p?.marker)
                .map(p=>String(p.playerId))
        );
        if(selectedId) keepIds.add(selectedId);

        Object.values(db.players||{}).forEach(p=>{
            if(!keepIds.has(String(p?.playerId))) p.positions=[];
        });
        Object.keys(db.positions||{}).forEach(c=>{
            const id=String(db.positions[c]?.playerId||'');
            if(id && !keepIds.has(id)) delete db.positions[c];
        });
        try { localStorage.setItem(DB_KEY, JSON.stringify(db)); } catch (_) {}
    })();

    let selectedPlayerId = null;
    let uiHadPlayer = false;
    let playerPanel = null;
    let coordsPanel = null;
    let hoverPanel = null;
    let hoverTimer = 0;
    let hoverHideTimer = 0;
    let apiBusy = new Set();
    let destroyed = false;
    let refreshTimer = 0;
    let lastNavigatedCoord = '';
    let selectedCoordinate = '';
    let coordsOpen = true;
    let markerFilter = 'all';
    let coordsManualPosition = null;
    let playerManualPosition = null;
    let playerManualSize = null;
    let coordsManualSize = null;
    let playerPanelCollapsed = false;
    let dragPanel = null;
    let contentObserver = null;
    let refreshDebounce = 0;

    try {
        lastNavigatedCoord = sessionStorage.getItem('SoNiC_GalaxyLastCoord') || '';
        const ui = JSON.parse(localStorage.getItem(UI_KEY) || 'null');
        if (ui?.playerId) { selectedPlayerId = String(ui.playerId); uiHadPlayer = true; }
        if (/^\d+:\d+:\d+$/.test(ui?.selectedCoordinate || '')) selectedCoordinate = String(ui.selectedCoordinate);
        if (!selectedCoordinate && /^\d+:\d+:\d+$/.test(lastNavigatedCoord)) selectedCoordinate = lastNavigatedCoord;
        if (ui?.coordsOpen !== undefined) coordsOpen = ui.coordsOpen !== false;
        if (ui?.playerPanelCollapsed !== undefined) playerPanelCollapsed = ui.playerPanelCollapsed === true;
        if (ui?.markerFilter) markerFilter = ui.markerFilter;
        if (ui?.coordsPosition && Number.isFinite(Number(ui.coordsPosition.left)) && Number.isFinite(Number(ui.coordsPosition.top))) {
            coordsManualPosition = { left: Number(ui.coordsPosition.left), top: Number(ui.coordsPosition.top) };
        }
        if (ui?.playerPosition && Number.isFinite(Number(ui.playerPosition.left)) && Number.isFinite(Number(ui.playerPosition.top))) {
            playerManualPosition = { left: Number(ui.playerPosition.left), top: Number(ui.playerPosition.top) };
        }
        if (ui?.playerSize && Number.isFinite(Number(ui.playerSize.width)) && Number.isFinite(Number(ui.playerSize.height))) {
            playerManualSize = { width: Number(ui.playerSize.width), height: Number(ui.playerSize.height) };
        }
        if (ui?.coordsSize && Number.isFinite(Number(ui.coordsSize.width)) && Number.isFinite(Number(ui.coordsSize.height))) {
            coordsManualSize = { width: Number(ui.coordsSize.width), height: Number(ui.coordsSize.height) };
        }
    } catch (_) {}

    function loadDB() {
        try {
            const x = JSON.parse(localStorage.getItem(DB_KEY) || 'null');
            if (x && typeof x === 'object' && x.players && x.positions) {
                x.version = 3;
                return x;
            }
        } catch (_) {}
        for (const key of LEGACY_DB_KEYS) {
            try {
                const x = JSON.parse(localStorage.getItem(key) || 'null');
                if (x && typeof x === 'object' && (x.players || x.positions)) {
                    const migrated = {
                        version:3,
                        players: x.players && typeof x.players === 'object' ? x.players : {},
                        positions: x.positions && typeof x.positions === 'object' ? x.positions : {}
                    };
                    Object.entries(migrated.positions).forEach(([c,d]) => {
                        if (!/^\d+:\d+:\d+$/.test(c) || !d?.playerId) return;
                        const id=String(d.playerId);
                        const p=migrated.players[id] ||= {
                            playerId:id,playerName:d.playerName||'',positions:[],
                            marker:null,favorite:false,api:0,apiCount:0
                        };
                        p.positions=Array.isArray(p.positions)?p.positions:[];
                        if(!p.positions.includes(c))p.positions.push(c);
                        if(!p.playerName && d.playerName)p.playerName=d.playerName;
                    });
                    Object.values(migrated.players).forEach(p=>{
                        p.playerId=String(p.playerId||'');
                        p.positions=[...new Set(Array.isArray(p.positions)?p.positions:[])].filter(c=>/^\d+:\d+:\d+$/.test(c)).sort(compareCoords);
                    });
                    try { localStorage.setItem(DB_KEY,JSON.stringify(migrated)); } catch (_) {}
                    return migrated;
                }
            } catch (_) {}
        }
        return { version:3, players:{}, positions:{} };
    }
    function saveDB() { try { localStorage.setItem(DB_KEY, JSON.stringify(db)); } catch (_) {} }
    function esc(v) { return String(v ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;').replace(/'/g,'&#039;'); }
    function compact(n) {
        n=Number(n)||0;
        if(n>=1e12)return (n/1e12).toFixed(1).replace('.0','')+'T';
        if(n>=1e9)return (n/1e9).toFixed(1).replace('.0','')+'G';
        if(n>=1e6)return (n/1e6).toFixed(1).replace('.0','')+'M';
        if(n>=1e3)return (n/1e3).toFixed(1).replace('.0','')+'k';
        return Math.round(n).toLocaleString('fr-FR');
    }
    function parseNum(v) {
        const raw=String(v??'').replace(/[^0-9.,\s]/g,'').trim(); if(!raw)return 0;
        const normalized=raw.replace(/\s/g,'').replace(/\.(?=\d{3}(?:\D|$))/g,'').replace(/,(?=\d{3}(?:\D|$))/g,'').replace(',','.');
        const n=Number(normalized); return Number.isFinite(n)?n:0;
    }
    function compareCoords(a,b){const aa=String(a).split(':').map(Number),bb=String(b).split(':').map(Number);return(aa[0]-bb[0])||(aa[1]-bb[1])||(aa[2]-bb[2]);}
    function isGalaxyPage(){return /component=galaxy/i.test(location.href)&&Boolean(document.querySelector('#galaxyContent,.galaxyRow,[id^="galaxyRow"]'));}
    function galaxySystem(){
        const g=Number(document.querySelector('#galaxy_input')?.value||window.galaxy||0);
        const s=Number(document.querySelector('#system_input')?.value||window.system||0);
        return {galaxy:g,system:s};
    }
    function playerIdFromElement(el){
        if(!el)return '';
        const rel=el.getAttribute?.('rel')||''; let m=rel.match(/player(\d+)/i); if(m)return m[1];
        const ds=el.dataset||{}; const d=ds.playerid||ds.playerId||ds.playerID||''; if(/^\d+$/.test(String(d)))return String(d);
        const href=el.getAttribute?.('href')||''; m=href.match(/(?:playerId|searchRelId|id)=(\d+)/i); if(m)return m[1];
        const onclick=el.getAttribute?.('onclick')||''; m=onclick.match(/player(?:Id|id)?[=,( ]+(\d+)/i); return m?m[1]:'';
    }
    function getPlayerIdFromRow(row){
        if(!row)return '';
        for(const el of row.querySelectorAll('[rel^="player"],[data-playerid],[data-player-id],[href*="playerId"],[href*="searchRelId"],[onclick*="player"]')){
            const id=playerIdFromElement(el); if(id)return id;
        }
        const own=ownIdentity();
        if(row.classList.contains('ownPlayerRow')||row.querySelector('.ownPlayerRow')||getPlayerNameFromRow(row)===own.name) return own.id;
        return '';
    }
    function dedupeRepeatedName(s){
        const t=String(s||'').trim(); if(!t)return t;
        if(t.length%2===0){
            const half=t.length/2;
            if(t.slice(0,half)===t.slice(half))return t.slice(0,half).trim();
        }
        const words=t.split(' ');
        if(words.length>=4&&words.length%2===0){
            const mid=words.length/2;
            if(words.slice(0,mid).join(' ')===words.slice(mid).join(' '))return words.slice(0,mid).join(' ');
        }
        return t;
    }
    function getPlayerNameFromRow(row){
        const cell=row?.querySelector('.cellPlayerName'); if(!cell)return '';

        const candidates=[
            cell.querySelector('a.playerName'),
            cell.querySelector('.playerName'),
            cell.querySelector('a[rel^="player"]'),
            cell.querySelector('[rel^="player"]')
        ].filter(Boolean);

        for(const node of candidates){
            const value=dedupeRepeatedName(String(node.innerText||node.textContent||'').replace(/\s+/g,' ').trim());
            if(value)return value;
        }

        for(const node of cell.querySelectorAll('a')){
            const value=dedupeRepeatedName(String(node.innerText||node.textContent||'').replace(/\s+/g,' ').trim());
            if(value && !/^(voir|profil|stats?|attaquer|espionner)$/i.test(value))return value;
        }

        return dedupeRepeatedName(String(cell.innerText||cell.textContent||'').replace(/\s+/g,' ').trim());
    }
    function ensurePlayer(id,name=''){
        if(!id)return null; id=String(id); db.players[id] ||= {playerId:id,playerName:'',positions:[],marker:null,favorite:false,api:0,apiCount:0};
        if(name)db.players[id].playerName=name; return db.players[id];
    }
    function rememberRow(row){
        const id=getPlayerIdFromRow(row);
        return id ? String(id) : '';
    }
    function getPlayerPositions(id){
        const p=db.players[String(id)]; if(!p)return [];
        return [...new Set(Array.isArray(p.positions)?p.positions.filter(x=>/^\d+:\d+:\d+$/.test(x)):[])].sort(compareCoords);
    }
    function ownIdentity(){
        const ids=[document.querySelector('meta[name="ogame-player-id"]')?.content,window.playerId,window.ogame?.account?.id,window.ogame?.account?.playerId,window.ogame?.player?.id];
        const id=ids.map(x=>String(x??'').trim()).find(x=>/^\d+$/.test(x))||'';
        const names=[window.playerName,window.ogame?.account?.playerName,window.ogame?.account?.name,document.querySelector('#playerName')?.textContent];
        return {id,name:names.map(x=>String(x??'').replace(/\s+/g,' ').trim()).find(Boolean)||''};
    }
    // Précharge les positions du joueur (liste des planètes de la page + dernier relevé de la page Empire) sans aucune requête.
    function preloadOwnPositions(){
        try{
            let saved=[]; try{const v=JSON.parse(localStorage.getItem(OWN_POSITIONS_KEY)||'[]'); if(Array.isArray(v))saved=v;}catch(_){}
            const known=new Set(saved.map(x=>x?.coords||`${x?.galaxy}:${x?.system}:${x?.position}`));
            let added=false;
            const add=(txt,type,name)=>{const m=String(txt||'').match(/(\d+)\s*:\s*(\d+)\s*:\s*(\d+)/); if(!m)return; const c=`${m[1]}:${m[2]}:${m[3]}`; if(known.has(c))return; known.add(c); added=true; saved.push({coords:c,galaxy:+m[1],system:+m[2],position:+m[3],type:type||1,name:String(name||'')});};
            document.querySelectorAll('#planetList .smallplanet').forEach(row=>{
                const pl=row.querySelector(':scope > a.planetlink');
                add(row.querySelector('.planet-koords')?.textContent||pl?.getAttribute('title')||pl?.getAttribute('data-tooltip-title'),1,pl?.querySelector('.planet-name')?.textContent);
            });
            try{const snap=JSON.parse(localStorage.getItem('SoNiC_Suite_NativeEmpireSnapshot')||'null'); (snap?.bodies||[]).forEach(b=>{ if(b?.type==='moon')return; add((b?.galaxy&&b?.system&&b?.position)?`${b.galaxy}:${b.system}:${b.position}`:(b?.coords||''),1,b?.name); });}catch(_){}
            if(added) localStorage.setItem(OWN_POSITIONS_KEY,JSON.stringify(saved));
        }catch(_){}
    }
    function syncOwn(){
        const own=ownIdentity(); if(!own.id)return; preloadOwnPositions(); const p=ensurePlayer(own.id,own.name); p.marker='own';
        try{const saved=JSON.parse(localStorage.getItem(OWN_POSITIONS_KEY)||'[]');if(Array.isArray(saved))saved.forEach(x=>{const c=x?.coords||`${x?.galaxy}:${x?.system}:${x?.position}`;if(/^\d+:\d+:\d+$/.test(c)){if(!p.positions.includes(c))p.positions.push(c);db.positions[c] ||= {};db.positions[c].playerId=own.id;}});}catch(_){ }
        p.positions.sort(compareCoords); saveDB();
        // Premier démarrage (aucun joueur sélectionné) : le tableau affiche directement les positions du joueur.
        if(!selectedPlayerId && !uiHadPlayer && p.positions.length){ selectedPlayerId=own.id; coordsOpen=true; uiHadPlayer=true; persistUI(); }
    }
    function markerFor(id){return MARKERS[db.players[String(id)]?.marker]||MARKERS.none;}
    function persistUI(){try{localStorage.setItem(UI_KEY,JSON.stringify({playerId:selectedPlayerId,selectedCoordinate:String(selectedCoordinate||''),coordsOpen,markerFilter,coordsPosition:coordsManualPosition,playerPosition:playerManualPosition,playerSize:playerManualSize,coordsSize:coordsManualSize,playerPanelCollapsed}));}catch(_){} }
    function statsUrl(id){return `https://www.mmorpg-stat.eu/base.php?pays=0&ftr=${encodeURIComponent(String(id))}.dat&univers=${statsUniverse()}`;}

    async function fetchPlayerAPI(id){
        id=String(id||''); if(!id||apiBusy.has(id))return; const p=ensurePlayer(id); if(!p)return;
        if(p.api&&Date.now()-p.api<10*60*1000){renderCoordsTable();return;}
        apiBusy.add(id); renderCoordsTable();
        try{
            const r=await fetch(`/api/playerData.xml?id=${encodeURIComponent(id)}`,{credentials:'same-origin'}); if(!r.ok)throw new Error(`HTTP ${r.status}`);
            const rawXml=await r.text();
            const xml=new DOMParser().parseFromString(rawXml,'text/html'),root=xml.querySelector('playerdata');
            if(!root)throw new Error('playerData.xml inattendu');
            const name=root.getAttribute('name')||'';if(name)p.playerName=name;
            const apiTime=Number(root.getAttribute('timestamp')||0)*1000;

            p.score=p.score||{}; p.ranking=p.ranking||{};
            const readPosition=(type)=>root.querySelector(`positions position[type="${type}"]`);
            const scoreTypes={global:0,economy:1,research:2,lifeform:8,military:3};
            Object.entries(scoreTypes).forEach(([key,type])=>{
                const el=readPosition(type); if(!el)return;
                const score=Number(el.getAttribute('score')||0);
                const rank=Number(String(el.textContent||'').replace(/[^0-9]/g,''));
                if(Number.isFinite(score))p.score[key]=Math.floor(score);
                if(Number.isFinite(rank)&&rank>0)p.ranking[key]=rank;
            });
            p.api=apiTime||Date.now();

            const found=[];
            root.querySelectorAll('planet').forEach((pl,index)=>{
                const pid=pl.getAttribute('id')||'';
                const coords=pl.getAttribute('coords')||'';
                if(!/^\d+:\d+:\d+$/.test(coords))return;
                const moon=pl.querySelector('moon');
                const moonId=moon?.getAttribute('id')||'';
                const planet=db.positions[coords]||{};
                db.positions[coords]={...planet,galaxy:+coords.split(':')[0],system:+coords.split(':')[1],position:+coords.split(':')[2],playerId:id,playerName:p.playerName||'',planetId:pid,planetName:pl.getAttribute('name')||planet.planetName||'',moonId,moonName:moon?.getAttribute('name')||planet.moonName||'',moon:Boolean(moon),home:index===0,api:p.api};
                found.push(coords);
            });
            p.positions=[...new Set([...(Array.isArray(p.positions)?p.positions:[]),...found])].sort(compareCoords);

            if(found.length){
                const known=new Set(found);
                p.positions=p.positions.filter(c=>known.has(c) || db.positions[c]?.api>=p.api);
                Object.keys(db.positions).forEach(c=>{
                    if(String(db.positions[c]?.playerId)===id && !known.has(c) && Number(db.positions[c]?.api||0)<p.api) delete db.positions[c];
                });
            }
            p.apiCount=found.length;saveDB();renderMarkerTable();renderCoordsTable();
        }catch(e){console.warn('[SoNiC Galaxy V41] playerData:',e);}
        finally{
            apiBusy.delete(id);
            if(String(selectedPlayerId)===String(id)){
                const coords=getPlayerPositions(id);
                if(coords.length && !coords.includes(selectedCoordinate)){
                    selectedCoordinate=selectPlayerIndicatorCoordinate(coords);
                    persistGalaxySelection();
                }
            }
            renderCoordsTable();
        }
    }

    function getGalaxyRedirectLink(coords){
        if(!/^\d+:\d+:\d+$/.test(coords||'')) return '';
        const [galaxy,system,position]=coords.split(':').map(Number);
        const params=new URLSearchParams();
        params.set('page','ingame');
        params.set('component','galaxy');
        params.set('galaxy',String(galaxy));
        params.set('system',String(system));
        params.set('position',String(position));
        return `${window.location.origin}/game/index.php?${params.toString()}`;
    }

    function persistGalaxySelection(){
        try{
            localStorage.setItem(UI_KEY,JSON.stringify({
                playerId:String(selectedPlayerId||''),
                selectedCoordinate:String(selectedCoordinate||''),
                coordsOpen:true,
                markerFilter,
                coordsPosition:coordsManualPosition,
                playerPosition:playerManualPosition,
                playerSize:playerManualSize,
                coordsSize:coordsManualSize,
                playerPanelCollapsed
            }));
        }catch(_){}
        if(/^\d+:\d+:\d+$/.test(selectedCoordinate||'')){
            try{sessionStorage.setItem('SoNiC_GalaxyLastCoord',selectedCoordinate);}catch(_){}
        }
    }

    function selectPlayerIndicatorCoordinate(coords){
        if(!Array.isArray(coords)||!coords.length) return '';
        if(selectedCoordinate && coords.includes(selectedCoordinate)) return selectedCoordinate;
        const cur=galaxySystem();
        const onCurrent=coords.find(c=>{
            const [g,s]=c.split(':').map(Number);
            return g===cur.galaxy && s===cur.system;
        });
        return onCurrent || coords[0] || '';
    }

    function getSelectedPlayerCoordinate(){
        if(!selectedPlayerId) return '';
        const coords=getPlayerPositions(selectedPlayerId);
        if(!coords.length) return '';
        if(!selectedCoordinate || !coords.includes(selectedCoordinate)){
            selectedCoordinate=selectPlayerIndicatorCoordinate(coords);
            persistGalaxySelection();
        }
        return selectedCoordinate;
    }

    function goToPlayerCoordinate(coords){
        if(!/^\d+:\d+:\d+$/.test(coords||'')) return false;
        if(!selectedPlayerId) return false;
        const coordsList=getPlayerPositions(selectedPlayerId);
        if(!coordsList.includes(coords)) return false;

        selectedCoordinate=coords;
        lastNavigatedCoord=coords;
        persistGalaxySelection();
        lastCoordsSig='';
        renderCoordsTable();

        const url=getGalaxyRedirectLink(coords);
        if(!url) return false;
        window.location.href=url;
        return true;
    }

    function selectNextPlayerCoordinate(){
        if(!selectedPlayerId) return '';
        let coords=getPlayerPositions(selectedPlayerId);
        if(!coords.length) return '';
        // Si des planètes de ce joueur portent une pastille, on ne parcourt qu'elles.
        const saved=coords.filter(c=>db.planets&&db.planets[c]);
        if(saved.length) coords=saved;

        const current=getSelectedPlayerCoordinate();
        const index=coords.indexOf(current);
        const next=coords[index < 0 ? 0 : (index+1)%coords.length];
        return next || '';
    }

    function navigateToNextPlayerPlanet(){
        const target=selectNextPlayerCoordinate();
        if(!target) return false;
        window.sonicLog('[SoNiC Galaxy V56] joueur:',selectedPlayerId,'indicateur:',selectedCoordinate,'→',target);
        return goToPlayerCoordinate(target);
    }

    function navigateToCoords(c){
        return goToPlayerCoordinate(c);
    }


