    function openHideFleetProfile() {
        document.getElementById('sonic-hide-fleet-profile')?.remove();
        let ownHide = null;
        try { ownHide = JSON.parse(localStorage.getItem('SoNiC_HideLeave_V1') || 'null'); } catch (_) {}
        const stored = ownHide && typeof ownHide === 'object' ? ownHide : loadSharedSonicSettings().hideLeave;
        const data = stored && typeof stored === 'object' ? JSON.parse(JSON.stringify(stored)) : {};
        // Activé par défaut dès qu'un réglage est enregistré (case décochable).
        data.enabled = ownHide ? data.enabled !== false : (stored && stored.enabled === true);
        data.standard = data.standard && typeof data.standard === 'object' ? data.standard : {};
        data.coordinates = data.coordinates && typeof data.coordinates === 'object' ? data.coordinates : {};
        data.variants = data.variants && typeof data.variants === 'object' ? data.variants : {};
        data.activeVariant = data.variants[data.activeVariant] ? String(data.activeVariant) : '';
        data.profiles = data.profiles && typeof data.profiles === 'object' ? data.profiles : {};
        data.profileNames = data.profileNames && typeof data.profileNames === 'object' ? data.profileNames : {};
        data.profile = String(data.profile || '');
        const profName = (n) => String(data.profileNames[n] || '').trim() || ('Profil ' + n);
        const MISSIONS = [[0,'- (Stationner)'],[1,'Attaquer'],[2,'Attaque groupée'],[3,'Transporter'],[4,'Stationner'],[5,'Maintenir'],[6,'Espionner'],[7,'Coloniser'],[8,'Recycler'],[9,'Détruire'],[15,'Expédition']];
        const DMODES = [['other','Autre corps des mêmes coordonnées'],['samesys','Même système, une autre position (ex. 16)'],['fixed','Coordonnées précises']];
        const TYPES = [[0,'- (automatique)'],[1,'Planète'],[2,'Champ de débris'],[3,'Lune']];
        const SPEEDS = [[0,'- (100 %)']].concat([100,90,80,70,60,50,40,30,20,10].map(v => [v, v + ' %']));
        const PREFS = [['','-'],['metal','Métal'],['crystal','Cristal'],['deuterium','Deutérium']];
        const SRC_TYPES = [[0,'Planète et lune'],[1,'Planète'],[3,'Lune']];
        const STD = '__std';
        let sel = STD;
        // Type du corps actuel (hors page Flotte) : lu dans la page, jamais supposé « lune ».
        const metaType = () => {
            const m = String(document.querySelector('meta[name="ogame-planet-type"]')?.content || '').toLowerCase();
            return m === 'moon' ? 3 : 1;
        };
        // Présélection : la position actuelle si elle a déjà un réglage enregistré.
        const curKeys = (() => {
            const f = window.fleetDispatcher, cp = f && f.currentPlanet;
            let g, sy, po, ty;
            if (cp) { g = Number(cp.galaxy); sy = Number(cp.system); po = Number(cp.position); ty = Number(cp.type) === 3 ? 3 : 1; }
            else { const m = String(getCurrentMoonKey() || '').match(/^(\d+):(\d+):(\d+)$/); if (m) { g = Number(m[1]); sy = Number(m[2]); po = Number(m[3]); ty = metaType(); } }
            return g ? [`${g}:${sy}:${po}:${ty}`, `${g}:${sy}:${po}`, `${g}:${sy}:${po}:0`] : [];
        })();
        const curPos = (() => {
            const f = window.fleetDispatcher, cp = f && f.currentPlanet;
            if (cp && Number(cp.galaxy)) return { g: Number(cp.galaxy), s: Number(cp.system), p: Number(cp.position), t: Number(cp.type) === 3 ? 3 : 1 };
            const m = String(getCurrentMoonKey() || '').match(/^(\d+):(\d+):(\d+)$/);
            return m ? { g: Number(m[1]), s: Number(m[2]), p: Number(m[3]), t: metaType() } : null;
        })();
        const curMatch = curKeys.find((k) => data.coordinates[k]);
        if (curMatch) sel = curMatch;
        const host = document.createElement('div');
        host.id = 'sonic-hide-fleet-profile';
        Object.assign(host.style, {position:'fixed',inset:'0',zIndex:'2147483647',background:'rgba(0,0,0,.6)',display:'flex',alignItems:'center',justifyContent:'center',padding:'14px',boxSizing:'border-box'});
        const fld = 'padding:3px 5px;background:#2f4f5f;border:1px solid #5d8196;color:#fff;border-radius:3px;box-sizing:border-box';
        const row = (label, inner) => `<div style="display:flex;align-items:center;justify-content:space-between;gap:8px;min-height:28px"><span style="color:#cfd8e0">${label}</span><span style="display:flex;gap:4px">${inner}</span></div>`;
        const selectHtml = (attr, list, cur) => `<select ${attr} style="${fld};width:190px">${list.map(([v, l]) => `<option value="${v}" ${String(cur) === String(v) ? 'selected' : ''}>${l}</option>`).join('')}</select>`;
        const keyLabel = (k) => { if (k.startsWith('v:')) return '⚙ Réglage ' + k.slice(2) + (data.activeVariant === k.slice(2) ? ' (utilisé)' : ''); if (k === STD) return '★ Standard (valeurs par défaut)'; const [g, sy, po, t] = k.split(':'); return `${g}:${sy}:${po} · ${t === '1' ? 'Planète' : t === '3' ? 'Lune' : 'Planète et lune'}`; };
        const entryOf = (k) => (k === STD ? data.standard : k.startsWith('v:') ? (data.variants[k.slice(2)] || (data.variants[k.slice(2)] = {})) : (data.coordinates[k] || (data.coordinates[k] = {})));
        const parseT = (t) => { if (t && typeof t === 'object') return t; const m = String(t || '').replace(/[\[\]\s]/g, '').match(/^(\d+):(\d+):(\d+)$/); return m ? { g: Number(m[1]), s: Number(m[2]), p: Number(m[3]) } : null; };
        const num = (v) => (v == null || v === '' || !Number.isFinite(Number(v)) ? '' : Math.max(0, Number(v)));
        const renderForm = () => {
            const e = entryOf(sel), d = data.standard, isStd = sel === STD;
            const ph = (v) => (isStd || v == null || v === '' ? '' : String(v));
            const t = parseT(e.target) || {}, dt = parseT(d.target) || {};
            const ships = e.ships || {}, dships = d.ships || {};
            const box = (k, v, pv, w) => `<input type="number" min="0" data-hf="${k}" value="${num(v)}" placeholder="${isStd ? '' : (pv || '')}" style="${fld};width:${w || 70}px;text-align:right">`;
            host.querySelector('[data-hide-form]').innerHTML = `
              ${row('Destination', selectHtml('data-hf="dmode"', isStd ? DMODES.slice(0, 2) : DMODES, e.destMode || (isStd ? 'other' : '')))}
              <div data-hf-box="samesys">${row('Position dans le système', box('dpos', e.destPos, d.destPos || 16, 70))}</div>
              <div data-hf-box="fixed">${row('Coordonnées précises', box('tg', t.g, dt.g, 52) + box('ts', t.s, dt.s, 52) + box('tp', t.p, dt.p, 52))}</div>
              ${row('Type de destination', selectHtml('data-hf="ttype"', TYPES, e.targetType != null ? e.targetType : (isStd ? 0 : '')))}
              ${row('Mission', selectHtml('data-hf="mission"', MISSIONS, e.mission != null ? e.mission : (isStd ? 0 : '')))}
              ${row('Vitesse', selectHtml('data-hf="speed"', SPEEDS, e.speed != null ? e.speed : (isStd ? 0 : '')))}
              <div style="color:#6fb6e0;font-size:13px;margin:10px 0 2px">Ressources restantes</div>
              ${[['metal','Métal'],['crystal','Cristal'],['deuterium','Deutérium']].map(([k, l]) => row(l, box(k, e[k], d[k], 110))).join('')}
              ${row('Ressource préférée', selectHtml('data-hf="pref"', PREFS, e.pref || ''))}
              <div style="color:#6fb6e0;font-size:13px;margin:10px 0 2px">Vaisseaux restants</div>
              ${EXPEDITION_PROFILE_SHIPS.map(sh => row(`<span style="display:inline-flex;align-items:center;gap:6px">${sonicShipIconHtml(sh.id, sh.short, 22)}${sh.name}</span>`, box('ship_' + sh.id, ships[sh.id], dships[sh.id], 110))).join('')}`;
            const syncBoxes = () => {
                const m = host.querySelector('[data-hf="dmode"]').value || (isStd ? 'other' : (d.destMode || 'other'));
                host.querySelectorAll('[data-hf-box]').forEach((el) => { el.style.display = el.dataset.hfBox === m ? '' : 'none'; });
            };
            host.querySelector('[data-hf="dmode"]').addEventListener('change', syncBoxes);
            if (!isStd) {
                // Listes à choix : « inchangé » = valeur du standard.
                ['dmode', 'ttype', 'mission', 'speed'].forEach((k) => {
                    const el = host.querySelector(`[data-hf="${k}"]`);
                    const cur = k === 'ttype' ? e.targetType : k === 'dmode' ? e.destMode : e[k];
                    // Toujours proposer « = standard » pour pouvoir revenir au réglage commun après une différence.
                    const o = document.createElement('option'); o.value = ''; o.textContent = '= standard'; el.insertBefore(o, el.firstChild);
                    if (cur == null) el.value = '';
                });
            }
            syncBoxes();
        };
        const collect = () => {
            const e = entryOf(sel), q = (k) => host.querySelector(`[data-hf="${k}"]`);
            if (!q('mission')) return;
            const n = (k) => { const v = q(k).value; return v === '' ? null : Math.max(0, Math.floor(Number(v) || 0)); };
            const g = n('tg'), sy = n('ts'), po = n('tp');
            if (g && sy && po) e.target = { g, s: sy, p: po }; else delete e.target;
            let dm = q('dmode').value;
            if (!dm && sel !== STD && g && sy && po) dm = 'fixed';
            // « Coordonnées précises » sans coordonnées ne change rien : on reste sur le standard.
            if (dm === 'fixed' && !(g && sy && po) && sel !== STD) dm = '';
            if (dm) e.destMode = dm; else delete e.destMode;
            const dp = n('dpos'); if (dp) e.destPos = Math.min(16, dp); else delete e.destPos;
            const opt = (k, key) => { const v = q(k).value; if (v === '') delete e[key]; else e[key] = Number(v); };
            opt('ttype', 'targetType'); opt('mission', 'mission'); opt('speed', 'speed');
            ['metal', 'crystal', 'deuterium'].forEach((k) => { const v = n(k); if (v === null) delete e[k]; else e[k] = v; });
            const pv = q('pref').value; if (pv) e.pref = pv; else delete e.pref;
            e.ships = {};
            EXPEDITION_PROFILE_SHIPS.forEach((sh) => { const v = n('ship_' + sh.id); if (v !== null) e.ships[sh.id] = v; });
        };
        const renderTop = () => {
            const keys = Object.keys(data.coordinates).sort((x, y) => x.localeCompare(y, 'fr', { numeric: true }));
            const bs = 'padding:4px 9px;border-radius:3px;cursor:pointer;font-size:11px;border:1px solid #4a6a7c;background:#1e2f3a;color:#cfe3ee';
            host.querySelector('[data-hide-sel]').innerHTML = `<select data-hide-pick style="${fld};flex:1;min-width:150px;max-width:100%">${[STD].concat(Object.keys(data.variants).sort((x, y) => x - y).map(v => 'v:' + v), keys).map(k => `<option value="${k}" ${k === sel ? 'selected' : ''}>${curKeys.includes(k) ? '● ' : ''}${keyLabel(k).replace('★ Standard (valeurs par défaut)', '★ Standard (toutes les positions)')}</option>`).join('')}</select>`
              + (sel === STD ? '' : `<button type="button" data-hide-reset style="${bs}" title="Efface les différences de cette position : elle reprend le standard">↺ = Standard</button><button type="button" data-hide-del2 style="${bs};border-color:#7a4147;color:#f0b3b8" title="Supprime cette position de la liste">🗑 Supprimer</button>`)
              + `<span style="color:#8392a0;font-size:10px;width:100%">${keys.length} position(s) personnalisée(s)</span>`;
            host.querySelector('[data-hide-del]').style.display = 'none';
            const nv = Object.keys(data.variants).length;
            host.querySelector('[data-hide-variant-count]').textContent = nv + ' / 9 réglage(s) supplémentaire(s)';
            host.querySelector('[data-hide-add-variant]').disabled = nv >= 9;
            const ar = host.querySelector('[data-hide-active-row]');
            ar.style.display = sel.startsWith('v:') ? 'flex' : 'none';
            host.querySelector('[data-hide-active]').checked = sel.startsWith('v:') && data.activeVariant === sel.slice(2);
            host.querySelector('[data-hide-title]').textContent = 'Options pour ' + (sel === STD ? 'toutes les positions' : keyLabel(sel));
        };
        const btn = 'padding:5px 12px;background:#2b4a5c;border:1px solid #6b93a8;color:#fff;border-radius:3px;cursor:pointer';
        host.innerHTML = `<div style="width:430px;max-width:96vw;max-height:92vh;overflow:auto;background:#141b22;border:1px solid #5d8196;border-radius:6px;box-shadow:0 12px 40px rgba(0,0,0,.75);color:#edf2f7;font:12px Arial,sans-serif;padding:12px;box-sizing:border-box">
          <div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:6px"><b data-hide-title style="color:#6fb6e0;font-size:15px"></b><span style="display:flex;gap:6px;align-items:center"><button type="button" data-hide-pds title="Ouvrir les réglages des flottes des portes de saut" style="padding:3px 9px;background:#1e2f3a;border:1px solid #4a6a7c;color:#cfe3ee;border-radius:3px;cursor:pointer;font-size:11px">⚡ Réglages des PDS</button><button type="button" data-hide-close style="background:none;border:none;color:#ddd;font-size:19px;cursor:pointer">×</button></span></div>
          <label style="display:flex;align-items:center;gap:7px;padding:4px 0"><input type="checkbox" data-hide-enabled ${data.enabled ? 'checked' : ''}> <b>Activer ces réglages pour « Cacher la flotte »</b></label>
          <div style="font-size:10px;color:#8392a0;line-height:1.4;margin-bottom:8px">Désactivé : tous les vaisseaux et toutes les ressources partent vers l'autre corps des mêmes coordonnées en Stationner à 100 %. Une position ne remplace que les champs remplis, les autres reprennent le standard (valeurs grisées).</div>
          <div style="margin-bottom:8px;display:flex;gap:5px;flex-wrap:wrap;align-items:center"><span style="color:#8392a0">Préréglage :</span><select data-hide-profile style="${fld};flex:1;min-width:170px"></select><button type="button" data-hide-profile-save style="${btn};padding:4px 8px" title="Enregistre tous les réglages actuels (standard, positions, réglages 2 à 10) dans le profil choisi">💾 Sauver</button><button type="button" data-hide-profile-rename style="${btn};padding:4px 8px" title="Renommer le profil choisi">✎</button></div>
          <div style="color:#8392a0;font-size:10px;margin-bottom:3px">Réglages enregistrés — clique pour choisir</div>
          <div data-hide-sel style="display:flex;gap:5px;flex-wrap:wrap;margin-bottom:8px"></div>
          <div style="margin-bottom:6px"><button type="button" data-hide-add-current style="${btn};width:100%;text-align:left" title="Crée des réglages propres à la position où vous êtes, puis saisissez la destination, la mission, la vitesse, les ressources et les vaisseaux à laisser">${curPos ? `＋ Choisir des réglages différents pour la position actuelle <b style="color:#ffd85b">${curPos.g}:${curPos.s}:${curPos.p} · ${curPos.t === 3 ? 'Lune' : 'Planète'}</b>` : '＋ Réglages différents pour la position actuelle (position non détectée)'}</button></div>
          <div style="display:flex;gap:6px;flex-wrap:wrap;align-items:center;margin-bottom:8px"><button type="button" data-hide-add-variant style="${btn}" title="Crée un réglage supplémentaire (jusqu'à 10 au total) : destination, mission, vitesse, ressources et vaisseaux. Choisissez ensuite celui que « Cacher la flotte » doit utiliser.">＋ Ajouter un réglage</button><span data-hide-variant-count style="color:#8392a0;font-size:10px"></span></div>
          <label data-hide-active-row style="display:none;align-items:center;gap:7px;padding:3px 0 8px"><input type="checkbox" data-hide-active> <span>Utiliser ce réglage pour « Cacher la flotte » (sinon : standard / position)</span></label>
          <div data-hide-form style="border-top:1px solid rgba(255,255,255,.1);padding-top:6px"></div>
          <div style="position:sticky;bottom:-12px;margin:12px -12px -12px;padding:10px 12px;background:#141b22;border-top:1px solid rgba(255,255,255,.14);display:flex;align-items:center;gap:8px"><button type="button" data-hide-del title="Supprimer le réglage de cette position" style="${btn};border-color:#7a4147;color:#f0b3b8">🗑 Supprimer</button><span style="flex:1"></span><button type="button" data-hide-cancel style="${btn}">Annuler</button><button type="button" data-hide-save style="${btn};border-color:#c39d34;color:#ffd85b">💾 Enregistrer</button></div>
        </div>`;
        document.body.appendChild(host);
        const close = () => host.remove();
        const go = (k) => { collect(); sel = k; renderTop(); renderForm(); };
        host.querySelector('[data-hide-close]').addEventListener('click', close);
        host.querySelector('[data-hide-pds]').addEventListener('click', () => { close(); try { openFleetProfileSettings(); } catch (_) {} });
        host.querySelector('[data-hide-cancel]').addEventListener('click', close);
        host.addEventListener('mousedown', e => { if (e.target === host) close(); });
        host.querySelector('[data-hide-sel]').addEventListener('change', (e) => { const p = e.target.closest('[data-hide-pick]'); if (p) go(p.value); });
        host.querySelector('[data-hide-sel]').addEventListener('click', (e) => {
            if (e.target.closest('[data-hide-reset]')) { if (sel === STD) return; if (sel.startsWith('v:')) data.variants[sel.slice(2)] = {}; else data.coordinates[sel] = {}; renderTop(); renderForm(); showToast('Position remise au standard : pense à « Enregistrer ».'); }
            else if (e.target.closest('[data-hide-del2]')) { if (sel === STD) return; if (sel.startsWith('v:')) { if (data.activeVariant === sel.slice(2)) data.activeVariant = ''; delete data.variants[sel.slice(2)]; } else delete data.coordinates[sel]; sel = STD; renderTop(); renderForm(); }
        });
        host.querySelector('[data-hide-del]').addEventListener('click', () => { if (sel === STD) return; if (sel.startsWith('v:')) { if (data.activeVariant === sel.slice(2)) data.activeVariant = ''; delete data.variants[sel.slice(2)]; } else delete data.coordinates[sel]; sel = STD; renderTop(); renderForm(); });
        const addKey = (g, sy, po, t) => { if (!(g > 0 && sy > 0 && po > 0)) return; const k = `${g}:${sy}:${po}` + (t ? ':' + t : ''); collect(); if (!data.coordinates[k]) data.coordinates[k] = {}; sel = k; renderTop(); renderForm(); setTimeout(() => { const first = host.querySelector('[data-hf="tg"]'); if (first && !first.value) first.focus(); }, 30); };
        host.querySelector('[data-hide-add-current]').addEventListener('click', () => {
            if (curPos) addKey(curPos.g, curPos.s, curPos.p, curPos.t);
        });
        host.querySelector('[data-hide-add-variant]').addEventListener('click', () => {
            collect();
            let n = 2; while (data.variants[String(n)] && n <= 10) n++;
            if (n > 10) return;
            data.variants[String(n)] = {};
            sel = 'v:' + n; renderTop(); renderForm();
        });
        host.querySelector('[data-hide-active]').addEventListener('change', (e) => {
            if (!sel.startsWith('v:')) return;
            data.activeVariant = e.target.checked ? sel.slice(2) : '';
            renderTop();
        });
        const persist = (closeAfter, msg) => {
            try {
                collect();
                data.enabled = host.querySelector('[data-hide-enabled]').checked;
                // Les positions sans aucune différence avec le standard ne sont pas conservées (la liste reste courte).
                Object.keys(data.coordinates).forEach((k) => {
                    const en = data.coordinates[k] || {};
                    const has = Object.keys(en).some((f) => f !== 'ships' && !(f === 'destMode' && en[f] === 'fixed' && !en.target) && en[f] != null && en[f] !== '') || Object.keys(en.ships || {}).length > 0;
                    if (!has) delete data.coordinates[k];
                });
                const hideText = JSON.stringify(data);
                try { localStorage.setItem('SoNiC_HideLeave_V1', hideText); }
                catch (qe) { if (window.sonicFreeStorage) window.sonicFreeStorage(hideText.length * 2 + 4096); localStorage.setItem('SoNiC_HideLeave_V1', hideText); }
                try { saveSharedSonicSettings({ hideLeave: data }); } catch (_) {}
                const back = JSON.parse(localStorage.getItem('SoNiC_HideLeave_V1') || 'null');
                if (!back) throw new Error('relecture vide');
                if (closeAfter) close();
                showToast(msg || ('🫥 Réglages « Cacher la flotte » enregistrés (' + (back.enabled ? 'activés' : 'désactivés') + ', ' + Object.keys(back.coordinates || {}).length + ' position(s)).'));
                return true;
            } catch (err) {
                console.error('[SoNiC] Échec enregistrement Cacher', err);
                sonicAlert('SoNiC : enregistrement impossible — ' + (err && err.message || err));
                return false;
            }
        };
        host.querySelector('[data-hide-save]').addEventListener('click', () => { persist(true); });
        // Profils : tous les réglages d'un coup (standard, positions, réglages 2 à 10).
        const SNAP = ['standard', 'coordinates', 'variants', 'activeVariant'];
        const renderProfiles = () => {
            const o = [['', '— réglages actuels —'], ['classic', 'Classique (espionner la position 16 de mon système)']];
            for (let n = 1; n <= 10; n++) o.push([String(n), (data.profiles[n] ? '● ' : '○ ') + 'Profil ' + n + ' — ' + profName(n).replace(/^Profil \d+$/, '').replace(/^$/, (data.profiles[n] ? 'enregistré' : 'vide'))]);
            const el = host.querySelector('[data-hide-profile]');
            el.innerHTML = o.map(([v, l]) => `<option value="${v}" ${v === data.profile ? 'selected' : ''}>${l.replace(/[<>&]/g, '')}</option>`).join('');
            const isN = /^\d+$/.test(data.profile);
            host.querySelector('[data-hide-profile-save]').disabled = !isN;
            host.querySelector('[data-hide-profile-rename]').disabled = !isN;
        };
        host.querySelector('[data-hide-profile]').addEventListener('change', (e) => {
            collect();
            const v = e.target.value;
            data.profile = v;
            if (v === 'classic') {
                Object.assign(data.standard, { mission: 6, destMode: 'samesys', destPos: 16, targetType: 1, speed: 0, metal: 0, crystal: 0, deuterium: 0 });
                delete data.standard.target; data.standard.ships = {};
                host.querySelector('[data-hide-enabled]').checked = true;
                sel = STD; renderTop(); renderForm(); renderProfiles();
                persist(false, '⚡ Préréglage Classique appliqué.');
            } else if (/^\d+$/.test(v)) {
                const snap = data.profiles[v];
                if (snap) {
                    SNAP.forEach((k) => { data[k] = JSON.parse(JSON.stringify(snap[k] != null ? snap[k] : (k === 'activeVariant' ? '' : {}))); });
                    sel = STD; renderTop(); renderForm(); renderProfiles();
                    persist(false, '📂 ' + profName(v) + ' chargé et appliqué.');
                } else {
                    renderProfiles();
                    showToast(profName(v) + ' est vide : règle ce que tu veux puis clique sur 💾 Sauver.');
                }
            } else renderProfiles();
        });
        host.querySelector('[data-hide-profile-save]').addEventListener('click', () => {
            if (!/^\d+$/.test(data.profile)) return;
            collect();
            const snap = {}; SNAP.forEach((k) => { snap[k] = JSON.parse(JSON.stringify(data[k] != null ? data[k] : (k === 'activeVariant' ? '' : {}))); });
            data.profiles[data.profile] = snap;
            renderProfiles();
            persist(false, '💾 ' + profName(data.profile) + ' enregistré.');
        });
        host.querySelector('[data-hide-profile-rename]').addEventListener('click', () => {
            if (!/^\d+$/.test(data.profile)) return;
            const cur = profName(data.profile);
            const nv = window.prompt('Nom du profil ' + data.profile + ' :', cur);
            if (nv == null) return;
            const t = String(nv).trim().slice(0, 30);
            if (t) data.profileNames[data.profile] = t; else delete data.profileNames[data.profile];
            renderProfiles();
        });
        renderProfiles();
        renderTop();
        renderForm();
    }

    function buildSettingsPanel() {
        const profile = getActiveFleetProfile();
        ensureLegacyJumpgateMigration(profile);
        const auto = isAutoProfile(profile);
        const keys = Object.keys(profile.coordinates || {}).sort((a,b) => a.localeCompare(b, 'fr', { numeric:true }));
        const currentKey = getCurrentMoonKey();
        const currentConfigured = currentKey && !!profile.coordinates[currentKey];

        let content;
        let standardCardHtml = '';
        if (auto) {
            content = `<div class="sonic-fleet-auto-card">
                <div class="sonic-fleet-auto-title"><strong>⚡ MODE AUTO</strong><span>Réserve calculée à chaque clic sur PROFIL</span></div>
                <div class="sonic-fleet-auto-rule"><b>Priorité :</b> PT → GT → PF. SoNiC laisse exactement le nombre de cargos nécessaire pour pouvoir emporter <b>toutes les ressources présentes</b> sur la lune.</div>
                <div class="sonic-fleet-auto-grid"><div><b>PT</b><span>capacité réelle SoNiC</span></div><div><b>GT</b><span>capacité réelle SoNiC</span></div><div><b>PF</b><span>capacité réelle SoNiC</span></div></div>
                <div class="sonic-fleet-auto-note">Si les PT disponibles ne suffisent pas, AUTO ajoute les GT, puis les PF. Si la flotte disponible ne permet toujours pas de couvrir toutes les ressources, AUTO laisse <b>le maximum de cargos disponibles</b>. Les autres vaisseaux restent entièrement disponibles pour le saut.</div>
                ${currentKey ? `<div class="sonic-fleet-auto-current">PDS actuelle : <b>${escapeHtml(currentKey)}</b></div>` : ''}
            </div>`;
        } else {
            const cards = keys.map(key => {
                const reserve = profile.coordinates[key];
                const items = summarizeReserve(reserve);
                const current = key === currentKey;
                return `<article class="sonic-fleet-coordinate-card">
                    <div class="sonic-fleet-coordinate-head">
                        <div class="sonic-fleet-coordinate-title"><strong>${current ? '● ' : ''}${escapeHtml(key)}</strong><small>${current ? 'PDS actuellement affichée · spécifique' : 'Réglage spécifique'}</small></div>
                        <div class="sonic-fleet-coordinate-actions">
                            <button type="button" data-fleet-action="edit" data-coordinate="${escapeHtml(key)}">✎ Modifier</button>
                            <button type="button" data-fleet-action="delete-coordinate" data-coordinate="${escapeHtml(key)}" class="danger icon" title="${profile.standardEnabled === true ? 'Supprimer cette exception (retour au standard)' : 'Supprimer cette coordonnée'}">🗑</button>
                        </div>
                    </div>
                    <div class="sonic-fleet-summary">${(items.length || summarizeResources(reserve).length) ? items.map(item => `<span class="sonic-fleet-summary-item">${sonicShipIconHtml(item.ship.ogameId, "", 18)}<b>${item.ship.short}</b> ${formatNumber(item.value)}</span>`).join('') + resourceChipsHtml(reserve) : '<span class="sonic-fleet-summary-item">Aucun vaisseau réservé — toute la flotte peut sauter.</span>'}</div>
                </article>`;
            }).join('');
            const stdItems = summarizeReserve(profile.standard);
            const stdOn = profile.standardEnabled === true;
            const standardCard = `<article class="sonic-std-card${stdOn ? ' is-on' : ''}">
                <div class="sonic-std-head">
                    <div class="sonic-std-title"><strong>★ PROFIL STANDARD</strong><small>${stdOn ? 'Appliqué à toutes les coordonnées sans réglage spécifique' : 'Désactivé : seules les coordonnées configurées ci-dessous sont utilisables'}</small></div>
                    <div class="sonic-std-actions">
                        <button type="button" data-fleet-action="toggle-standard" class="${stdOn ? 'on' : ''}">${stdOn ? '● ACTIF' : '○ INACTIF'}</button>
                        <button type="button" data-fleet-action="edit-standard">✎ Modifier</button>
                        <button type="button" data-fleet-action="reset-standard" class="danger" title="Vider le profil standard">🗑</button>
                    </div>
                </div>
                <div class="sonic-fleet-summary">${(stdItems.length || summarizeResources(profile.standard).length) ? stdItems.map(item => `<span class="sonic-fleet-summary-item">${sonicShipIconHtml(item.ship.ogameId, "", 18)}<b>${item.ship.short}</b> ${formatNumber(item.value)}</span>`).join('') + resourceChipsHtml(profile.standard) : '<span class="sonic-fleet-summary-empty">Aucun vaisseau à laisser (tout part au saut)</span>'}</div>
                ${currentKey ? `<div class="sonic-std-status">PDS actuelle <b>${escapeHtml(currentKey)}</b> : ${profile.coordinates[currentKey] ? '<span class="specific">réglage spécifique</span>' : (stdOn ? '<span class="standard">utilise le standard</span>' : '<span class="none">non configurée</span>')}</div>` : ''}
            </article>`;
            const specificHead = `<div class="sonic-spec-head"><strong>Réglages spécifiques par coordonnée</strong><small>${keys.length ? keys.length + ' coordonnée' + (keys.length > 1 ? 's' : '') + ' · remplace(nt) le standard' : 'Aucun — le standard s’applique partout'}</small></div>`;
            standardCardHtml = standardCard;
            content = specificHead + (cards ? `<div class="sonic-spec-grid">${cards}</div>` : `<div class="sonic-fleet-empty"><strong>Aucune spécificité</strong>Utilisez « ＋ PDS actuelle » ou « ＋ Coordonnée » pour définir une exception au standard.</div>`);
        }

        const toolbarButtons = auto
            ? ``
            : `<button type="button" data-fleet-action="add-current">＋ PDS actuelle</button><button type="button" data-fleet-action="add-coordinate">＋ Coordonnée</button><button type="button" data-fleet-action="add-profile">＋ Nouveau profil</button><button type="button" data-fleet-action="rename">✎ Renommer</button>`;
        const note = auto
            ? `<b>AUTO :</b> le nombre de GT/PT/PF à laisser est recalculé en fonction des ressources et des cargos réellement disponibles au moment du clic sur <b>PROFIL</b>. <b>Enregistrer</b> mémorise la sélection du profil AUTO.`
            : `<b>Règle :</b> la quantité configurée est la quantité qui doit RESTER sur la PDS. <b>Enregistrer</b> mémorise le profil sélectionné. <b>PROFIL</b> soustrait cette réserve aux vaisseaux disponibles et remplit le formulaire natif avec le surplus à sauter.`;

        return `<div class="sonic-fleet-profile-panel">
            <div class="sonic-fleet-profile-head"><div><strong>⚡ CONFIGURATION DES FLOTTES</strong><span>${auto ? 'Mode automatique · cargos nécessaires aux ressources' : 'Un profil standard + des exceptions par coordonnée'}</span></div><button type="button" data-fleet-action="close">×</button></div>
            ${standardCardHtml ? `<div style="padding:6px 10px 0">${standardCardHtml}</div>` : ''}
            <div class="sonic-fleet-profile-toolbar">
                <span>PROFIL</span>
                <select data-fleet-profile-select title="Profil affiché dans V : sélectionnez une configuration">${fleetProfiles.profiles.map(p => `<option value="${escapeHtml(p.id)}" ${p.id === profile.id ? 'selected' : ''}>⚡ ${escapeHtml(p.name)}</option>`).join('')}</select>
                <span>Z →</span>
                <select data-fleet-z-profile-select title="Profil utilisé par le raccourci Z">${fleetProfiles.profiles.map(p => `<option value="${escapeHtml(p.id)}" ${p.id === fleetProfiles.zProfileId ? 'selected' : ''}>Z · ${escapeHtml(p.name)}</option>`).join('')}</select>
                ${toolbarButtons}
                <button type="button" data-fleet-action="expedition-profile" title="Configurer la flotte d'expédition">🚀 Flotte d'expé</button><button type="button" data-fleet-action="collect-profile" title="Configurer Collecter">📦 Collecter</button><button type="button" data-fleet-action="transport-profile" title="Configurer Transporter : vaisseaux et ressources à prendre">🚚 Transporter</button><button type="button" data-fleet-action="station-profile" title="Configurer Stationner : vaisseaux et ressources à prendre">⚓ Stationner</button><button type="button" data-fleet-action="hide-profile" title="Configurer Cacher la flotte">🫥 Cacher</button><button type="button" data-fleet-action="recall-profile" title="Quantités à laisser sur la planète quand tu cliques Vaisseaux (touche V), en plus de la réserve d'expédition">🚀 Vaisseaux</button>
            </div>
            <div class="sonic-fleet-profile-note">${note}${currentKey ? ` · PDS actuelle : <b>${escapeHtml(currentKey)}</b>${(!auto && !currentConfigured) ? ' · non configurée' : ''}` : ''}</div>
            <label class="sonic-gate-goto" style="display:flex;align-items:center;gap:6px;margin:6px 10px;color:#cfe3ee;font:11px Arial,sans-serif;cursor:pointer"><input type="checkbox" ${(() => { try { return JSON.parse(localStorage.getItem('SoNiC_Suite_Settings') || '{}').gateGoToDest === true ? 'checked' : ''; } catch (_) { return ''; } })()} onchange="window.sonicSetGateGoto&&window.sonicSetGateGoto(this.checked)"> Aller sur les coordonnées de destination après un saut</label>
            <label class="sonic-gate-goto" style="display:flex;align-items:center;gap:6px;margin:6px 10px;color:#cfe3ee;font:11px Arial,sans-serif;cursor:pointer"><input type="checkbox" ${(() => { try { return JSON.parse(localStorage.getItem('SoNiC_Suite_Settings') || '{}').gotoOriginDest === false ? '' : 'checked'; } catch (_) { return 'checked'; } })()} onchange="window.sonicSetOriginGoto&&window.sonicSetOriginGoto(this.checked)"> Aller sur la planète/lune d'origine (destination présélectionnée sur la page Flotte)</label>
            <div class="sonic-fleet-coordinate-list">${content}</div>
            <div class="sonic-fleet-profile-footer"><span><b class="sonic-shortcut-key">Z</b> applique le profil « Z → » · <span class="sonic-shortcut-help-v">V</span> ouvre cette configuration · <b class="sonic-shortcut-key">A</b> prend tout · <b class="sonic-shortcut-key">Entrée</b> saute</span><div class="sonic-fleet-foot-actions">${auto ? '' : '<button type="button" data-fleet-action="delete-profile" class="sfp-del">🗑 Supprimer le profil</button>'}<button type="button" data-fleet-action="save-profile" class="sfp-save">💾 Enregistrer</button><button type="button" data-fleet-action="close">FERMER</button></div></div>
            <div class="sonic-fleet-editor" data-fleet-editor><div class="sonic-fleet-editor-panel"><div class="sonic-fleet-editor-head"><strong data-editor-title></strong><small>Quantités à LAISSER sur cette PDS. Le surplus de vaisseaux sera proposé au saut.</small></div><div class="sonic-fleet-editor-cols"><section><h4>Vaisseaux</h4><div class="sonic-fleet-editor-rows">${SHIPS.map(ship => `<div class="sonic-fleet-editor-row"><span class="sonic-fleet-profile-icon sonic-fleet-icon-${ship.ogameId}" title="${escapeHtml(ship.name)}">${sonicShipIconHtml(ship.ogameId, ship.short)}</span><span class="sonic-fleet-editor-name">${escapeHtml(ship.name)}</span><input type="text" inputmode="numeric" autocomplete="off" data-editor-ship="${ship.ogameId}" value="0" aria-label="Réserve ${escapeHtml(ship.name)}"></div>`).join('')}</div></section><section class="sonic-fleet-editor-res"><h4>Ressources à laisser</h4><div class="sonic-fleet-editor-rows">${RES_KEYS.map(r => `<div class="sonic-fleet-editor-row"><span class="sonic-fleet-profile-icon sonic-res-tile" title="${r.name}">${sonicResIconHtml(r, 24)}</span><span class="sonic-fleet-editor-name">${r.name}</span><input type="text" inputmode="numeric" autocomplete="off" data-editor-res="${r.id}" value="0" aria-label="Ressource ${r.name}"></div>`).join('')}</div><p class="sonic-fleet-editor-hint">Quantité qui reste sur la position</p></section></div><div class="sonic-fleet-editor-foot"><button type="button" data-fleet-action="editor-cancel">ANNULER</button><button type="button" class="primary" data-fleet-action="editor-save">ENREGISTRER</button></div></div></div>
        </div>`;
    }

    function sonicFleetAsk(modal, opts) {
        return new Promise(resolve => {
            modal.querySelector('.sonic-fleet-ask')?.remove();
            const el = document.createElement('div');
            el.className = 'sonic-fleet-ask';
            el.innerHTML = `<div class="sonic-fleet-ask-box${opts.danger ? ' danger' : ''}">
                <div class="sonic-fleet-ask-head"><span>${opts.icon || '⚡'}</span><strong>${escapeHtml(opts.title || '')}</strong></div>
                <div class="sonic-fleet-ask-body">${opts.message || ''}${opts.input ? `<input type="text" autocomplete="off" data-ask-input maxlength="40" value="${escapeHtml(opts.value || '')}" placeholder="${escapeHtml(opts.placeholder || '')}">` : ''}</div>
                <div class="sonic-fleet-ask-foot">${opts.alertOnly ? '' : '<button type="button" data-ask="no">Annuler</button>'}<button type="button" class="${opts.danger ? 'danger' : 'primary'}" data-ask="yes">${escapeHtml(opts.confirmText || 'Valider')}</button></div>
            </div>`;
            const done = value => { el.remove(); resolve(value); };
            el.addEventListener('click', e => {
                const b = e.target.closest('[data-ask]');
                if (b) { e.stopPropagation(); done(b.dataset.ask === 'yes' ? (opts.input ? (el.querySelector('[data-ask-input]').value.trim() || null) : true) : null); }
                else if (e.target === el) done(null);
            });
            el.addEventListener('keydown', e => {
                e.stopPropagation();
                if (e.key === 'Escape') done(null);
                if (e.key === 'Enter') { e.preventDefault(); el.querySelector('[data-ask="yes"]').click(); }
            });
            modal.appendChild(el);
            (el.querySelector('[data-ask-input]') || el.querySelector('[data-ask="yes"]')).focus();
        });
    }

    function openEditor(modal, coordinate) {
        const profile = getActiveFleetProfile();
        const isStd = coordinate === '__standard__';
        const reserve = isStd ? (profile.standard = normalizeReserve(profile.standard)) : createCoordinate(profile, coordinate);
        if (!reserve) return;
        const editor = modal.querySelector('[data-fleet-editor]');
        editor.dataset.coordinate = coordinate;
        editor.querySelector('[data-editor-title]').textContent = isStd ? 'RÉSERVE STANDARD — toutes les coordonnées' : `RÉSERVE — ${coordinate}`;
        editor.querySelectorAll('[data-editor-ship]').forEach(input => {
            input.value = formatNumber(reserve[input.dataset.editorShip] || 0);
        });
        editor.querySelectorAll('[data-editor-res]').forEach(input => {
            input.value = formatNumber(reserve['res_' + input.dataset.editorRes] || 0);
            if (input.dataset.editorRes === 'lithium') {
                // Le lithium ne peut pas être transporté : champ grisé.
                input.value = '0'; input.disabled = true; input.title = 'Le lithium ne se transporte pas';
                const box = input.closest('label,div'); if (box) box.style.opacity = '.4';
            }
        });
        editor.classList.add('open');
    }

    function closeEditor(modal) {
        modal.querySelector('[data-fleet-editor]')?.classList.remove('open');
    }

    function bindSettingsPanel(modal) {
        const select = modal.querySelector('[data-fleet-profile-select]');
        select?.addEventListener('change', () => {
            fleetProfiles.activeProfileId = select.value;
            saveFleetProfiles();
            modal.innerHTML = buildSettingsPanel();
            bindSettingsPanel(modal);
        });

        const zSelect = modal.querySelector('[data-fleet-z-profile-select]');
        zSelect?.addEventListener('change', () => {
            fleetProfiles.zProfileId = zSelect.value;
            saveFleetProfiles();
            modal.innerHTML = buildSettingsPanel();
            bindSettingsPanel(modal);
        });

        sonicFixResIcons(modal);
        if (modal.__sonicFleetClick) modal.removeEventListener('click', modal.__sonicFleetClick);
        modal.__sonicFleetClick = async event => {
            const target = event.target.closest('[data-fleet-action]');
            if (!target) return;
            const action = target.dataset.fleetAction;
            const coordinate = target.dataset.coordinate;
            const profile = getActiveFleetProfile();

            if (action === 'close') { modal.remove(); return; }
            if (action === 'expedition-profile') { openExpeditionFleetProfile(); return; }
            if (action === 'collect-profile') { openCollectResourcesProfile(); return; }
            if (action === 'transport-profile') { openMissionProfile('transport'); return; }
            if (action === 'station-profile') { openMissionProfile('station'); return; }
            if (action === 'hide-profile') { openHideFleetProfile(); return; }
            if (action === 'recall-profile') { window.SoNiCRecallReserve?.openTable?.(); return; }
            if (action === 'editor-cancel') { closeEditor(modal); return; }
            if (action === 'edit') { if (isAutoProfile(profile)) return; openEditor(modal, coordinate); return; }
            if (action === 'edit-standard') { if (isAutoProfile(profile)) return; openEditor(modal, '__standard__'); return; }
            if (action === 'toggle-standard') {
                if (isAutoProfile(profile)) return;
                profile.standard = normalizeReserve(profile.standard);
                profile.standardEnabled = profile.standardEnabled !== true;
                if (profile.standardEnabled) fleetProfiles.zProfileId = profile.id;
                saveFleetProfiles();
                modal.innerHTML = buildSettingsPanel();
                bindSettingsPanel(modal);
                showToast(profile.standardEnabled ? `⚡ Profil standard activé · Z applique « ${profile.name} ».` : 'Profil standard désactivé.');
                return;
            }
            if (action === 'reset-standard') {
                if (isAutoProfile(profile)) return;
                const okStd = await sonicFleetAsk(modal, { icon: '🗑', danger: true, title: 'Vider le profil standard', confirmText: 'Vider',
                    message: `Remettre à zéro le profil standard de « <b>${escapeHtml(profile.name)}</b> » et le désactiver ?<small>Les exceptions par coordonnée ne sont pas touchées.</small>` });
                if (!okStd) return;
                profile.standard = createEmptyReserve();
                profile.standardEnabled = false;
                saveFleetProfiles();
                modal.innerHTML = buildSettingsPanel();
                bindSettingsPanel(modal);
                showToast('Profil standard vidé et désactivé.');
                return;
            }
            if (action === 'add-profile') {
                const name = await sonicFleetAsk(modal, { icon: '＋', title: 'Nouveau profil', confirmText: 'Créer', input: true, placeholder: 'Nom du profil',
                    value: `Profil ${fleetProfiles.profiles.filter(p => !isAutoProfile(p)).length + 1}`,
                    message: 'Donnez un nom à ce profil de réserves.<small>Il aura son propre profil standard et ses exceptions par coordonnée.</small>' });
                if (!name?.trim()) return;
                const newProfile = createDefaultFleetProfile(name.trim());
                fleetProfiles.profiles.splice(Math.max(0, fleetProfiles.profiles.length - 1), 0, newProfile);
                fleetProfiles.activeProfileId = newProfile.id;
                saveFleetProfiles();
                modal.innerHTML = buildSettingsPanel();
                bindSettingsPanel(modal);
                return;
            }
            if (action === 'add-current') {
                const key = getCurrentMoonKey();
                if (!key) { showToast('SoNiC : coordonnée actuelle introuvable.', true); return; }
                createCoordinate(profile, key);
                saveFleetProfiles();
                modal.innerHTML = buildSettingsPanel();
                bindSettingsPanel(modal);
                openEditor(modal, key);
                return;
            }
            if (action === 'add-coordinate') {
                const key = await sonicFleetAsk(modal, { icon: '＋', title: 'Ajouter une coordonnée', confirmText: 'Ajouter', input: true, placeholder: '1:123:7', value: getCurrentMoonKey() || '',
                    message: 'Coordonnée de la PDS à configurer.<small>Format galaxie:système:position (ex. 1:123:7).</small>' });
                if (!key || !/^\d+:\d+:\d+$/.test(key.trim())) { if (key) showToast('Coordonnée invalide.', true); return; }
                const normalized = key.trim();
                createCoordinate(profile, normalized);
                saveFleetProfiles();
                modal.innerHTML = buildSettingsPanel();
                bindSettingsPanel(modal);
                openEditor(modal, normalized);
                return;
            }
            if (action === 'delete-coordinate') {
                if (isAutoProfile(profile)) return;
                if (!coordinate || !profile.coordinates[coordinate]) return;
                const okDel = await sonicFleetAsk(modal, { icon: '🗑', danger: true, title: 'Supprimer la coordonnée', confirmText: 'Supprimer',
                    message: profile.standardEnabled === true ? `Supprimer le réglage spécifique de la PDS <b>${escapeHtml(coordinate)}</b> ?<small>Cette PDS utilisera de nouveau le profil standard.</small>` : `Supprimer la réserve de la PDS <b>${escapeHtml(coordinate)}</b> ?<small>Le profil standard est inactif : cette PDS ne sera plus configurée.</small>` });
                if (!okDel) return;
                delete profile.coordinates[coordinate];
                saveFleetProfiles();
                modal.innerHTML = buildSettingsPanel();
                bindSettingsPanel(modal);
                return;
            }
            if (action === 'rename') {
                if (isAutoProfile(profile)) { showToast('Le profil AUTO ne peut pas être renommé.', true); return; }
                const name = await sonicFleetAsk(modal, { icon: '✎', title: 'Renommer le profil', confirmText: 'Renommer', input: true, value: profile.name, message: `Nouveau nom pour « <b>${escapeHtml(profile.name)}</b> ».` });
                if (!name?.trim()) return;
                profile.name = name.trim();
                saveFleetProfiles();
                modal.innerHTML = buildSettingsPanel();
                bindSettingsPanel(modal);
                return;
            }
            if (action === 'save-profile') {
                saveFleetProfiles();
                modal.innerHTML = buildSettingsPanel();
                bindSettingsPanel(modal);
                showToast(`⚡ Profil « ${profile.name} » enregistré.`);
                return;
            }
            if (action === 'delete-profile') {
                if (isAutoProfile(profile)) { showToast('Le profil AUTO est permanent.', true); return; }
                if (fleetProfiles.profiles.filter(p => !isAutoProfile(p)).length <= 1) {
                    await sonicFleetAsk(modal, { icon: 'ℹ', title: 'Suppression impossible', confirmText: 'Compris', alertOnly: true, message: 'Il doit rester <b>au moins un profil</b> manuel. Créez-en un autre avant de supprimer celui-ci.' });
                    return;
                }
                const okProf = await sonicFleetAsk(modal, { icon: '🗑', danger: true, title: 'Supprimer le profil', confirmText: 'Supprimer le profil',
                    message: `Supprimer définitivement le profil « <b>${escapeHtml(profile.name)}</b> » ?<small>Son profil standard et ses ${Object.keys(profile.coordinates || {}).length} exception(s) par coordonnée seront perdus.</small>` });
                if (!okProf) return;
                fleetProfiles.profiles = fleetProfiles.profiles.filter(p => p.id !== profile.id);
                fleetProfiles.activeProfileId = fleetProfiles.profiles[0].id;
                if (fleetProfiles.zProfileId === profile.id) {
                    fleetProfiles.zProfileId = fleetProfiles.activeProfileId;
                }
                saveFleetProfiles();
                modal.innerHTML = buildSettingsPanel();
                bindSettingsPanel(modal);
                return;
            }
            if (action === 'editor-save') {
                const editor = modal.querySelector('[data-fleet-editor]');
                const key = editor?.dataset.coordinate;
                if (!key) return;
                const isStd = key === '__standard__';
                const reserve = isStd ? (profile.standard = normalizeReserve(profile.standard)) : createCoordinate(profile, key);
                if (isStd) { profile.standardEnabled = true; fleetProfiles.zProfileId = profile.id; }
                editor.querySelectorAll('[data-editor-ship]').forEach(input => {
                    reserve[input.dataset.editorShip] = Math.max(0, Math.floor(parseNumber(input.value)));
                });
                editor.querySelectorAll('[data-editor-res]').forEach(input => {
                    reserve['res_' + input.dataset.editorRes] = input.dataset.editorRes === 'lithium' ? 0 : Math.max(0, Math.floor(parseNumber(input.value)));
                });
                saveFleetProfiles();
                modal.innerHTML = buildSettingsPanel();
                bindSettingsPanel(modal);
                showToast(key === '__standard__' ? '⚡ Profil standard enregistré et activé.' : `⚡ Réserve ${key} enregistrée.`);
            }
        };
        modal.addEventListener('click', modal.__sonicFleetClick);

        if (modal.__sonicFleetBound) return;
        modal.__sonicFleetBound = true;
        modal.addEventListener('focusin', event => {
            if (event.target.matches('[data-editor-ship],[data-editor-res]')) event.target.value = parseNumber(event.target.value) || '';
        });
        modal.addEventListener('focusout', event => {
            if (event.target.matches('[data-editor-ship],[data-editor-res]')) event.target.value = formatNumber(parseNumber(event.target.value));
        });
        modal.addEventListener('mousedown', event => event.stopPropagation());
    }

    function openFleetProfileSettings() {
        try {
            injectStyles();
            const profile = getActiveFleetProfile();
            ensureLegacyJumpgateMigration(profile);
            document.getElementById('sonic-fleet-profile-settings')?.remove();
            const modal = document.createElement('div');
            modal.id = 'sonic-fleet-profile-settings';
            modal.innerHTML = buildSettingsPanel();
            document.body.appendChild(modal);
            bindSettingsPanel(modal);
        } catch (error) {
            console.error('[SoNiC Profils PDS] Ouverture impossible :', error);
            showToast(`SoNiC : ouverture impossible — ${error?.message || error}`, true);
        }
    }

    function showToast(message, warning = false) {
        let toast = document.getElementById('sonic-fleet-toast');
        if (!toast) {
            toast = document.createElement('div');
            toast.id = 'sonic-fleet-toast';
            Object.assign(toast.style, { position:'fixed', left:'50%', bottom:'22px', transform:'translateX(-50%)', zIndex:'2147483001', padding:'9px 15px', borderRadius:'3px', font:'11px Arial,sans-serif', color:'#fff', boxShadow:'0 5px 20px rgba(0,0,0,.55)' });
            document.body.appendChild(toast);
        }
        toast.style.background = warning ? '#5a2528' : '#173d29';
        toast.style.border = warning ? '1px solid #93464b' : '1px solid #4b9d6a';
        toast.textContent = message;
        clearTimeout(toast._timer);
        toast._timer = setTimeout(() => toast.remove(), warning ? 3000 : 1800);
    }

    function isTypingTarget(element) {
        const tag = element?.tagName?.toLowerCase();
        return tag === 'input' || tag === 'textarea' || tag === 'select' || !!element?.isContentEditable;
    }

    function getNativeShipInputs() {
        const form = document.getElementById('jumpgateForm');
        if (!form) return [];
        return SHIPS.map(ship => {
            const input = form.querySelector(`input[name="ship_${ship.ogameId}"]`) || form.querySelector(`input[name="${ship.ogameId}"]`);
            return input ? { ...ship, input } : null;
        }).filter(Boolean);
    }

    function readInputNumber(input) {
        if (!input) return 0;
        return Math.max(0, parseNumber(input.value));
    }

    function dispatchNativeShipValue(input, value) {
        input.value = String(Math.max(0, Math.floor(value)));
        input.dispatchEvent(new Event('input', { bubbles: true }));
        input.dispatchEvent(new Event('change', { bubbles: true }));
        input.dispatchEvent(new Event('keyup', { bubbles: true }));
    }

    function applyCurrentProfileToJumpGate() {
        const form = document.getElementById('jumpgateForm');
        const profile = getZFleetProfile();
        const coordinate = getCurrentMoonKey();
        if (!form || !profile) {
            showToast('SoNiC : la Porte de saut native n’est pas ouverte.', true);
            return false;
        }
        if (!coordinate) {
            showToast('SoNiC : impossible de déterminer la coordonnée de la PDS.', true);
            return false;
        }

        ensureLegacyJumpgateMigration(profile);
        const autoMode = isAutoProfile(profile);
        const nativeShips = getNativeShipInputs();
        if (!nativeShips.length) {
            showToast('SoNiC : aucun vaisseau natif détecté dans la PDS.', true);
            return false;
        }

        if (!autoMode && !resolveReserve(profile, coordinate)) {
            showToast(`SoNiC : aucune réserve configurée pour ${coordinate}.`, true);
            return false;
        }

        const availableById = {};
        nativeShips.forEach(ship => {
            const rel = parseNumber(ship.input.getAttribute('rel'));
            const current = readInputNumber(ship.input);
            availableById[ship.ogameId] = rel || current;
        });

        const totalResources = autoMode ? readCurrentBodyResources() : 0;
        let reserve;
        let autoDetails = null;
        if (autoMode) {
            autoDetails = computeAutoReserve(availableById, totalResources);
            reserve = autoDetails.reserve;
        } else {
            reserve = Object.assign({}, resolveReserve(profile, coordinate));
        }

        let carryNote = '';
        if (!autoMode) {
            const resLeft = RES_KEYS.filter(r => Number(reserve['res_' + r.id]) > 0);
            if (resLeft.length) {
                let carry = 0;
                resLeft.forEach(r => { carry += Math.max(0, readResourceValue(r.id) - Number(reserve['res_' + r.id])); });
                if (carry > 0) {
                    const free = {};
                    nativeShips.forEach(ship => { free[ship.ogameId] = Math.max(0, (availableById[ship.ogameId] || 0) - (Number(reserve[String(ship.ogameId)]) || 0)); });
                    const extra = computeAutoReserve(free, carry);
                    const added = [];
                    Object.keys(extra.reserve).forEach(id => {
                        const add = Number(extra.reserve[id]) || 0;
                        if (add > 0 && /^\d+$/.test(id)) { reserve[id] = (Number(reserve[id]) || 0) + add; added.push(`${formatNumber(add)} ${(SHIPS.find(x => String(x.ogameId) === id) || {}).short || id}`); }
                    });
                    if (added.length) carryNote = ` · +${added.join(' + ')} gardés pour emporter le surplus de ressources`;
                }
            }
        }
        let reservedTypes = 0;
        let totalReserved = 0;
        nativeShips.forEach(ship => {
            const available = availableById[ship.ogameId] || 0;
            const keep = Math.max(0, Math.floor(Number(reserve[String(ship.ogameId)]) || 0));
            const jumpCount = Math.max(0, available - keep);
            if (keep > 0) {
                reservedTypes++;
                totalReserved += Math.min(available, keep);
            }
            dispatchNativeShipValue(ship.input, jumpCount);
        });

        if (autoDetails) {
            const parts = autoDetails.allocation.map(item => `${formatNumber(item.kept)} ${item.shipId === 203 ? 'GT' : item.shipId === 202 ? 'PT' : 'PF'}`);
            const coverage = autoDetails.uncovered > 0
                ? ` ⚠ ${formatNumber(autoDetails.uncovered)} ressources sans capacité`
                : '';
            showToast(`⚡ AUTO ${coordinate} : ${parts.length ? 'réserve ' + parts.join(' + ') : 'aucun cargo à laisser'} · ${formatNumber(totalResources)} ressources${coverage}`);
        } else {
            showToast(`⚡ ${coordinate} : profil appliqué · ${reservedTypes} types · ${formatNumber(totalReserved)} vaisseaux conservés${carryNote}.`);
        }
        return true;
    }

    // Bouton « Profil » : centré entre « Choisir tous les vaisseaux » et « Réinitialiser la sélection », à la hauteur de ces boutons.
    function positionNativeJumpGateProfileButton(button, form, sendAll) {
        if (!button || !form || !sendAll) return;
        const formRect = form.getBoundingClientRect();
        const sendRect = sendAll.getBoundingClientRect();
        let reset = null;
        try { reset = form.querySelector('#resetall, .js_resetAll, #reset, a[onclick*="reset" i]') || null; } catch (_) {}
        if (!reset) {
            const links = Array.from(form.querySelectorAll('a')).filter(a => a !== sendAll && a !== button && a.offsetParent !== null && !a.id.startsWith('sonic-'));
            reset = links.find(a => a.getBoundingClientRect().left > sendRect.right - 2 && Math.abs(a.getBoundingClientRect().top - sendRect.top) < 20) || null;
        }
        const h = Math.max(18, Math.min(30, Math.round((sendRect.height || 24) - 2)));
        const w = Math.round(h * 1.75);
        // Les deux boutons natifs se touchent : on décale « Réinitialiser » vers la droite pour libérer la place du bouton Profil, sans chevauchement.
        let shift = 0;
        if (reset) {
            reset.style.transform = '';
            const rr0 = reset.getBoundingClientRect();
            const gap = rr0.left - sendRect.right;
            const need = w + 10;
            if (gap < need) { shift = Math.ceil(need - gap); reset.style.transform = `translateX(${shift}px)`; }
        }
        button.style.setProperty('width', w + 'px', 'important');
        button.style.setProperty('height', h + 'px', 'important');
        // Zone utile de la planche (liserés blancs et gris exclus) : 854 x 471 px, mise à l'échelle du bouton.
        button.style.setProperty('--sonic-pds-kx', String(w / 854));
        button.style.setProperty('--sonic-pds-ky', String(h / 471));
        let left;
        if (reset) {
            const rr = reset.getBoundingClientRect();   // position déjà décalée
            left = ((sendRect.right + rr.left) / 2 - formRect.left) - w / 2;
        } else left = sendRect.right - formRect.left + 14;
        const top = (sendRect.top - formRect.top) + (sendRect.height - h) / 2;
        button.style.left = `${Math.round(Math.max(4, left))}px`;
        button.style.top = `${Math.round(Math.max(0, top))}px`;
    }

    function injectNativeJumpGateProfileButton() {
        injectStyles();
        const form = document.getElementById('jumpgateForm');
        if (!form) return false;

        injectNativeJumpGateTargetPanel();

        const sendAll = form.querySelector('#sendall');
        if (!sendAll) return true;

        form.querySelectorAll(
            '#sonic-jumpgate-profile-btn, #sonic-jumpgate-config-btn, .sonic-jumpgate-profile-btn, .sonic-jumpgate-config-btn, .sonic-jumpgate-profile-icon, .sonic-jumpgate-profile-label'
        ).forEach(el => el.remove());

        if (getComputedStyle(form).position === 'static') form.style.position = 'relative';

        const profileButton = document.createElement('a');
        profileButton.href = 'javascript:void(0);';
        profileButton.id = 'sonic-jumpgate-profile-btn';
        profileButton.className = 'sonic-jumpgate-profile-image-btn tooltip js_hideTipOnMobile';
        profileButton.title = 'Appliquer le profil SoNiC actif';
        profileButton.setAttribute('role', 'button');
        profileButton.setAttribute('aria-label', 'Appliquer le profil SoNiC actif');
        profileButton.dataset.sonicPdsImageVersion = 'v2';
        profileButton.classList.add('sonic-pds-chev');
        if (window.SONIC_ASSETS.profileSprite) {
            profileButton.classList.add('sonic-pds-chev-img');
            profileButton.style.setProperty('--sonic-pds-sprite', `url(${window.SONIC_ASSETS.profileSprite})`);
        } else profileButton.innerHTML = '<span aria-hidden="true">»»»</span>';
        profileButton.addEventListener('click', event => {
            event.preventDefault();
            event.stopPropagation();
            syncFleetProfilesFromStorage();
            applyCurrentProfileToJumpGate();
            profileButton.classList.add('sonic-pds-pressed');
        });
        // Retour à l'état « au repos » quand la sélection est réinitialisée ou entièrement remplacée.
        form.addEventListener('click', (ev) => {
            const t = ev.target instanceof Element ? ev.target.closest('a,button,input') : null;
            if (t && t !== profileButton && !t.id.startsWith('sonic-')) profileButton.classList.remove('sonic-pds-pressed');
        }, true);
        form.appendChild(profileButton);
        positionNativeJumpGateProfileButton(profileButton, form, sendAll);

        setTimeout(() => positionNativeJumpGateProfileButton(profileButton, form, sendAll), 350);
        return true;
    }

    function findJumpGateTrigger() {
        const selectors = ['#jumpgateOpenOverlay','[data-ipi-hint*="jumpgate" i]','a[href*="component=jumpgate"]','[onclick*="jumpgate" i][onclick*="display" i]','[data-action*="jumpgate" i]'];
        for (const selector of selectors) {
            try { const el = document.querySelector(selector); if (el) return el; } catch (_) {}
        }
        const candidates = Array.from(document.querySelectorAll('a,button,input[type="button"],input[type="submit"],li,div'));
        return candidates.find(el => {
            const text = (el.textContent || el.value || '').trim().toLowerCase();
            return text === 'porte de saut' || text === 'jump gate';
        }) || null;
    }

    function openJumpGateShortcut() {
        document.getElementById('sonic-fleet-profile-settings')?.remove();
        const form = document.getElementById('jumpgateForm');
        if (form) {
            injectNativeJumpGateProfileButton();
            return true;
        }
        const trigger = findJumpGateTrigger();
        if (trigger?.click) {
            trigger.click();
            waitForNativeJumpGate();
            return true;
        }
        return false;
    }

    function waitForNativeJumpGate(timeout = 2200) {
        if (!document.body) return;
        const started = Date.now();
        let attempts = 0;
        const tick = () => {
            attempts++;
            const form = document.getElementById('jumpgateForm');
            if (form) injectNativeJumpGateProfileButton();
            if ((form && form.querySelector('#sonic-jumpgate-target-panel')) || Date.now() - started >= timeout || attempts >= 28) return;
            setTimeout(tick, 80);
        };
        tick();
    }

    const skMatch = (id, event, def) => window.SoNiCShortcuts ? window.SoNiCShortcuts.matches(id, event) : event.key.toLowerCase() === def;
    function handleFleetProfileShortcut(event) {
        if (event.ctrlKey || event.altKey || event.metaKey || event.repeat || isTypingTarget(event.target)) return;
        const isConfig = skMatch('gateConfig', event, 'v');
        const isApply = skMatch('gateApply', event, 'z');
        if (!isConfig && !isApply) return;
        const form = document.getElementById('jumpgateForm');
        if (!form) return;
        event.preventDefault();
        event.stopImmediatePropagation();
        if (isConfig) { openFleetProfileSettings(); return; }
        syncFleetProfilesFromStorage();
        injectNativeJumpGateProfileButton();
        applyCurrentProfileToJumpGate();
    }

    function handlePlanetToMoonShortcut(event) {
        if (event.ctrlKey || event.altKey || event.metaKey || event.repeat || isTypingTarget(event.target)) return;
        if (!skMatch('planetToMoon', event, 'l')) return;

        const currentCp = new URLSearchParams(window.location.search).get('cp');
        if (!currentCp) return;

        const currentMoon = Array.from(document.querySelectorAll('#planetList .moonlink')).some(link => {
            try {
                return new URL(link.getAttribute('href') || '', window.location.href).searchParams.get('cp') === currentCp;
            } catch (_) { return false; }
        });
        if (currentMoon) return;

        let moonLink = null;
        const rows = document.querySelectorAll('#planetList .smallplanet');
        for (const row of rows) {
            const planetLink = row.querySelector(':scope > a.planetlink');
            const href = planetLink?.getAttribute('href');
            if (!href) continue;
            try {
                const rowCp = new URL(href, window.location.href).searchParams.get('cp');
                if (rowCp === currentCp) {
                    moonLink = row.querySelector(':scope > a.moonlink');
                    break;
                }
            } catch (_) {}
        }

        if (!moonLink) return;
        const moonHref = moonLink.getAttribute('href');
        if (!moonHref) return;

        try {
            const moonUrl = new URL(moonHref, window.location.href);
            const moonCp = moonUrl.searchParams.get('cp');
            if (!moonCp) return;

            event.preventDefault();
            event.stopImmediatePropagation();

            const current = new URL(window.location.href);
            const target = new URL(moonUrl.href);
            if (current.searchParams.has('component')) {
                target.searchParams.set('component', current.searchParams.get('component'));
            }
            target.searchParams.set('page', 'ingame');
            target.searchParams.set('cp', moonCp);
            window.location.href = target.toString();
        } catch (_) {}
    }

    function handleJumpGateShortcut(event) {
        if (event.ctrlKey || event.altKey || event.metaKey || event.repeat || isTypingTarget(event.target)) return;
        if (!skMatch('gateOpen', event, 'p') && !skMatch('gateAll', event, 'a')) return;
        const key = skMatch('gateOpen', event, 'p') ? 'p' : 'a';

        if (key === 'p') {
            const form = document.getElementById('jumpgateForm');
            if (form) {
                injectNativeJumpGateProfileButton();
                event.preventDefault();
                event.stopImmediatePropagation();
                return;
            }
            let trigger = document.getElementById('jumpgateOpenOverlay') || findJumpGateTrigger();

            if (trigger && typeof trigger.click === 'function') {
                event.preventDefault();
                event.stopImmediatePropagation();
                trigger.click();
                waitForNativeJumpGate(3000);
                return;
            }

            return;
        }

        const form = document.getElementById('jumpgateForm');
        if (!form) return;
        if (key === 'a') {
            const sendAll = form.querySelector('#sendall');
            if (!sendAll) return;
            event.preventDefault();
            event.stopImmediatePropagation();
            sendAll.click();
        }
    }


    // ===== Rechargement de la porte de saut : halo rouge sur les coordonnées activées =====
    const GATE_COOLDOWN_KEY = 'SoNiC_Suite_JumpGateCooldowns_v1';
    // Recharge de la PDS : 1 h divisée par la vitesse de flotte de l'univers (x2 → 30 min). Surcharge possible : localStorage.SoNiC_GateCooldownMin
    try { if (!localStorage.getItem('SoNiC_Suite_JumpGateFix_v4')) { ['SoNiC_Suite_JumpGateByLevel_v1', 'SoNiC_Suite_JumpGateLearned_v1', GATE_COOLDOWN_KEY].forEach(k => localStorage.removeItem(k)); localStorage.setItem('SoNiC_Suite_JumpGateFix_v4', '1'); } } catch (_) {}
